window.POEM_DB=window.POEM_DB||{};POEM_DB["song_045"]={"n":"许及之","dyn":"宋","poems":[{"t":"白山茶","f":"五言律诗","c":["白茶诚异品，天赋玉玲珑。","不作烧灯焰，深明韫椟功。","易容非世力，幻质本春工。","皓皓知难污，尘飞漫自红。"]},{"t":"北方馆驲屏风皆画落墨牡丹","f":"七言绝句","c":["停车京洛净风沙，几见屏开落墨花。","故国似人犹可喜，秾肌何况谢铅华。"]},{"t":"白沟河","f":"七言绝句","c":["艺祖怀柔不耀兵，白沟如带作长城。","太平自是难忘战，休恨中间太太平。"]},{"t":"白龟","f":"五言绝句","c":["物有为身累，龟灵却受钻。","毛公今放汝，珍重保身安。"]},{"t":"百结","f":"五言绝句","c":["丁香从百结，恨只满东风。","未必愁能解，虚传酒有功。"]},{"t":"柏乡县","f":"七言绝句","c":["昔贤不肯入朝歌，况乃军中忌讳多。","咄咄衣冠出疆去，迫于人处竟成讹。"]},{"t":"斑竹","f":"五言绝句","c":["自得湘江种，禽栖不敢弹。","怕摇枝上露，犹是泪琅玕。"]},{"t":"跋谏长画轴后五王按乐图","f":"七言绝句","c":["玉笛床头取次横，自吹头管按新声。","梨园旧谱今何在，一段风流画得成。"]},{"t":"矮桃","f":"五言绝句","c":["花叶自低昂，攀折人不舍。","偷实定短人，朔辩愧黄马。"]},{"t":"碧芦步","f":"五言绝句","c":["霜叶彫残芰，寒花发旧芦。","一秋明眼处，落雁惠崇图。"]},{"t":"避雨渔阳太守庙","f":"七言绝句","c":["拂面秋风云漠漠，伤心古汴黍离离。","不因避雨渔阳庙，争见元丰大观碑。"]},{"t":"百七丈和篇有尽道温柔别有乡谁知绛阙水茫茫之句意有属也再用韵奉酬 其一","f":"七言律诗","c":["仙凡从昔各为乡，弱水蓬莱隔混茫。","不见麻姑呈狡狯，空教贺老号清狂。","两奁心事无人共，万点花飞有底忙。","说与东风须作主，莫教痴白妒娇黄。"]},{"t":"百七丈和篇有尽道温柔别有乡谁知绛阙水茫茫之句意有属也再用韵奉酬 其二","f":"七言律诗","c":["休厌黄鹂百啭声，诗翁亦是不平鸣。","中年怀抱愁离别，暇日亲朋好会并。","踏损落红无锦袜，吟成白雪有朱英。","栏杆徙倚空三叹，雨后斜阳写不成。"]},{"t":"百七丈寒食扁舟之盟遽寒姚黄恐成轻负辄赋二篇复以酴醾为约 其二","f":"七言律诗","c":["连夕惊雷非恶声，池塘閤閤几蛙鸣。","春程尚有三之一，乐事那能四者并。","养得苔钱都满砌，足为花地藉残英。","闻閒不惜冲泥过，架上酴醾玉已成。"]},{"t":"百七丈寒食扁舟之盟遽寒姚黄恐成轻负辄赋二篇复以酴醾为约 其一","f":"七言律诗","c":["閒中直指醉为乡，寒食扁舟竟渺茫。","可惜海棠随雨过，犹怜粉蝶伴醒狂。","游人静后西山好，春事深来老圃忙。","未必烦公频折简，花时还是负姚黄。"]},{"t":"被旨祈祷数至天竺圭僧录求白云堂诗为赋唐律一首","f":"七言律诗","c":["白云峰下白云堂，堂上高人一办香。","绕殿持经山四合，缭墙行道木千章。","众生未免婴时苦，大士宁能与世忘。","祈雨祈晴来复去，此身却似白云忙。"]},{"t":"鲍融州病足叩谒适遇孝若示融州菊诗和篇次韵呈","f":"七言律诗","c":["不见融州夏涉秋，居然款对豁羁愁。","犹存尊足怜同病，不系虚舟任打头。","久待一州当敛惠，终烦诸野要营求。","我今不啻便应足，独恨于君百未酬。"]},{"t":"白石榴","f":"五言绝句","c":["花开水晶瓶，叶排青琐窗。","枝红立白帜，蝶阵垂翅降。"]},{"t":"跋宋朝老再和陶渊明归去来辞","f":"五言古诗","c":["吾乡说三宋，伯也抱奇伟。","太学三十年，不作举子语。","晚当拜特恩，青衫送还官。","开口论世事，有舌不可扪。","吾皇开寿域，汪濊泽万国。","勉公俯而就，如女有正色。","翻然感际会，千载今一时。","谁欤俾宿留，再和归来辞。","渊明归有田，公归徒四壁。","姑奉祝融祠，胜煮南山石。","公乎未得第，我辈惭登科。","空飧了无补，奈此归来何。"]},{"t":"贺新郎","f":"词","c":["旧俗传荆楚。","正江城、梅炎藻夏，做成重午。","门艾钗符关何事，付与痴儿騃女。","耳不听、湖边鼍鼓。","独炷炉香熏衣润，对潇潇、翠竹都忘暑。","时展卷，诵骚语。","新愁不障西山雨。","问楼头、登临倦客，有谁怀古。","回首独醒人何在，空把清尊酹与。","漾不到、潇湘江渚。","我又相将湖南去，已安排、吊屈嘲渔父。","君有语，但分付。"]},{"t":"寄洪州新建知县","f":"七言律诗","c":["远听弦歌乐部封，放衙乘醉半疏慵。","家辞南越无千里，县管西山有几峰。","人望废田禾影合，吏愁空狱藓痕重。","孺亭应更悲前事，烟草萋萋叫夜蛩。"]},{"t":"新晴","f":"五言古诗","c":["连旬困梅霖，接夏潦乘溽。","泄云涣新霁，游兴难管束。","出关便航湖，停篙葑蒲绿。","渔歌入浦溆，沙禽乱惊浴。","昏霏送霞落，依稀辨林谷。","初更电辉摇，轻雷忽相续。","蛙声杂猛雨，波翻碎鸣玉。","何能足清睡，快举卮酒沃。","明朝看晨光，未必非所欲。"]},{"t":"次韵叶德友苦热吟","f":"五言古诗","c":["避暑本无法，有法心可移。","达尊迫人事，盛服严天威。","六月厉戈甲，百鍊亲炉锤。","前驱上峻坂，后鞭禁长吁。","正午万灶增，尅晷千夫炊。","辕门待排结，军令无徐舒。","陆浑救急燎，栾巴稽噀霏。","期以片时灭，不许一草萎。","醲赏激勇往，毕力争忘疲。","不计挥汗雨，宁思濯风漪。","当其用力所，岂复知热时。","万事心地存，百夫火宅驰。","四时更代谢，二至争愆逾。","积阴理必复，大夏阳常居。","及此当歊赩，岂得怀郁纡。","杜愿踏层冰，几欲投清池。","韩思坐深甑，为说亦岂疏。","极知隶元气，孰与逃象滋。","聊用供嘲咏，且以相戏娱。","吾侪幸安适，家食饕委蛇。","念彼方热耘，焉能思逃虚。","静胜昔人心，屡空斯晏如。","况予负深谴，省咎阖重扉。","友朋相急难，往复通有无。","每怀子叶子，久与期襟期。","有此苦热吟，句韵两崛奇。"]},{"t":"喜雨次韵翁常之苦热吟","f":"五言古诗","c":["羲和不弭驭，炎帝方秉机。","孰不爱赵衰，谁肯触武威。","岂知铄金石，乃得齐璿玑。","鹿角甫云解，葵箑无停挥。","万宝成南讹，一枕安北扉。","殿閤施馀薰，茅茨溥增辉。","鼎鼎百年内，咄咄七十稀。","临流抒我怀，新浴振我衣。","雷雨急生凉，天恩觉沦肌。","诗来取静胜，句到不吾欺。","盛服思客位，重铠念边陲。","当暑如怀秋，秋至勿兴悲。"]},{"t":"再酬常之","f":"五言古诗","c":["理极终必复，孰逃造化机。","司夏流中气，执衡振严威。","有怀渴云霓，不愿雨珠玑。","油然起崚嶒，闪若惊霍挥。","嘉泽彻中霄，凉飙入重扉。","良苗固怀新，冶叶亦生辉。","从欲天匪私，屡丰古实稀。","垂老藉香火，凌晨肃裳衣。","百拜屈我躬，万感铭我肌。","兹生每有逢，末路敢为欺。","正尔饱丘壑，及此轸疆陲。","念终抱愧耻，已矣徒伤悲。"]},{"t":"中秋见怀","f":"五言古诗","c":["明月出海底，先照彤庭墀。","正以合德故，争效朝宗驰。","须臾散精彩，普率扬明辉。","常时或显晦，所历随茫瀰。","及兹秋中气，燎然光满规。","岂但碧汉澄，无复宿雾披。","如坐水晶宫，更泛碧琉璃。","凛凛栗肤发，炯炯析毫釐。","竟欲乘浮槎，试与穷垠涯。","或拟斫却桂，或云生桂枝。","蟾宫到者折，不生岂不稀。","玉斧修何事，倒即无倒期。","沉吟自绝倒，痛饮忘倾攲。","兹辰病因仍，良行觉支离。","始行浮云多，犹欲一口吹。","东床念斋夕，妙语寄相思。","词到律自协，意古趣更奇。","今虽减冰轮，犹照蘸甲卮。","寄声巷南翁，斯辰可无诗。","我欲资隽永，庶以得自颐。"]},{"t":"侍南轩先生卷云亭望岳麓积雪分韵得初作二字","f":"五言古诗","c":["新元既涉九，腊尾春未初。","司寒励馀职，飞雪来庭除。","因风稀复密，潜阴惨还舒。","瑞色入陇麦，祥膏润园蔬。","未足映书读，已宽带经锄。","和气融比屋，所积惟林庐。","怅焉起遐观，未知问所如。","南轩笑领客，操已敢作疏。","岂无门下生，不肯升篮舆。","冲泥按徐辔，秀句生蹇驴。","卷云毕清集，湖山眇开予。","蜿蜒翠麓中，万瓦参琼琚。","急扫供茗事，隔江竟烦渠。","终日乐未央，不为食有鱼。","十韵分九人，其一固闰馀。","并以属汰砾，敢下冯妇车。","屯云方杂沓，二白难踌躇。","须公专吟笔，载赓仍屡书。"]},{"t":"张时可席上喜雪分韵得水字时予后至周希稷期而不集","f":"五言古诗","c":["寒威逼重帏，皓彩堕庭戺。","不谓晦日愁，乃有丰年喜。","更长要深杯，客缓愧停己。","后来固自佳，不至犹可纪。","传香共分题，索笑惊落纸。","摩挲玉梅瓶，冻合西湖水。"]},{"t":"次韵黎师侯登王叔武文昌阁看雪","f":"五言古诗","c":["春雪如过客，所止留莫住。","但见空中驰，机心逐鸥鹭。","度腊凛馀寒，同云忽朝聚。","乍看鲛泣珠，渐觉柳飘絮。","少焉有矜色，琼枝斗玉树。","登临须胜流，著我觉形污。","北山鲜明姿，爱客急修具。","坐间两荆州，翛然隐风度。","更著老弥明，清谈屋瓴注。","客醉主亦欢，主醉客即去。","剥啄凤沼来，忽得石鼎句。","便可当画图，却将醒眼觑。"]},{"t":"次韵转庵用山谷半字韵见寄","f":"五言古诗","c":["居閒数相过，每语夜参半。","稍作一日疏，已起三秋叹。","老去惜光阴，欢来犹把玩。","去年掺袂别，转首抟沙散。","恍思麇鹿侣，岂是鸳鹭伴。","拂龟信逢辰，听鸡虞失旦。","冉冉金阶趋，穆穆玉皇案。","端笏俨一夔，曳履仪十乱。","咸德足享天，旅荐洁初盥。","疲驽亦自鞭，百驾祇恐缓。","以兹故山梦，累累若珠贯。","佳句自山来，居然起衰愞。","平生锦绣肠，不复置冰炭。","室迩犹远思，迢迢况闽馆。","加意松柏姿，聊逐桑榆暖。","归投玉女壶，天当一笑粲。"]},{"t":"次韵书怀","f":"五言古诗","c":["世味真嚼蜡，閒趣觉隽永。","闭门读旧书，拓牖豁微囧。","窥道忘一斑，反身得三省。","佳人不可招，妙处谁与领。","未刖聊晨门，已献那泣郢。","向来真左计，只合事幽屏。","感君汪洋陂，洗我荣辱境。","逢原得新功，馀润及古井。","笔端有辘轳，句法见驰骋。","梅花动乡思，霜风吹鬓影。","言归日在念，未策心已警。","咫尺看白云，祇隔冯公岭。"]},{"t":"次韵酬徐居厚寺簿","f":"五言古诗","c":["度江见三白，飞雪为谁妍。","因山行毕役，忧国且愿年。","眷言灵驾发，绵延属车骈。","阳侯既效职，滕六敢自贤。","阁阴不忍下，竣事即堕前。","山林亦缟衣，挥洒纷素筵。","似与孤臣泪，同作珠贝编。","岂无访戴舟，拘文不容牵。","感君相料理，语妙堪流涎。","奈何补天手，袖此鉴湖堧。","不受邻僧米，颜公合忧煎。","挼挲映雪眼，纵臾吟诗肩。","同时天下名，一日方九迁。","君不策高足，馀子烦后鞭。"]},{"t":"再用韵","f":"五言古诗","c":["正士如正色，耻与俗竞妍。","老成信迟钝，阿婆曾少年。","斯人寄閒地，宇宙岂赘骈。","向来驰天壤，谁者相愚贤。","我欲从之游，每恨不得前。","兹行本尸祝，代庖误当筵。","高轩既枉过，妙语亦盈编。","受施不知报，力疾可复牵。","风雪久为虐，江湖长蛟涎。","天岂困男儿，地阙东南堧。","惟有皎洁姿，不受寒暑煎。","勉子加餐饭，行行盍仔肩。","时哉有通塞，道岂随变迁。","愿将钓竿手，一为公执鞭。"]},{"t":"王弱翁同年以多病故人疏韵五诗为惠次韵奉酬 其一","f":"五言律诗","c":["王君圭璋姿，宜在条理科。","妙语天发成，瑩彻非砻磨。","宗庙要琬琰，世岂无卞和。","顾恐太分明，颇觉瓦砾多。"]},{"t":"王弱翁同年以多病故人疏韵五诗为惠次韵奉酬 其二","f":"五言律诗","c":["斯文万金药，不救俗儒病。","卢生谁云邪，夫子未出正。","羊肠驾觭轮，鲸澜溯孤榜。","噫乎吾道难，自古斗衰盛。"]},{"t":"王弱翁同年以多病故人疏韵五诗为惠次韵奉酬 其三","f":"五言律诗","c":["江水日万折，衮衮望东注。","饥鸢无停飞，不足了雏哺。","君看青紫绶，但供折腰具。","物理信如此，焉敢辞世故。"]},{"t":"王弱翁同年以多病故人疏韵五诗为惠次韵奉酬 其四","f":"五言律诗","c":["叶脱秋色静，水落洲渚陈。","文昌易为月，翩翩欲相亲。","蝉声老逾夏，乍听意觉新。","此时酒一尊，不可无此人。"]},{"t":"王弱翁同年以多病故人疏韵五诗为惠次韵奉酬 其五","f":"五言律诗","c":["心竞事未已，趣了计有馀。","彭泽八十日，便可膏吾车。","趣时方枘拙，涉世孤舟虚。","君无攻我短，政尔吾太疏。"]},{"t":"直舍考校次弱翁再用前韵 其一","f":"五言律诗","c":["胸中无渭泾，笔下安诠科。","糊名彊别白，朱丹困研磨。","传诗得建安，妙画追永和。","快读洗我怀，珠玑拾何多。"]},{"t":"直舍考校次弱翁再用前韵 其二","f":"五言律诗","c":["我句芜陋质，聊学捧心病。","君诗婉娈容，毅然色更正。","唱叹朱弦音，流喝清池榜。","足亢江西宗，它年耳孙盛。"]},{"t":"直舍考校次弱翁再用前韵 其三","f":"五言律诗","c":["官冷得酒钱，便欲糟床注。","不管门东儿，张颐须咽哺。","堪笑布裙妇，遮藏备修具。","君自不纡轸，何止倾盖故。"]},{"t":"直舍考校次弱翁再用前韵 其四","f":"五言律诗","c":["夜读举子语，戛戛务去陈。","唤起场屋梦，倍觉灯火亲。","科第计谓了，痴儿事方新。","寄言山内友，勿念尘中人。"]},{"t":"直舍考校次弱翁再用前韵 其五","f":"五言律诗","c":["堆案即姑置，栖息万籁馀。","阶除勃窣行，两脚当我车。","径欲烦客卿，相从赋子虚。","曲生不可招，坐令此计疏。"]},{"t":"转庵集客分韵得作字见示次韵奉酬","f":"五言古诗","c":["转庵诗老手，久不见近作。","尚友喜文会，分韵得真乐。","联翩来巨轴，淋漓想酬酌。","异味非五鲭，良裘岂一貉。","有如得良剂，居然起深瘼。","虽微与兹集，所得良不薄。","山王果为累，竹林诚可略。","何妨赘赓酬，聊复资戏谑。","永言相忘友，久要欣有托。","后当不如今，今可不悟昨。","亦欲见真率，正须先宿诺。","少待天气凉，伟观洒高阁。"]},{"t":"转庵再用作字韵见酬有蓍蔡休咎之语复韵为答","f":"楚辞体","c":["步蹇无良行，思苦乏新作。","虫声徒自切，我病有何乐。","言写纾短怀，深汲难远酌。","敢嗟凤兮凤，正惭貉非貉。","诗家有医王，同社求句瘼。","固不相短长，祇恐自鄙薄。","胡为作蚁梦，乃欲谈豹略。","此意诚起懦，斯言几善谑。","天幸吾已数，人生归有托。","居然成老丑，何者裨画诺。","知予与罪予，并束春秋阁。"]},{"t":"次韵滕丞以古风为贽","f":"五言古诗","c":["松柏覆高冈，根株渗七泽。","雪霜有古今，柯叶无改易。","上干青云霄，下庇神龙宅。","哕哕朝阳鸣，杳杳逢堵迹。","五色绚文章，八音谐金石。","群飞竞婆娑，争附第充斥。","匠石既罕遇，社栎顾何益。","伶伦不雌雄，嶰竹杂蝼蝈。","蓝田惊世瑞，造物等儿剧。","昨曾窥斓斑，今犹眩朱碧。","居然获径寸，几欲按三尺。","久之置怀袖，尚尔赊踧踖。","姑凭副墨子，往备庚桑役。"]},{"t":"陈西老咏桧古风次韵","f":"五言古诗","c":["古井千尺深，而无一寸波。","古桧荫其旁，愔愔长铜柯。","明堂一柱难，如此梁栋何。","匠石久袖手，高岑郁峨峨。","天风一披拂，剑佩相戛磨。","不愿为阿房，千门贮秦娥。","愿作寒士庇，渠渠共婆娑。","吁嗟不相贷，飞轮迫羲和。","谁欤荐轮囷，万牛未为多。"]},{"t":"次韵陈大用分韵得对字","f":"五言古诗","c":["离群易兴怀，会面即忻对。","兹岂非人情，况复是吾辈。","稍稍不晤语，毣毣已心愦。","世态炎复凉，画事素先缋。","馀子纷珷玞，良友抵珍琲。","仲方真小难，煮糜是所爱。","有作窥古淡，如女洗妆黛。","亦尝和宫徵，惜不听环佩。","是举终当了，此事可使废。","转庵传分韵，容成忆同载。","肝胆徒轮囷，酬酢任瑕类。"]},{"t":"次韵陈大用","f":"五言古诗","c":["林峦迫摇落，卉木见槎梗。","物当各归根，人盍思退省。","我今幸投閒，日力竞俄顷。","阖户思寡过，出户忘造请。","第知龟藏六，大似蛙坎井。","佳客车枉门，好语裘挈领。","遽发醯鸡覆，如脱孤㹠阱。","见道乏新硎，导窾昧微綮。","元方擅能事，转庵互规警。","倡酬传五字，玩味消百眚。","盘餐共粗粝，轩窗临阒静。","恨方厉霜风，惜不行蔗境。","何当历崟岑，相与忘畛町。","江山开伟观，华盖登绝顶。"]},{"t":"与同社游山园次翁常之韵","f":"五言古诗","c":["眷言太玉峰，本是仙佛宅。","端视俨若屏，侧睨展如翼。","洞府何渺茫，传闻见图画。","疆理虽东瓯，题品经谢客。","至今味篇咏，当时想游历。","顾我本萍泛，买邻寓栖息。","江山自呈露，卉木因种植。","凿岩得泉香，拓户见山色。","佳客入庭户，英气来几席。","幽葩芬石根，好鸟弦坐侧。","拄笏山之西，拿舟江以北。","明月浮可捉，疏星挂堪摘。","拂晨天宇净，出海阳乌赤。","脩岚烁紫翠，远目眩朱碧。","崚嶒双塔影，突兀古殿脊。","媚川溟渤宽，绝境天地窄。","前贤未尝亡，胜趣何有极。","兹时届清和，同社共推激。","肯为终日留，喜免重城隔。","长歌响林坰，妙语出金石。","尔汝合忘形，拘挛非远识。","莫嗔惊著汝，试问今何夕。","曹刘墙可短，丘崖肩可拍。","却笑山阴会，翻悲昔人迹。","喻指孰非是，计马谁失得。","明当新诗来，勿惮难韵迫。","趣归不匆忙，馀兴犹襞积。","感君吐琼瑰，为我写胸臆。"]},{"t":"六月十五日西湖夜泛高炳如集客赵临安蟠老致饷同游者陈可行杨少云李元德王顺伯何绍彭张宗尹杨氏子弟侍僧方与焉次炳如韵","f":"五言古诗","c":["西湖著明月，万象各偃伏。","夙昔湖上游，赓酬动盈束。","未有夜泛诗，此诺吾屡宿。","剥啄闻招呼，纵臾戒行速。","读君纸三过，洗我愁万斛。","行行正作意，在在堪刮目。","山光真起予，过雨俨新浴。","精蓝憩深幽，疏篁庇脩绿。","棋声节风瓯，参差自成曲。","睡乍味觉甜，语软气能馥。","老僧与客忘，谛紬楞严轴。","小立水花净，一堤良意足。","方舟晓兴动，篙人听回复。","薰风散金波，心境两愁独。","是中有妙句，万古无管属。","诗家高书记，前赵今鲍叔。","归来要推敲，遣饷到林谷。","陈榻初解悬，膺门契仍笃。","不遗太学蕃，王杨共高躅。","陆笑阿戎谈，足以侍几牍。","支郎更可人，啖蔬如啖肉。","而我厕髯张，形骸愧珠玉。","敢逃清白眼，仅免朱丹毂。","明朝软红中，清游梦应续。","未叹终滞淹，湖山已收录。"]},{"t":"次韵薛子明由罗浮登富览","f":"五言古诗","c":["罗浮映挂綵，富览游兹亭。","地非南海峤，山结北斗城。","双鳌插奔澜，万峰若屯营。","往复信潮汐，日夜归沧溟。","沙涨陵谷移，水落洲渚横。","谢客纾目力，郭公参地形。","夫君有心哉，象纬罗中扃。"]},{"t":"次韵薛子明赋雪渊寒瀑","f":"五言古诗","c":["南山阻且秀，三峰屹而挺。","笙跨夜鹤声，松纳古潭影。","珍潜滃无眹，樵涉深及胫。","星娥閟灵踪，月卿探幽屏。","同气想飞霞，相过谈倒景。","傥遇莲叶舟，定自太华井。"]},{"t":"游石梁","f":"五言律诗","c":["天柱昔饱观，石梁今创见。","愧此叉枒姿，空费轮囷荐。","安得愚公移，往作灵光献。","突兀千里间，普适寒士愿。"]},{"t":"沈丈察院次游凤山韵见示再次韵奉酬","f":"五言古诗","c":["短思如枯蘖，不忘雨露滋。","一朝得甘霔，牙檗纷差差。","向来圯上编，敢孤老人期。","至今巾箧中，常觉律吕随。","风骨自难蜕，寸心恐终违。","苦语迫应酬，如醉多倾攲。","拟求风斤斲，庶使胶柱移。","遗以五色篇，服之欲生翚。","东隅纵已失，南车足占迷。","堂堂豸冠老，伟论堪扶危。","不妨似妩媚，正尔烦逶迤。","馀事出长技，传玩争矜持。","高吟有催和，好雨诚知时。","疲驽惧难驾，渴骥思脱羁。","行当遂远放，雁伴聊同栖。"]},{"t":"游道林岳麓寺 其一","f":"五言律诗","c":["幕府日多暇，而无簿书劳。","唤渡涉湘西，鼓枻歌离骚。","今日湖南山，领览归我曹。","颇觉叶舟稳，夷涂自风涛。"]},{"t":"游道林岳麓寺 其二","f":"五言律诗","c":["道林访幽栖，羁怀惬所尚。","岳麓振前策，盘纡得夷旷。","向来北山移，无物辞嘲谤。","见此意豁然，泉声助悲壮。"]},{"t":"游道林岳麓寺 其三","f":"五言律诗","c":["从昔游山人，留题尽名字。","壁昏暮鸦栖，石腻群鸿戏。","今人来更多，后观复长喟。","吾侪幸闻健，拄笏致爽气。"]},{"t":"游道林岳麓寺 其四","f":"五言律诗","c":["名山喻名理，妙处须独到。","提耳从百闻，岂尽历历告。","兹游太清绝，足以偿宿好。","相期岁寒姿，对此松柏操。"]},{"t":"曾主管由宜春道中得遗弃小儿属予收养道间寄诗纪实次韵奉酬","f":"词","c":["日月被八极，覆盆自无明。","阳春妪万物，孤翰有悲鸣。","所以圣明治，要烛幽隐情。","一旱出料外，谁与填饥坑。","豪家亦何心，闭籴门忍横。","指囷宽嗷嗷，凛若临大兵。","雨馀百忧洗，痛定犹忡怔。","今代子曾子，赞画外台清。","高轩昨过我，绝尘不容瞠。","归途出城闉，岸许闻啼婴。","下车非内交，一念千金轻。","摩挲脱九死，感慨恩更生。","抱持涉数舍，见我托此?。","再拜敢有渝，鞠养专厢荣。","嗟予何为者，世故亦饱更。","识君千万间，胸次久已成。","所饥非一儿，公乎勉功名。"]},{"t":"曾主管专介取弃儿再次前韵","f":"词","c":["自别心耿耿，奈此秋月明。","晨兴洗我耳，鹊鹊枝间鸣。","踵门得缄翰，中有恻怛情。","眷彼水际儿，感公脱危坑。","传之邑父老，相语涕泗横。","郑重烦取将，摩挲付老兵。","忌饱体未充，惯拊心无怔。","应答已如响，炯炯双眸清。","试问父母谁，惝恍目屡瞠。","微公父母恩，何以活此婴。","儿生未有知，阴报已不轻。","公犹不自德，安得名许生。","共惟仁圣朝，发政先鳏?。","吾侪值歉乏，讵敢孤官荣。","二星妙宣指，悉数仆屡更。","三接尚须臾，一路当生成。","况乃幕中画，实负当世名。"]},{"t":"湖上饯沈兴国分韵得二字","f":"五言古诗","c":["赤骥见已罕，名驹更兼值。","吾乡推贤侯，逢人话詹事。","讼简古风还，心清民业遂。","江山妙主盟，景物恢位置。","如何柱石姿，尚以牧伯寄。","北关别经年，南薰动离思。","居然软红中，见此清白似。","松筠俨长身，云霄舒直气。","宠光竹使符，假借玉阶地。","饷计曾入幕，军容有竑议。","恭闻天语温，喜见家学粹。","它时课最腾，看即玺书被。","今晨欣寿节，轻阴递凉吹。","三呼礼云毕，一笑天所施。","榴花染白云，游鯈芘青芰。","画舸得夷犹，名园随造次。","怀绶却羡君，戏彩且归侍。","不繇雁荡山，即过石门寺。","永嘉政久成，谢公迹重记。","剩有名诗章，因来寄一二。"]},{"t":"送盖总领上计三首 其一","f":"五言古诗","c":["绝代有佳人，岑楼碧岧峣。","即之起幽芬，可慕不可招。","风雨二十年，寒荣耸高标。","置之白玉堂，致主轩与尧。","胡为枉襆被，江干驾轻轺。","施物功方成，丹砂夜生苗。","披腹吐琳琅，碧简趋丹霄。"]},{"t":"送盖总领上计三首 其二","f":"五言古诗","c":["昔者云夙驾，杨柳方依依。","今其望来思，两见秋风吹。","前乎已劳还，后此亦云归。","丹笔映螭坳，祥风动紫微。","岂不念归美，正尔畏简书。","不见居官乐，惟忧士卒饥。","昔人无遗孔，后来补深痍。","炯炯心独苦，所贵知者希。"]},{"t":"送盖总领上计三首 其三","f":"五言古诗","c":["熠熠飞者萤，变化自衰草。","时至能晶荧，翕张合吾道。","微光苦不息，岂足裨穹昊。","迢迢风雨夕，耿耿祇自保。","苟无车先生，分合委枯槁。","乾死诚未悔，药笼资探讨。"]},{"t":"送孙会之县尉秩满归庐陵","f":"五言古诗","c":["人生贵相知，不在相逢早。","庐陵说三孙，修名惬诸老。","伯也吾同年，久别心杲杲。","季也真可人，一见颜色好。","金石出几杖，握手屡倾倒。","屈魂虽尚醒，贾骨久云槁。","微君写穷愁，何以慰怀抱。","再见一尉更，取别何草草。","回视徒四壁，蝉声缀吟藁。","向来雕斲工，见辄迹如扫。","汲深无新泉，送子惭涸潦。","珍重皎洁姿，相期在斯道。"]},{"t":"送赵倅秩满东归分韵得念字","f":"五言古诗","c":["官閒颇成赘，习懒积怀歉。","古井无复波，寒灰岂能焰。","苟且信自惭，奔竞亦良厌。","学道无新功，但觉益友欠。","夫君圭璋姿，表里绝瑕玷。","瓦砾诚可羞，温润得渐染。","向来三语称，吾里怀窥觇。","名谈造根柢，高文在铅椠。","转首十五年，天庭久宜掞。","胡然慰穷愁，相逢古天堑。","治中员外置，缩手靳韝䪜。","从容国医旁，出语即中砭。","邂逅秩云满，萧条理琴剑。","炯炯幽者兰，林深守孤艳。","宁受萧艾欺，忍使薋菉僣。","谁欤功名涂，由己拯昏垫。","小草非远志，臭味真有忝。","羞杀东方生，饥死更求赡。","因君动行李，令我起归念。","西山有石田，努力事耕敛。"]},{"t":"乞补外出江皋待命泊伟观二首 其一","f":"五言古诗","c":["经年充拾遗，一字无所补。","岂不怀故乡，念方事新主。","一朝冒超迁，循墙不遑处。","宁离人间世，亦恋行在所。","有亲方赖禄，有子方应举。","守道在守官，奈当事斯语。"]},{"t":"乞补外出江皋待命泊伟观二首 其二","f":"五言古诗","c":["欲去不得遂，正如太庙羊。","登俎分所宜，得去喜可量。","圣度真如天，不妨且翱翔。","扶老复携幼，迁居大江傍。","居然得伟观，怅焉渺遐荒。","潮头来如山，亲乐想未央。"]},{"t":"题廨舍壁二首 其一","f":"五言古诗","c":["明时有何遗，亦复许掇拾。","大言得面陈，小言可封入。","有时效疏愚，岂是当务急。","每蒙天下施，听之恐不及。","退思自生惭，黄卷常在执。","旧田虽甚芜，新井尚可汲。","勉哉竞斯辰，万一如有立。"]},{"t":"题廨舍壁二首 其二","f":"五言古诗","c":["本不事矰弋，未免执矢疑。","客来非不多，益友每远之。","薰风时一顾，素抱谁与期。","久要竹居叟，谈诗能解颐。","两颊贮微笑，径造观我私。","请解褦襶衣，相与举近诗。"]},{"t":"纶子效靖节止酒体赋筠斋余亦和而勉之","f":"五言古诗","c":["纶以筠名斋，种筠当掩关。","爱筠栽竹易，见竹知筠难。","竹以筠为本，筠居竹之间。","希筠岁寒操，追筠古风还。","筠中听瑟瑟，筠外泻潺潺。","人与筠俱胜，筠随境共閒。"]},{"t":"重题陈汉卿贫亦好斋","f":"五言古诗","c":["古人重安贫，未若贫而乐。","岂不爱膏粱，顾乃嗜藜藿。","我闻首阳饿，荣名千驷怍。","况乃陋巷子，箪瓢殊不恶。","刀头得几何，蜗角战方虐。","以兹悟生理，贫中始澹泊。","陈侯清时英，廊庙宜著脚。","圭窦势岂容，贫斋意聊托。","苍生方饥渴，未可云盘礴。","且来禄万钟，脱粟躬自薄。"]},{"t":"次韵常之松庐有感","f":"五言古诗","c":["年少爱节序，老大感岁时。","亦知夜漏短，自喜昼景迟。","怀人笏频拄，矫首帽屡攲。","至情何惨怆，同气相因依。","君家说大难，心胸缊多奇。","永欢思伐木，长歌倚式微。","眷言无雁地，渴想前鸿俱。","一别如昨日，二年忽今兹。","数传龟组解，备著鲈风词。","寒乡少瑞应，远览期长离。","解缆辞江皋，反袂接水湄。","无从犹出涕，有弟应垂洟。","今见松庐作，可胜薤露悲。","怜君抱苦节，爱兄见哀诗。","无复逝水向，当有高山知。","老惭无领解，久约同襟期。","勉和吹篪章，聊慰深长思。"]},{"t":"周时仲提干求二亲墓亭扁答以攀柏因为著语","f":"五言律诗","c":["扫松拜亲墓，攀柏念亲泣。","柏露滴儿衣，儿泪和露湿。","五鼎从可陈，三釜嗟何及。","坟前白颈鸦，终日声楂楂。"]},{"t":"次韵题吴无过所藏张无垢难老堂诗轴","f":"五言古诗","c":["养亲感卧冰，慕亲悲履霜。","眷兹母孙情，胚胎炳前光。","先生一奖励，吴氏增激昂。","至今诸孙行，如立严师傍。","躬行斯入室，言辞特滥觞。","当时五子名，佩服讵可忘。","省也滋拳拳，何止升其堂。"]},{"t":"次韵廖端叟求墨","f":"五言古诗","c":["忆昨同舍时，爱子志尚坚。","研穷非口耳，点勘分乌焉。","读声锵金石，笔思涌漪涟。","合并几寒暑，分散如云烟。","家虽才咫尺，见且无夤缘。","甥馆闻徙居，我屋欣接椽。","乃以随吏鞅，而叹抱遗编。","嗟哉燕鸿隔，漫尔夔蚿怜。","三年阅黄榜，万选遗青钱。","祇擅文场声，不上吏部铨。","儒冠未为误，洛诵方流传。","夏果烦送似，唐律仍灿然。","为墨贻古作，如珠出深渊。","书生均老丑，嗜好相后先。","亦有大禹圭，未许蒲氏贤。","何惜遗久交，相得真忘年。","久知铁为研，更以心自鞭。","矧古传毛颖，端合遗陈玄。","落笔看馀万，斗酒须十千。","虽无兰亭茧，愿助韦郎笺。","古今一俛仰，人墨相磨研。","有无要相通，唱和聊成篇。","我今辟三径，门开西一偏。","已过中秋月，皆为晚凉天。","何妨对花下，取笑同樽前。","第惭葵卫足，欲愈犹联拳。"]},{"t":"次韵德友惠黄雀","f":"五言古诗","c":["兴来把酒杯，径欲连台拗。","聊用资吟哦，岂谓贪醉饱。","晨起秋思清，茶罢诗肠搅。","筠斋伫远思，诗筒驰速巧。","饷我晚田雀，如鹰初脱爪。","惠我长城句，如栋略无桡。","雀命虽甚微，饥驱亦良挠。","何异不农耕，而乃窃禄稍。","哦诗思陶谢，论交怀管鲍。","只消寄诗篇，断不厌煎炒。"]},{"t":"再次大用韵赋梅花","f":"五言古诗","c":["暖律回枯荄，春阳发寒梗。","梅根有特操，花事每先省。","分苗本十洲，孕玉可千顷。","松篁纳深交，桃李绝奇请。","冬居姑射山，下荫太华井。","幽栖有心赏，巡檐常笑领。","相对各忘言，岂但无机阱。","诗虽道未尊，技可造经綮。","孤标固洗凡，累句自无警。","转庵诗家医，妙剂即苏眚。","元方诗家禅，默参惟打静。","欲离香色想，恐堕人我境。","昨夜来朔风，吹香过南町。","小解作浅语，醍醐欣灌顶。"]},{"t":"再次转庵用梗字韵赋梅","f":"五言古诗","c":["见梅思洛阳，何愁道路梗。","见雪忆灞桥，便可心思省。","仙家种玉成，造化炊粱顷。","凛然孤高标，敢以尘溷请。","将军有传令，遽成临渴井。","王言惟作命，盍作和羹领。","香色归本根，滋味岂机阱。","自非泯全牛，安得试尝綮。","转庵句中画，梅诗言外警。","难韵有辘轳，妙语压菑眚。","昨夜垂垂雨，一洗娟娟静。","便觉容成圃，真是太玉境。","朝来知见香，堕在区别町。","不如两忘言，搔首孤山顶。"]},{"t":"园丁以菊为屏为船转庵竹院谛赏不足分题得塔字","f":"五言古诗","c":["眷彼东篱花，忽作西灵塔。","又如船子泛，复似南屏阖。","园翁起童心，须弥欣芥纳。","分题要铿锵，饫秋振萧飒。","我合浮屠尖，工须画溪罨。","崚嶒玉崔嵬，团栾金匼匝。","俨然香色俱，间彼青黄杂。","天成具体相，人事因假合。","愿修衣裓供，用作布地蹋。","那将有漏身，久实无缝合。","转庵曾著语，竹院尝挂搭。","我有一句子，无问亦无答。"]},{"t":"德友惠竹栽甚富而又得佳篇既种复喜雨次韵谢之","f":"五言古诗","c":["嗜酒爱风竹，种竹涓日醉。","小园窘边幅，杂芳纷位置。","此君何可无，野卉辟之易。","亩许得滋旷，千个栽不翅。","故人虽借居，爱竹有幽致。","肯割钟山青，分植容成地。","移来天亦喜，凉生雨兼值。","既免躬抱瓮，何惜亲阅视。","飒爽已可人，能同听秋思。"]},{"t":"转庵观赵十一圣花","f":"五言古诗","c":["有艺者赵生，杂出逞活法。","飞走异族类，指教各驯狎。","参戏竿欲摧，险弄首将压。","当场等嬉笑，旁观举震霅。","其间圣花术，殆是天下甲。","出没鬼物惊，变幻风雨霎。","觌面唤名葩，信手如素插。","洞视空樊笼，赤立却巾帢。","居然龆龀儿，恍出虎兕柙。","脱索妇更神，倒锥目不眨。","穿杨百步间，设的两口夹。","一箭中关捩，四坐骇汗洽。","或驰若转轮，或舞若挥箑。","机缄孰主张，造化在嘘呷。","技进无万殊，妙用才一掐。","傥然自胡越，谁能会鄏郏。"]},{"t":"次转庵圣花韵","f":"五言古诗","c":["转庵诗三昧，仍嗜书八法。","写出金弹句，可玩不可狎。","近观圣花作，险若君独压。","壮如钱塘潮，清若苕溪霅。","僚丸同妙手，痀蜩真脱甲。","庖刀方奏砉，郢风复运霎。","文章特小技，圣处奚假插。","得趣堪献佛，高吟岸乌帢。","达者越拘挛，迷者泥检柙。","岂知造化机，目击不容眨。","衮衮万马奔，翼翼两攻夹。","灵根有变通，时雨自浃洽。","意轻秦赵璧，价重蒲葵箑。","记舟何用痕，印钱偶因掐。","于道得达尊，问鼎不问郏。"]},{"t":"范武子挽词","f":"五言古诗","c":["呜呼吾武子，天乎夺何速。","潇洒锦绣肠，秀润琅玕腹。","出口论世事，好语惊拙目。","孝友式里闾，急难骇僮仆。","曩于建业都，共庀主人属。","但不同姓氏，何翅如手足。","一日不晤对，尺简频往复。","中夜怀清姿，有梦堕脩竹。","时予悼伉俪，感尔念鳏独。","别去几岁华，亦闻悲壶俶。","同病心相怜，异县情愈笃。","我欲托以妹，子不鄙其族。","两穷忽相值，一家有馀睦。","去作建安县，振彼七闽俗。","岂不化彊梗，元不用鞭扑。","邑人歌载途，当路荐联牍。","彼守何坚忍，于民能迫促。","二年甘不考，百谪宁忍辱。","子方困吏鞅，妹忽沦鬼录。","入户悲方缠，出门湿如束。","骏足不受羁，盐车宜折轴。","讣来忽收书，痛甚不容读。","未令吾母知，可闻尔母哭。","人生会有终，汝死冤乎毒。","吁嗟先大夫，艰难脱荒服。","衣钵自桐乡，生涯去巴蜀。","清德诚可种，石田不能粟。","尔母今在堂，何以供水菽。","尔弟独当户，何以资耕筑。","三儿须教训，一女待鞠育。","自愧贫多累，未能分薄禄。","近拟乞州麾，因用致家塾。","此愿未吾遂，有身莫渠赎。","所居读书岩，旁依紫逻曲。","忆昔曾同登，相期共结屋。","今晨何为者，昨梦不可续。","平生乐哉丘，终焉埋此玉。","虽遣奠刍陈，不及墓草宿。","呜呼吾武子，临风泪盈掬。"]},{"t":"应致远以百韵古诗见示推许过当病中姑借放翁韵奉酬","f":"七言古诗","c":["我诗何敢希杨公，况复进之陆放翁。","烦君妙语相纵臾，控地岂得追培风。","两翁齐名家异县，叹惜馀年能几见。","斯人不上甘泉班，我辈先之腼颜面。","君到灵山亲得语，切莫提撕落言句。","恨君相见一年迟，不同蓟北燕南路。"]},{"t":"胡伯晖有诗训豚犬辈次韵以广其意","f":"七言古诗","c":["金风著幕惊新秋，银河摇落光飞浮。","天籁既息虫声啾，书生白发不解愁。","挑灯夜诵疾于流，人生在勤业箕裘。","少不努力进厥修，老将噬脐孰怨尤。","悠悠天壤卑微休，安得独叹命不犹。","昔人忘食兼忘忧，何适非学息与游。","道不敢径川不游，朝吟暮讽夜校雠。","至理渐渍如膏油，好处心会非力求。","不特祇为科第谋，正使积书如邺侯。","手尚不触读岂周，张口云雾正自羞。","学与不学人焉廋，汝曹曾念及此不。","贤师学到无全牛，乃翁为汝相延留。","一官为援乏蚍蝣，欲糊汝口违松楸。","敢辞折腰向督邮，赋归无地堪耕收。","勉旃汲古到索丘，困来时复揩双眸。"]},{"t":"次德友韵","f":"七言古诗","c":["忆昨得君和陶诗，床头细读人谓痴。","二南固自立墙面，十驾亦欲鞭驽疲。","退惭作吏了无补，正使得句安能奇。","有时拈笔弄纸墨，大似临敌收枪旗。","投老且愿共诗社，斗健聊欲为儿嬉。","恨子寓舍苦迢递，有僧借屋无奔驰。","乞米不须烦送似，无储自足常宴如。","转庵与为方外旧，仆也何翅管中窥。","岂有脩竹真可款，曷不宿雾及早披。","来诗赓酬特未已，追逐登临随所之。"]},{"t":"得赵昌甫诗集转呈转庵却以谢梦得诗见示有诗次韵","f":"七言古诗","c":["我馋嗜诗欣染指，但见其长有谁毁。","早年游方识赵谢，如鲁逢掖宋章甫。","谢诗澜翻豪且古，赵句清癯澹而苦。","学力到后成一家，渠自不知为孰使。","天各一方费渴思，想见冰增寒似水。","居然老手斫方圆，出户中规还中矩。","转庵活法已参遍，何止得心仍得髓。","我如无宝穷波斯，望著是珍先自喜。","忽得赵璧急呈似，示以谢草如寄取。","自怜老去无长进，努力吟哦训儿子。"]},{"t":"再次转庵韵","f":"七言古诗","c":["能诗何殊臂使指，得句不愁人背毁。","诗何缘瘦道自肥，谁嘲饭颗山前甫。","誓不惊人死不休，言是良工心独苦。","骊黄牝牡元不问，智诈勇贪俱可使。","合时端如锥画沙，悟处快于瓴建水。","赵诗平澹谢奇古，所以吾侪誇絜矩。","转庵更是可怜人，诗眼既高窥字髓。","我生何能补一字，君美非溢私两喜。","更须传抄及同社，定不惊嗟斯是取。","骚坛摩垒真几人，安能碌碌数馀子。"]},{"t":"次韵才叔分韵得七字","f":"七言古诗","c":["竹院主人新筑室，涓吉上梁辰取乙。","鸠工度材合忙冗，分韵题诗能暇逸。","独怜久不到容成，片语全无课秋律。","自伤病足转拘挛，不复抛砖为倡率。","转庵忽传七字作，顿埽陈言洗凡质。","剩喜金风入诗思，定挽银河洗吟笔。","鼓宫宫动妙入神，上医医国愈吾疾。","联翩急埽烦寄似，已负今年七月七。"]},{"t":"次陈伯寿分韵得者字","f":"七言古诗","c":["南浦家庖亦烟火，何事胸中太潇洒。","少提笔力老更坚，不信昏金徒巧瓦。","一官姑混录录中，三生岂是悠悠者。","秋镫夜课阿戎读，高筑诗坛洁莲社。","人传绣口仍锦心，我诧琼杯并玉斝。","阿戎官学两俱长，金固在镕非跃冶。","转庵忽传分韵作，咳唾珠玑来笔下。","挽回巫峡使倒流，快注银河见高泻。","敢陪驿骑策疲驽，绝喜风樯追阵马。","爱诗未足老犹贪，染指更尝犹靳舍。","祇惭狗尾聊续貂，安得曲终成奏雅。","吟哦未了忽开予，拟约凭高共纾写。"]},{"t":"次转庵用坡公韵并简洪樗野","f":"七言古诗","c":["短日驱驰驹一罅，百刻六旬分卜夜。","残年馀力秉烛吟，所冀二中并四下。","敢多奇疾希卢扁，祇是寒温随补泻。","转庵著眼从昔高，伯仲古人相匹亚。","细哦纤巧天许觑，硬语崚嶒神所借。","窠臼已脱卑晋宋，真淳更拟出陶谢。","近惊樗野轻千里，远自鄱阳踰百舍。","举似诗家说中蜜，更引禅宗谈倒蔗。","老父病后已云怯，馀子听诗应转怕。","那令勉继坡公韵，预恐难逃灌夫骂。"]},{"t":"送蔡骏叟往金陵见留守李尚书","f":"七言古诗","c":["蔡郎百战吞贤关，彤庭射策谁其班。","桂枝第一几得攀，一官去纠蜑与蛮。","留台友第季孟间，吟诗远过陈后山。","使觅仙山大药还，归来五色应斓斑。","因声为语大匠般，君何不来予汗颜。"]},{"t":"邵廷评供职未阅月乞为淮南检法官以归赋长句见志次韵为饯","f":"七言古诗","c":["圣朝亦知贱士丑，尚许追随牛马走。","圄空幸免殚拙心，材散那能呈好手。","万里来归尘扑面，一梦惊回柳生肘。","同僚末至得斯人，眼底轮囷曾有否。","青云直上气如虹，要津立登槎犯斗。","惠文安得事仁尧，吏酷自应嗤小苟。","相从几何突未黔，掉头归去依岩薮。","拄笏聊看罨画山，岸巾且饮淮南酒。","夫君自是皎洁姿，不用沧浪濯缨垢。","正恐功名自逼人，更向王畿重结绶。"]},{"t":"送赵推官持檄之兴国","f":"七言古诗","c":["赵君派自天源来，细考衡茅无此才。","文章决科特馀事，幕府官业何壮哉。","论事不愁开口屡，直道驰驱羞诡遇。","尺伸如可寸枉施，宁脱青衫故园去。","宗庙之宝森玙璠，诸公争欲出我门。","极知胸中有定力，未肯叱驭随王尊。","楚狂凉凉莫宜世，一笑相逢有初契。","尊酒论文情益亲，但不同姓实兄弟。","文昌堂前汝水东，万顷烟雨时濛濛。","向来簇坐觅新句，多少行人图画中。","君今胡为事行李，著身翻在图画里。","捧檄王事不可迟，何况堂中老亲喜。","喜君问道康庐旁，过家上冢还不妨。","再拜松楸有心事，孟母卜邻今更良。","了却痴儿纷案牍，回首庐山真面目。","唤起三年梦中意，想见诗成清可掬。"]},{"t":"崧高行上周密使寿","f":"七言古诗","c":["银潢快泻天无声，秋光漾出圆蟾明。","玉关晏眠柝不惊，筹帷坐见万里情。","健儿饱食细柳营，猛将思奋抚剑鸣。","摘试一二来帝京，表里百万皆精兵。","此时崧岳风更清，寿酒消得如渑倾。","天子神武恢八弦，一贤制难真长城。","鸿钧对斡三阶平，珠连五纬荐玑衡。","天开地辟霖雨成，中书之考远作程。","回视万卷纷拿撑，一编自足垂勋名。","书生脑脂眯短檠，莫耶挂壁吼长鲸。","相公办取崧高行，不惜携之上峥嵘。"]},{"t":"崧高齐上施参政寿","f":"楚辞体","c":["灵山钟秀崧高齐，鹿苑名胜神所栖。","水晶玉札银成泥，无论粉绿丹黄黳。","文星相望直斗奎，出藩入从黄金闺。","谁坐廊庙赓凫鹥，山经地志古有稽。","我公间气今其繄，资兼文武双印提。","十年太学甘朝齑，吐光万丈腾虹霓。","鸡林传诵争航梯，至今威名詟羌氐。","张旃朔庭抚遗黎，鼓舞雄豪泣旄齯。","折冲樽俎眠鼓鼙，屯云万里行春犁。","五风十雨无苦凄，此疆尔界谁町畦。","不须京观封鲸鲵，混一少忍矜扶藜。","从容论道开端倪，一语折衷温如绨。","鉴裁不阅黄与骊，流品自成桃李蹊。","琴音八极回薰兮，长庚夜明玉绳低。","貂珰晓驰建章西，黄封九酝天处题。","寿以一饮千玻瓈，公开寿域民同跻。","龟文燕颔额插犀，中书之考米一稊。","葛仙炼丹旧有溪，从公拟欲求刀圭。","散作人间刮膜篦，尽洗凡骨开尘迷。"]},{"t":"云龙歌上周丞相寿","f":"词","c":["万化衮衮相乘除，循环甲子如数珠。","甲子既周理当复，岂有润泽翻焦枯。","丞相补天祗衮职，闵雨忧民见颜色。","云龙契合此其时，能费天工几多力。","明当月色圆如秋，书生徙倚生暮愁。","欲攀斗柄酌河汉，一滴变化为万流。","忆得去年曾拜月，此日团圆仍皎洁。","极知有药自长生，更愿长圆浑不缺。","今年拜月去年同，却欲屏翳驱云蒙。","久占月角如张弓，两月少雨惟多风。","昨夜占星忽离毕，定自滂沱翻手疾。","今朝四郊已沾濡，丞相明朝是生日。","书生喜极欲起舞，急买香茅葺庭宇。","公不见崧岳降神生甫申，山川出云作时雨。"]},{"t":"上南轩先生寿","f":"七言古诗","c":["岷峨一线江滥觞，意行万里无留藏。","五湖洞庭洑熊湘，衡岳岿然锁其旁。","离堆砥柱屹相望，湍流横溃不得狂。","挽回断港济绝航，一齐众楚势莫当。","三芝五饵别有方，狂简痼疾滨膏肓。","天遣奔波赴洄湟，回视坎井足跳梁。","三浴薰之惊望洋，一语咽口成周章。","昨夜太白垂光芒，皎然松柏凌雪霜。","向来十袭一瓣香，再拜斯文寿无央。","愿回帝力超羲皇，无怀大庭还我乡。"]},{"t":"次韵何起岩喜雨","f":"七言古诗","c":["龟坼高田畦渴雨，何取尸臣守兹土。","抽毫擢发控深衷，羽衣拜章夜当午。","天门岧峣洞九重，玉几哀矜迥三拊。","守臣有罪固合诛，农夫在勤亦良苦。","去年旱荒有积仓，今年饥歉将空庾。","通宵洒润祇若丝，明发屯云俨安堵。","初惊大点来莫当，俄即翻盆流孰禦。","旧雨相过忆去年，坐视排檐亦如许。","我惭历历洗心源，君喜津津见眉宇。","瑰章杰句助欢呼，石燕商羊俱鼓舞。","急须似吸举深杯，莫负如渑写甘㴻。"]},{"t":"次徐漕韵贺留守刘观文祷雪感应","f":"七言古诗","c":["雪霜之忍有至慈，一片到地五谷滋。","所以腊中重三白，史讥失时书直辞。","我公卧护北门北，百姓爱公如爱日。","及冬祷雪乃爱民，若有鬼神宜率职。","要晴要雨天必从，玉山何独閟烛龙。","一夜风师擘冰絮，坐使东国成雪宫。","晓起清愁无复有，如在春风饮醇酒。","欲歌零雨劳公归，正尔补天须妙手。"]},{"t":"再次韵呈徐漕","f":"七言古诗","c":["留台心与天等慈，违春觅雪回象滋。","计台心与留台似，贺版趣遣琼瑰辞。","白战场前受降北，笔补造化戈却日。","郢中之曲信寡和，鼓宫宫动能者职。","我欲十驾期相从，今见老子其犹龙。","径须乞公玉蕊佩，去上绝顶瑶台宫。","下视尘寰一何有，天地交光落吾酒。","酌公云梦公莫辞，能费公吟几叉手。"]},{"t":"次韵程判院喜雪","f":"七言古诗","c":["帝心端与天心合，务本先农斥浮末。","冬温祷雪响交孚，急霰先声如撒泼。","献花女儿弄璿玑，剪裁楚水烦湘妃。","东郭先生不敢出，南枝乌鹊空惊飞。","高卧从教深没屋，此是天工真雨粟。","但愿四海大有年，无田可耕宁己独。","诗翁爱日亲年高，时时梦里见三刀。","男儿盍洎千钟养，蹴踏起舞听鸡号。","勋业欺人头易雪，化工于汝难私燮。","满酌长歌白雪吟，下里阳春讵有别。"]},{"t":"雪再作山甫约游雨花台不遂闻与诸公登凤凰台次韵送似","f":"七言古诗","c":["骚屑寒威逼重幕，衲被蒙头慵蚤作。","不知一夜雪花飞，但讶五更风力恶。","摩挲病眼试凭陵，把玩清诗何洒落。","好语自足驱疟疠，嘉祥况乃销离瘼。","绝怜冰箸堕脩檐，拨触风琴响朱箔。","一冬温煖忧麦蚕，万事乘除等凫鹤。","为言三凤今河东，曾约连驺出南郭。","山阴舟回虽兴尽，巫峡云归终倖薄。","方疑再往成渺芒，已拉群公溯寥邈。","九万扶摇不可希，随分榆枋吾亦乐。"]},{"t":"次韵苏伯茂立春日雪","f":"七言古诗","c":["从事青州初入幕，子墨梁园新有作。","春工试手欲成妍，滕六蜚英良不恶。","初看到地润却无，旋喜积威乾更落。","铺檐羃砌遍匿瑕，压瘴埋蝗广求瘼。","蓝田种玉夜生苗，吴娃擘茧朝盈箔。","认巢无处疑昏鸦，敛翅有踪惊瘦鹤。","一庭柳絮漾东风，千树梨花醉西郭。","犯寒觅句觉诗清，贾勇行杯疑酒薄。","颇烦造物相料理，顿使幽怀渺绵邈。","回看稚子失啼饥，想见田家尔应乐。"]},{"t":"登伟观因诵老杜道林岳麓诗用其韵","f":"七言古诗","c":["立秋三日天气殊，凉风渺渺舒郁纡。","少日第拄西山笏，暇时惟汎会昌湖。","投老身登华盖顶，度堂面直莲峰炉。","长江回抱若裹玉，明月荡漾如怀珠。","楠溪大源小源出，樟浦早潮晚潮俱。","凌空笔架呈挂綵，出海金轮看浴乌。","中川蚌胎非妩媚，港口螺浮疑虚无。","何以得此江山伟，若有相者神明扶。","了知无一可云补，其敢有二当何诛。","故人相逢笑颠错，生涯不解先膏腴。","且同野叟共尔汝，免以前衔相唤呼。","看山未觉迷老眼，报国终愧全微躯。","斫竹特为三益径，把钓倦作扁舟图。","乃知绝境真妙绝，强名孤屿何尝孤。","凭栏聊欲须款款，飞帆正尔来于于。","明朝此兴定不浅，但恐劳苦肩舆夫。"]},{"t":"雅师求阁名既为作扁榜仍赋娱客杂句","f":"七言古诗","c":["妙景非声亦非色，非色岂应容粉饰。","东坡妙用遍虚空，大地山河等儿剧。","简斋有句添蛇足，雨抹晴妆要娱客。","黄妃塔边净相寺，破屋荆榛十年事。","雅师办得一片心，化出宝坊全体备。","杰阁巍巍尊大士，我欲名之无尽意。","更拈蛇足扁东偏，与师饷客为客地。","东坡仙去可无诗，客来了此一段奇。","未雨未晴烦举似，非鬼非仙竟是谁。"]},{"t":"王宣甫求崇斋扁榜仍索诗转庵之作先成即次韵为寄","f":"七言古诗","c":["圣门教人亦多术，由也升堂未入室。","颜虽在寝犹仰高，火就水流随燥湿。","但见终日不违愚，岂知庶几介如石。","陶溪昨以崇名斋，欲予隶古诗记实。","今晨忽见转庵作，名与诗高同起日。","崇斋少学用心苦，晚乃一扫科举习。","霜降自然知水落，道损都忘为学益。","一从崇卑悟师说，心已沈酣全体易。","书扁外和转庵诗，不待形容有润色。","忆昨尊公期类予，似我颛愚有何获。","老惭才衰惟钝迟，感君肯赴同襟期。","闭关却埽门植榆，不妨倡和来埙篪。"]},{"t":"次韵转庵读中兴碑","f":"七言古诗","c":["千秋金镜唐元龟，苞桑镜见龟灼知。","女主为祸已云惨，天宝之乱尤危疑。","九龄早悟绸缪诗，其奈哥奴基棼丝。","外人何得与家事，旋闻潜纳河洲睢。","席誇禄儿李裴和，助桀为虐几乘危。","趣之使乱果为谁，张巡庙哭祇涕垂。","高将军固非远虑，掉头肯和金刀篪。","四镇休罪高仙芝，张垍早措平章辞。","望贤宫中例忍饥，金刀胡饼方效奇。","事有至难已言之，贼心包藏久窃窥。","春秋知我盍罪我，监国引嫌孰维持。","颜笔劲节霜筠似，元文秋月华星如。"]},{"t":"次韵袁尚书同年巫山之什","f":"七言古诗","c":["我本山泽之臞姿，出处相较黠与痴。","生当浙东岩壑地，閒觉壶中光景迟。","井蛙敢从海若语，雁荡断谓天下奇。","一从天柱想突兀，便觉屏嶂排参差。","盍归乎来归未得，今吾非故吾何之。","南官祝融常在望，北征太行长相随。","几欲拓开令混一，虽愧力乏犹忘疲。","故人将指镇巴蜀，大江扬舲张虹旗。","经行先须实古锦，及境方要褰赤帷。","阳侯似知公得句，吴榜自舞山折枝。","有客忽传巫山高，长安不复纸价低。","阳台从昔誇词赋，大夫无乃姑戏嬉。","山川合因云雨祀，神明何得亵渎为。","牵牛织女誇自古，小姑彭郎讹一时。","三复新诗有如此，尽洗遗恨从今兹。","蜀道虽云在天上，政誉巳逐诗声驰。","世情向背南北阮，人物好丑东西施。","愿君沧溟恢宇量，听彼瓶罂居井湄。","已为下户蠲逋赋，更要全蜀俱信眉。","长安父老久延颈，关外饟馈宽张颐。","寂寞恐有玄尚白，留落得无素染缁。","规模久矣欣济济，民俗定尔臻嘻嘻。","公归得政公何疑，勿为风月镌峨嵋。","归来要续峿溪颂，已赋中和宣布诗。"]},{"t":"听刘念九丈二姬歌所和醉时歌明日亦次韵送似时已三鼓","f":"词","c":["边头幕府文书省，功名之心灰似冷。","老去英雄髀生肉，功名之心死未足。","中原有土尚沦金，中原有民惟戴宋。","天开地辟会有日，竹头木屑宁无用。","男儿信命人见嗤，命轻于山重于丝。","未肯身同草木腐，径欲名与天壤期。","行藏我何有，交友勿复疑。","躬行即吾道，归求有馀师。","和气冲融自斟酌，荣枯不逐花开落。","物理天时信有终，云虽出岫终归壑。","未须高卧百尺楼，未须紧束春秋阁。","夫子适去还适来，无波古井生青苔。","我独不归何为哉，渴心已觉飞黄埃。","长鲸未骑且扪虱，不妨随意芬浮杯。"]},{"t":"田家秋日词","f":"七言古诗","c":["晚禾未割云样黄，荞麦花开雪能白。","田家秋日胜春时，原隰高低分景色。","寒栗挂篱实累累，角田已收枯豆萁。","芋魁切玉和作糜，香过邻墙滑流匙。","牧童牧童罢吹笛，领牛山下急归吃。","菜本未移麦未种，尔与耕牛閒未得。"]},{"t":"晚田黄雀词","f":"词","c":["黄雀不知来处所，或云海化或蛰土。","秋至晚田拾禾黍，投身不知入罔罟。","十中八九不计数，黄雀之死孰怜汝。","汝不如搏谷并布谷，又不能快活催麦熟。","农夫辛苦耕，无功食其禄。","无功尚可那无厌，腹饱果然犹不足。","呜呼一年三百六十日，常时安在今时出。","安得山间野谷生石田，与汝饱死终天年。","黄色雀，还可怜。"]},{"t":"次韵陈伯寿食黄雀有感","f":"七言古诗","c":["嗟哉黄雀力命微，譬彼食言安能肥。","乃欲身与天壤期，沕穆造化窥缄机。","以时启蛰安居卑，蛰久启晚见者稀。","不耕而食乘三时，晚禾欲熟堆农扉。","就田恣啄充久饥，来时千百漫天飞。","惟欲蔽翳朝阳晞，似雨霏微疑复非。","此时得计压稻枝，腹饱果然不思归。","岂知时与命相违。","投身入网分所宜，鸡肋犹怯尊拳挥。","汝辈么么将安之，螟螣害稼古实讥。","嗟哉黄雀全无知，大似爝火凌朝晖。","炙之醢之争称奇，谁念物命聊依依。","黄雀何责复何悲，夷齐饿采西山薇。","不尔吸风何活为，颜子箪食其庶几。","祇令瓢饮将谁欺，霜露舒惨相恩威。","螳蝉小大遂黠痴，人为物灵贤则希。","比物丑类姑释疑，螽斯岂得比后妃。","钧之三成君父师，法当授命宁避危。","有益于国身何亏，我欲与雀排重围。"]},{"t":"次韵酬转庵","f":"七言古诗","c":["南浦太丘潜少微，非隐非吏嘉遁肥。","转庵相与菊花期，黄雀乃得诗发机。","诗则高矣物甚卑，物惟所遇知音稀。","黄雀幸甚逢斯时，菊因东篱桃左扉。","吟成虽佳不疗饥，黄雀头颅万里飞。","两语如露蒙晨晞，后人往往悟昨非。","转庵识破花拈枝，勘遍诸方漳南归。","爱诗爱字沦肤肌，知我愈觉成相违。","同病亦谓投閒宜，老婆心切一手挥。","长篇险韵铸出之，涉斋自讼识评讥。","不待见闻方觉知，覆盆一旦遭赫晖。","平生此段诚大奇，愿言稽首长归依。","为能忍辱偏慈悲，东山久别思蔷薇。","生处放熟非过为，岂须圉圉才见几。","宁受校人当面欺，诗坛受降曾怖威。","床头置易甘成痴，虽匪颜徒窃愿希。","今见菊花更不疑，牵联黄雀为匹妃。","南浦柏梁一字师，转庵拨动关捩危。","琴鼓不鼓无成亏，前言戏解小郎围。"]},{"t":"德久送沙噀信笔为谢","f":"七言古诗","c":["海物惟错群分命，并海馋涎为物病。","采拾烹煮如撷蔬，岂念含灵钧物性。","就中水母为最蠢，以虾作眼资汲引。","虾入罔罟自不知，水母浮悠亦良窘。","其间墨鱼工吐墨，以墨自蔽潮水黑。","潮来舟人如拾块，贩者填街卖乌贼。","沙噀噀沙巧藏身，伸缩自如故纳新。","穴居浮沫儿童识，探取累累如有神。","钧之并海无所闻，吾乡专美独擅群。","外脆中膏美无度，调之滑甘至芳辛。","年来都下为鲜囿，独此相忘最云久。","转庵何自得此奇，惠我百辈急呼酒。","人生有欲被舌瞒，齿亦有好难具论。","忻兹脆美一饷许，忏悔未已滋念根。","拟问转庵所从得，访寻不惜百金直。","岂非近悟圣化诗，望兹尤物令人识。","绿衣在旁忽冁然，蝤蛑取笑却可怜。"]},{"t":"再用韵谢德久见和","f":"词","c":["人为物灵钧受命，物本于人无诟病。","圣远庖厨存此心，诗咏虫鱼明物性。","沙噀入咏诚蠢蠢，因之演雅聊援引。","此辈已分泥涂辱，吾侪忍加汤火窘。","乌郎自乌墨鱼墨，如虱处发不知黑。","锁管寄车墨者流，书契岂皆能作贼。","牡蛎分房巧芘身，雉蛤移种陈接新。","?君孕玉自撑拄，蠙氏采月为精神。","西施有舌话前闻，老婆之牙岂同群。","螯属黄中膏具美，螺族青出味作辛。","蚬蛏蚶蛤壳为囿，相濡以沫期耐久。","自为锅釜使受烹，宁落提携死于酒。","子产校人从肆瞒，流水长者功难论。","寄声海上钓鳌客，鳌动恐伤大地根。","满船月明何所得，意不在鱼钩自直。","潮来忽见驾山来，个解吞舟人不识。","有客闻之为骇然，人鱼更擅将谁怜。"]},{"t":"次韵监簿弟惠乌髭药有诗","f":"七言古诗","c":["漆城容可为荫室，发白何由黑于漆。","但闻拔白成斑句，安得反老还童术。","嗟予同气仍同心，怜我年侵雪更侵。","尔年少我尚馀纪，我发纵秃当投簪。","顶如赤壶已无二，君有良方诚已试。","正使缁鬓犹能华，未免种须逢见戏。","我发非病心合医，心白发白无已时。","欲将心来烦汝黑，且图百问百不知。"]},{"t":"再次韵酬答","f":"七言古诗","c":["弟官辟廱邻藏室，肤如凝脂眼如漆。","人言自是仙中人，何乃反求还白术。","少年苦学知苦心，心为发根宜早侵。","黑间见白犹堪镊，白既还短难胜簪。","我老闭门师不二，病足挛拳百药试。","草玄尚白从客嘲，摅尾奋鳞任宾戏。","我闻医国为上医，子方诚良盍济时。","百二之名殽函固，谁与问津君当知。"]},{"t":"杨似勋许惠丹砂","f":"七言古诗","c":["双矑炯炯朱成碧，两鬓星星玄尚白。","丹砂入地长黄芽，苍颜幻得婴儿色。","了知色相无定形，造化于人亦儿剧。","蓬莱三山何渺茫，内景黄庭犹准的。","怀璧其罪彼何辜，资盗以粮渠自贼。","西州九转得奇功，愧我闻名未曾识。","小人有母垂八十，步履轻便自畴昔。","今年一病起衰容，分明只得丹砂力。","九顿首拜三叹息，什袭藏之愿无斁。","日引月长馀几何，神夺鬼偷疑暗掷。","间者从公有天相，启閟抽关话奇特。","便祈公赐公许之，归语老亲感填臆。","膝行欲请还踧踖，盛事不应相趣迫。","三沐三熏课长句，句岂能神公自德。"]},{"t":"杨丈既惠丹砂数种再用韵敬酬","f":"七言古诗","c":["鹊鹊飞来动林碧，喜声楂楂鸦颈白。","宗伯怜予反哺情，遣赠金丹光五色。","先生上医已医国，敌国长城贤季剧。","胸次经纶有准绳，壶中消息有端的。","地行在在即神仙，世上营营自蟊贼。","一编黄石岂容窥，九籥丹经应默识。","未许骑鲸游汗漫，已约据龟论夙昔。","嗟予闻道了无功，粗识事亲惟竭力。","苦乏大药从人觅，数溷宁能无厌斁。","先生乐施微少靳，变化丹砂犹米掷。","得陇望蜀安敢料，和章更枉圭璋特。","名臣奏议得精本，并与寒窗资省臆。","有亲可娱书可读，归养可期非怵迫。","愧无好语酬少分，昨夜春官长阴德。"]},{"t":"以端研送郑景元同年","f":"七言古诗","c":["贵公宝研如宝璧，书生摩墨但摩石。","有文无研正不妨，有研无文亦堪惜。","渐老祇愁才力尽，片歙拳端宁不靳。","吾家面样什袭珍，色如马肝肤理润。","昔言眼为石之病，此论不公吾有證。","星辰在天珠在渊，此石睛光鸲鹆瑩。","文字之祥吾敢颛，郑侯一见心拳拳。","百年石交吾与汝，更有甚者吾当捐。","儿曹旁观俱唧唧，儿曹莫痴翁岂失。","郑侯自有无价珍，持献于人吾惴慄。","愿侯珍研如所有，少时光芒须逼斗。","会看落笔中书堂，却试玉堂挥翰手。"]},{"t":"又次韵转庵用食黄雀韵赞叹邓长孺曩得予端研邓为转庵甥方在疚","f":"七言古诗","c":["论研当考石精微，观人岂计体瘠肥。","歙溪入浙无淹期，刷丝罗纹如出机。","比并端坑终品卑，就中古端见尤稀。","难得已叹承平时，长绳束腰下岩扉。","宿粮腰畔不救饥，凿深泉眼迸若飞。","浸淫竟日无光晞，轻生重石不悟非。","石工传业犹孙枝，我售古璞千金归。","璞虽云石玉为肌，信手得墨无拒违。","事忙行草取次宜，才衰笔老无发挥。","顷见邓友辍赠之，质粹材美不可讥。","契家有子吾所知，文章光焰期腾晖。","不妨怪怪仍奇奇，酷似牢之惟舅依。","嗟嗟尚怵霜露悲，循陔自苦躬采薇。","读礼以外将胡为，力学报亲其殆几。","学非有厌书非痴，有志于上皆可希。","彤庭对策决大疑，制草说命周南妃。","玉堂从容有馀师，古来孽子操心危。","勉旃无令一篑亏，万钉要看黄金围。"]},{"t":"驯熊叹","f":"七言古诗","c":["兽名曰熊本逸才，啬夫教之驯若孩。","开槛当街作险戏，寻橦旋筵能千回。","负戴蹲跠时䀡睒，忽然逸出渠亦敢。","啬夫当之作人立，嗟尔勇气终坎壈。","问云初教本无法，祇是豚蹄趁饥乏。","说似连营饱食人，努力边头厉戈甲。"]},{"t":"射鹰行","f":"七言古诗","c":["圣作桑弧男子志，矢人伤人岂吾事。","五陵少年狭斜游，柘弹金丸矜垩鼻。","一朝折节臂良弓，腰身不动马如风。","背弯团月无留意，秃鸧老鹰应弦坠。","书生忍饥犹努力，夜夜孤灯腕寒石。","等閒拓手石五馀，真是无心事书策。","诗书岂不关时须，寄语悠悠年少儿。","一鹰一兔寻常事，正要尺箠鞭羌夷。"]},{"t":"悯牛行","f":"七言古诗","c":["牢牛得肉那忍吃，匪论阳报谈阴德。","忆牛初生成犊时，随母耕田眼先识。","茧栗渐长初胜犁，脱轭项间染能赤。","一行错误随后鞭，习得犁行如界直。","耕来耕去禾稻成，得閒放食行田塍。","稻秫掠嘴不敢食，自齧枯草甘如饧。","马终蒙帷犬蒙盖，牛岂无功遭横害。"]},{"t":"舁石行","f":"词","c":["沙河塘路飞晴泥，夹道睨立如凫鹥。","千夫舁石自何所，相以柝节当鼓鼙。","一夫流喝相和答，声与步应如采齐。","观者局蹐汗通下，彼独閒暇轻如携。","此石非是装玉砌，此石非是筑金堤。","不为文陛仪禁卫，定作润础承榱题。","俨然一柱方峙立，何者偃植为拱枅。","呜呼自昔良工心独苦，大材小用俱难取。"]},{"t":"素丝行","f":"词","c":["冰盆缲丝千尺长，雪花玉色无晶光。","机声札札逐羲御，百襄一一输文章。","素姿已是随时贬，妖茜娇蓝还点染。","东邻巧妇斗痴妍，对刺文禽相掩冉。","衣裳颠倒那得知，但见新行胜旧时。","倡优却得被后饰，汉庭只集书囊帷。","君不见古来志士多惨戚，古貌古心少颜色。"]},{"t":"观弈篇","f":"词","c":["秉烛随者明，弈棋观者精。","观者未必高于弈，只是不与黑白同死生。","天上神仙何所争，亦复于此未忘情。","樵夫柯烂忽猛省，却与棋仙作机警。","千古未尽一局閒，岩草岩花自凄冷。","呜呼圣主不弃刍荛言，弈棋复出亦必资傍观。"]},{"t":"古柏行","f":"七言古诗","c":["太华山头有古柏，宿柯成铜根化石。","自从出地受雪霜，直到于今几千尺。","向来移种向中州，挽之不动艰万牛。","根连玄圃渗七泽，凤凰将雏鸣上头。","春草寒花几衰歇，枯蔓朽株风屡拔。","岿然此柏安如山，匝地清阴覆椒樾。","不辞孤立成大厦，匠石踌蹰少须暇。"]},{"t":"卖花行","f":"七言古诗","c":["缃桃绯杏琴心叠，睡起海棠收醉颊。","麝煤输彻锦薰笼，金脂染就来禽帖。","姚家魏家苦留春，花信未先红一捻。","卖花老翁正自痴，预喜荷钱出小池。","却恨身非殷七七，一日之中成四时。","不念书生抱孤节，昨夜东风长华发。"]},{"t":"次转庵寄用坡公赋梅韵","f":"七言古诗","c":["一夜酸风惊拉槁，雪压茅檐攲欲倒。","孰知寒谷自能春，斗坼琼枝故相恼。","两年旧隐住容成，耐冷冲寒起常早。","透窗疏影眠未佳，拥被孤吟诗易好。","别来问讯迥相忘，养就苔文从不埽。","诗人云远岁云暮，自插一枝怜鬓老。","孤山在望不可到，惆怅馀香委芳草。","谁邀配食水仙人，长笛横吹倚苍昊。"]},{"t":"次韵胡伯晖喜王簿移梅","f":"七言古诗","c":["水南梅花光似雪，扑地香风喷鼻裂。","诗人不来岁华晚，寂寞岩扃那忍折。","一朝移向凌风前，雕栏碧甃生寒烟。","聘以新诗寿芳酒，洗空遗恨春溅溅。","住山多时识幽洁，行到台边忽凄咽。","故园萼绿正相思，冷却东皋半犁铁。"]},{"t":"仇香种梅已开而出乡未归再次伯晖韵","f":"七言古诗","c":["忆醉江南枝上雪，爱词人把罗巾裂。","篇成皓齿发琼姿，酒尽貂裘堪当折。","如今消得督邮前，期会纷来闹似烟。","故人一枝久寂寞，新愁万斛谁洗溅。","仇香有意移芳洁，索笑不来空哽咽。","幸自花开君不归，一夜孤根冷如铁。"]},{"t":"欲雪怀度云新种梅三次伯晖韵","f":"七言古诗","c":["朔风动地天欲雪，涧底孤松定皴裂。","忆梅已觉肠九回，赋诗敢爱肱三折。","帘疏香细度云前，想见娟娟媚晚烟。","主人吟哦伴幽独，醉墨不惜花袍溅。","人与寒枝共修洁，未遣调羹笛休咽。","贩马江头得句回，踏破蟾光敲镫铁。"]},{"t":"次韵诚斋醉卧海棠图之什","f":"词","c":["海棠宁莫种，种须千万株。","濯锦江头锦漫谷，斧斤不赦如薪枯。","乍逢樵人莫逢杨氏女，遗恨年年泣朝露。","杨氏自媚昭阳宫，海棠自映扶桑树。","山城幽独逢坡翁，一洗千载尘埃蒙。","张园锦障人所惜，醉里看花尽英特。","酒满衣襟花满裳，只许茶铛近笔床。","顾影鬅鬙醒还卧，乌巾正堪漉白堕。","只恐明朝雨霏霏，花雨征帆各自飞。","休论长篇与短韵，且与春风写音问。","此人此句皆可图，底须紫凤并天吴。"]},{"t":"次韵诚斋饮张园放翁酹酒海棠花下","f":"七言古诗","c":["九霞觞翻湿云幄，群仙戟指嫌轻薄。","海棠枝上管春晴，醉魂未醒来层城。","风姨妒吹银烛灭，明月飞来更奇绝。","急须巢饮添烛光，今日绮霞明日雪。","濯锦江头识放翁，翁令对花群玉丛。","试浇以酒添花晕，是酒是花若试问。"]},{"t":"次转庵榴花韵","f":"七言古诗","c":["良辰竞渡常伛指，爱花颂花奚谤毁。","年年五月见红榴，重著赐衣怜杜甫。","佳节有名名不去，阅甫逢辰何自苦。","薄俗传讹成力竞，作戏轻生为酒使。","惆怅刘郎击节词，招屈亭前但流水。","明当鍊镜非常规，我辈持觞宁越矩。","只为榴花饮亦佳，况是转庵吟入髓。","浮花浪蕊竟何为，秾艳芳心诚可喜。","不应寂寞负澄鲜，同社联翩须记取。","相期竟到无何乡，徙倚更约凭虚子。"]},{"t":"再次转庵韵","f":"七言古诗","c":["安石移根烦使指，花蹙红绡谁擘毁。","封姨妒作阿醋呼，同调何殊申及甫。","肯怜颠倒落绛英，祇觉韩公用心苦。","流传午节遂成例，萱草戎葵并驱使。","真能染却白云殷，灵囿鲜繁金谷水。","诗人爱节因爱花，射团点缀追前矩。","炎官鍊丹成绛雪，獭胆分杯凝赤髓。","谁言不似舞裙红，色相异观特私喜。","点化精神欲然句，晋宋风流坡独取。","鄙哉摘实儿女见，却要瓶罂结多子。"]},{"t":"再次转庵催结局韵","f":"七言古诗","c":["赋花必花指喻指，花若堪谀亦堪毁。","转庵赋梅工赋影，祇竟吕刑元是甫。","节逢五日赋榴花，拟别甘酸亦良苦。","犹之论画先论形，形似丹青谁不使。","岂知雪里有芭蕉，满壁沧溟本非水。","方皋相马群自空，梓匠挥斤风即矩。","续弦何处觅鸾胶，起死底须求凤髓。","榴花可玩不可食，昌歜无甜人自喜。","肯将粉泪匹红巾，眼高一世坡仙取。","花事方殷催结局，还许殿后吟些子。"]},{"t":"同转庵诸人筠斋赏荷花次转庵韵","f":"七言古诗","c":["一笑筠斋同集客，眼看荷花笑中坼。","未说赏花先赏叶，破晓清香晨竟夕。","了知出水非雕饰，乍觉临流似涂泽。","多情落日助酣红，争媚清漪动寒碧。","其间得意谁最多，几个文禽不容只。","锦鳞似梭跃流黄，雨盖如镕倾大白。","同社持觞聊破戒，行令传花非俚画。","昆明撑舟真锦渡，太华如船俨仙籍。","明朝定尔传新篇，今日袖然有诗伯。","诗来忽起西湖思，我辈已觉蓬莱隔。","忆曾画船作夜游，亲听菱歌和露摘。","南高北高祇在眼，长桥短桥频泛宅。","挂冠神武吾盍归，奏篇未央君盍适。","便应献策取貂蝉，焉用孤吟和蝼蝈。","功成五湖有成例，全赐西湖底分擘。","回视筠斋乃坳堂，岂须更许渔争席。","红莲绿水姑相娱，明月夜光成浪获。","当暑清风诵三过，真是双清泯心迹。"]},{"t":"再次韵","f":"七言古诗","c":["急雨撒珠泣渊客，疾风捲荷波涛坼。","须臾雨过即风休，但有水香浮月夕。","水到飞霞几断港，安得红云藏薮泽。","儿曹问津本何有，茭葑蒙茸填淤碧。","划开天宇镜面平，荡漾渔舟自双只。","老惭数溷烦击鲜，筠外栽莲供醉白。","客来意坐夜沈沈，境以客重声籍籍。","清缨浊足随去取，水宽地窄易区画。","转庵夙昔董诗盟，同社歌呼剧欢伯。","婆娑得句俄朗吟，欸乃答声非夐隔。","乃知神语天亦相，仍使菱歌夜犹摘。","著身胜处即冰壶，混俗静中无火宅。","我虽爱吟无好句，其奈处閒聊自适。","未能汗漫据龟蛤，何补官私响蛙蝈。","天籁自鸣忽闻蝉，众作俱喑推巨擘。","恍思南塘香百里，拟汎具区帆一席。","更吟赏实起馋涎，细剥莲蓬珠贝获。","不如藏六守筠斋，水落霜枯且投迹。"]},{"t":"次韵才叔赋菊屏","f":"七言古诗","c":["宾主铛坐成三丁，以菊分题君得屏。","两屏夹立君中坐，君其吉兆当屏星。","化工开花等儿戏，园子结花象物形。","宗英乘船正荡漾，而我对塔方岧亭。","人幸似花同臭味，花亦与人共芳馨。","菊潭之水明且清，楚畹之英驻而龄。","细思杜老看谁健，争似刘伶终不醒。","男儿闻健且饮酒，良辰莫作痴冻蝇。"]},{"t":"绍熙改元早起","f":"五言律诗","c":["元日好天气，侵晨供佛灯。","生逢大庭氏，閒作小乘僧。","报主须身健，勤家且夙兴。","一贫容易饱，四海愿丰登。"]},{"t":"元日","f":"五言律诗","c":["新受开禧岁，难逢庆会辰。","感恩沦骨髓，无力报涓尘。","抱瓮供春事，加餐作幸民。","屠苏须满引，且愿病离身。"]},{"t":"元日简转庵","f":"五言律诗","c":["遥想潘夫子，元正免立墀。","已倾新岁酒，未和隔年诗。","老色长欺鬓，春风不肯丝。","人言金可作，宁惜草堂资。"]},{"t":"次宣甫用转庵韵赋惜春怀转庵","f":"五言律诗","c":["气合桑舆友，才推屈宋衙。","留春无上策，作意惜残花。","葭倚终惭玉，蓬生正倚麻。","陶溪人远室，漳浦客思家。"]},{"t":"次韵转庵书怀","f":"五言律诗","c":["应节何妨俗，伤春已是翁。","百年谙社酒，万里忆郫筒。","话旧肱堪折，追欢袖略通。","潘郎久不见，妙语想蘋鸿。"]},{"t":"秋思","f":"五言律诗","c":["秋色已彊半，秋光才较清。","卷帘为月地，入户得潮声。","萤度催儿课，蛩吟觉妇惊。","起看河汉畔，星象湿晶瑩。"]},{"t":"次韵常之秋日郊居十首 其一","f":"五言律诗","c":["秋日郊居好，风光属散人。","雍容观物化，潇洒任天真。","菊好芙投老，杨疏柳效颦。","飞翻看两蝶，喜得自由身。"]},{"t":"次韵常之秋日郊居十首 其二","f":"五言律诗","c":["田里逢年岁，江山净物华。","栖粮供野雀，输赋答官蛙。","觳觫眠穰圃，龙钟卧酒家。","不须听击壤，平世此何加。"]},{"t":"次韵常之秋日郊居十首 其三","f":"五言律诗","c":["年光本尅期，秋闰似移时。","断雁馀新绠，残蝉泥旧枝。","黄华随露展，乌帽受风攲。","预有登高兴，秋风入梦思。"]},{"t":"次韵常之秋日郊居十首 其四","f":"五言律诗","c":["穷巷家何隘，秋郊景自舒。","草涂飞蚱蜢，蓼岸点舂锄。","虾菜通潮信，鱼蒲傍海居。","饭廉称柳市，别业计非疏。"]},{"t":"次韵常之秋日郊居十首 其五","f":"五言律诗","c":["寄种侪孙稻，株株欲竞齐。","年丰催酿蚁，夜半想闻鸡。","野老同杯酌，忘形绝町畦。","虽无花泛水，终恐世人迷。"]},{"t":"次韵常之秋日郊居十首 其六","f":"五言律诗","c":["涉世味何疏，师心道与俱。","古风诗入律，远景句成图。","一语中标的，千篇徒嗫嚅。","秋光照轩豁，我辈未囚拘。"]},{"t":"次韵常之秋日郊居十首 其七","f":"五言律诗","c":["学阃难优入，诗堂仅许升。","百年从皓首，一盏爱秋灯。","次第挂冠老，晨昏有发僧。","未能逃兀兀，祇欲任腾腾。"]},{"t":"次韵常之秋日郊居十首 其八","f":"五言律诗","c":["龙翔江上水，万折只朝宗。","依倚惟危槛，扶持有短筇。","秋山成自献，落日为谁容。","临眺馀嘉菊，重阳酒自供。"]},{"t":"次韵常之秋日郊居十首 其九","f":"五言律诗","c":["诗分缘稼穑，别墅故人多。","又过中秋闰，无如明月何。","违离增寂寞，衰病废吟哦。","十首撩人甚，重翻古井波。"]},{"t":"次韵常之秋日郊居十首 其十","f":"五言律诗","c":["觅句无新语，怀人有故情。","归音苏酒渴，诗法酿秋清。","近种芙蓉发，低铺锦绣成。","虽赊新瓮熟，腊酝待同倾。"]},{"t":"次韵吴季行秋怀","f":"五言律诗","c":["弹冠惊野马，束带响吴钩。","意远秋多思，诗清语过愁。","君当仪省户，我合老林丘。","何日苕溪上，相从不系舟。"]},{"t":"冬日邀友同赏","f":"五言律诗","c":["令温风有信，林静叶无哗。","别种桃舒萼，先期梅著花。","成蹊馀屐齿，索笑见檐牙。","未饮朝来酒，何妨饭后茶。"]},{"t":"念九日早闻雪","f":"五言律诗","c":["去岁一冬暖，开春逾月晴。","伸眉来雨意，变色起雷声。","摇动园林喜，欢呼鸟雀鸣。","閒中多感激，诗句亦生成。"]},{"t":"岁除日见白发","f":"五言律诗","c":["四十明朝是，俄惊白发新。","旧诗曾探借，今语遂为真。","不恨身将老，惟怜学转贫。","婆娑花县底，谁复念安仁。"]},{"t":"除夜斋宿","f":"五言律诗","c":["老境惭年长，斋居惜岁徂。","难分阿戎炬，只拥玉川炉。","夜雨知时落，朝阳谪见无。","君王素修德，安意饮屠苏。"]},{"t":"新晴二首 其一","f":"五言律诗","c":["入院馀旬浃，今朝始快晴。","才闻乌鹊语，已有蜜蜂声。","到眼花枝暖，粘须柳絮轻。","重门无个事，诗意正关情。"]},{"t":"新晴二首 其二","f":"五言律诗","c":["宿雨居然阁，顽云扫似开。","岚光湖上出，霁色柳边来。","铃鸽抟风转，筝鸢掣线回。","脩廊閒勃窣，花影上苍苔。"]},{"t":"祷雨有喜","f":"五言律诗","c":["已用计然策，犹烦傅说霖。","绵延三日往，慰藉九重深。","柱础收馀润，摩围散薄阴。","何庸尸祝力，圣主自诚心。"]},{"t":"次韵转庵喜雨二首 其一","f":"五言律诗","c":["通夕闻鸣霤，凌晨起炷熏。","映山高见雨，隔坞远留云。","卢橘明金弹，安榴染绛裙。","楼居堪护足，终羡蝶飞纷。"]},{"t":"次韵转庵喜雨二首 其二","f":"五言律诗","c":["榴绽千重束，葵开一丈红。","为怜花寂寞，却念雨溟濛。","此去须时若，相将喜屡丰。","閒中有忙事，祇得挠邻翁。"]},{"t":"再次韵酬转庵 其一","f":"五言律诗","c":["经梅多过溽，转蕙拟吹薰。","山脚昏酣日，檐牙晓堕云。","病忺添御裌，笔懒习书裙。","那得惊人句，聊将绝世纷。"]},{"t":"再次韵酬转庵 其二","f":"五言律诗","c":["万木稠新绿，孤花委晚红。","山容随隐见，云影度空濛。","农老无嫌问，人言不害丰。","破愁还作喜，结句答邻翁。"]},{"t":"德久雨迁鱼庄赋诗纵臾","f":"五言律诗","c":["漫雪蜗争席，翻泥蚓近床。","不堪听鹳垤，应喜得鱼庄。","带雨移行李，携孥问野航。","西湖第一义，佳句已难忘。"]},{"t":"再用韵答转庵","f":"五言律诗","c":["岚光趋泽笏，波影漾湖床。","借竹欣移宅，看花拟宴庄。","钟声来佛屋，镜面济慈航。","莫便疏城市，诗盟未可忘。"]},{"t":"再和二首 其一","f":"五言律诗","c":["晴日烘船屋，薰风傍笔床。","未穿三益径，已想百花庄。","野火明僧寺，樵歌度客航。","山头明月上，酒兴故难忘。"]},{"t":"再和二首 其二","f":"五言律诗","c":["城市从疏出，何人独拜床。","不辞乘下泽，久已厌康庄。","借屋欣凭阁，临湖似舣航。","风波无用避，端与世相忘。"]},{"t":"乡会游湖怀南床复次韵","f":"五言律诗","c":["名园乡党敬，莫可致南床。","盛事联千佛，诸公竞一庄。","建侯期朔漠，驻跸尚馀杭。","报国平生志，他年幸勿忘。"]},{"t":"再戏和转庵","f":"五言律诗","c":["孰裹经旬饭，谁同夜雨床。","何妨散花女，聊伴食鱼庄。","拟唤桃根渡，还思范蠡航。","江湖真落手，身世可兼忘。"]},{"t":"寓居","f":"五言律诗","c":["野水生洲面，閒云傍屋颠。","钟鸣人已定，月满句初圆。","花径经过少，苔文长养便。","行藏随处是，安用买山钱。"]},{"t":"得东山居主人恋家不出因借戴希周渔乡居赋杂兴六首 其一","f":"五言律诗","c":["借得渔乡住，分明似水仙。","好山排座右，明月到尊前。","挂綵迎朝日，飞霞带晚烟。","往来真自在，易觅钓渔船。"]},{"t":"得东山居主人恋家不出因借戴希周渔乡居赋杂兴六首 其二","f":"五言律诗","c":["借得渔乡住，蟾光忽满轮。","金波随短棹，银汉有通津。","几度中秋月，今宵自在身。","一尊消得醉，眼底欠诗人。"]},{"t":"得东山居主人恋家不出因借戴希周渔乡居赋杂兴六首 其三","f":"五言律诗","c":["借得渔乡住，心安即是家。","客来时举酒，饭后定分茶。","野老从争席，山童解献花。","扁舟随意坐，不羡斗边槎。"]},{"t":"得东山居主人恋家不出因借戴希周渔乡居赋杂兴六首 其四","f":"五言律诗","c":["借得渔乡住，閒居气味长。","新霜浓淡白，早橘浅深黄。","勋业锦囊句，光阴宝篆香。","故人如访问，宛在水中央。"]},{"t":"得东山居主人恋家不出因借戴希周渔乡居赋杂兴六首 其五","f":"五言律诗","c":["借得渔乡住，诗家物色宜。","苇声鱼拨剌，竹影月参差。","风铎时成曲，山童解答诗。","閒居多乐事，惟有此心知。"]},{"t":"得东山居主人恋家不出因借戴希周渔乡居赋杂兴六首 其六","f":"五言律诗","c":["借得渔乡住，清霜已著秋。","丹枫如锦障，黄菊似钱流。","物理观诸妄，吾生等一沤。","得閒闻健好，随寓且夷犹。"]},{"t":"次韵石谦伯山居","f":"五言律诗","c":["地僻人为胜，居閒乐自知。","书声山响亮，琴韵水逶迟。","为药藤修架，因花槿结篱。","蓝田冷松竹，那得久怡怡。"]},{"t":"次韵潘德久借居西湖张氏园诗","f":"五言律诗","c":["竹居元为竹，闻借帚湖阴。","齐物千言就，巢枝一径深。","岚光开句眼，虚籁试禅心。","赓得西湖咏，何须更姓林。"]},{"t":"木瓜园","f":"五言律诗","c":["近郭梅根古，临流野兴长。","结亭从寄乐，隔坞得浮香。","度锦趋莲渚，吹云映柳庄。","棠阴无可纪，题作小河阳。"]},{"t":"次韵木缊之题挹爽书院","f":"五言律诗","c":["岁月多歧路，生涯几短亭。","归来故人眼，相对旧时青。","诗带烟霞寄，园知杖屦经。","预愁逃社去，湖外渺沧溟。"]},{"t":"题江心寺","f":"五言律诗","c":["屹立中川屿，江行结斗城。","千滩界岩下，两塔涌波擎。","布地有沙涨，中天惟月明。","清宵挠禅定，端是棹歌声。"]},{"t":"舟行过沛城","f":"五言律诗","c":["人日晴还暖，游丝舞复翻。","湖平开镜面，岸静见芦根。","舟昔几番过，地今何处村。","沛城多美酒，弭棹一开樽。"]},{"t":"籴舟泊高沙为境内所逐却泊天长","f":"五言律诗","c":["官薄谋先拙，才疏食更浮。","抱关从委吏，贷粟向河侯。","遏籴还逾境，迎风更溯流。","百年俱逆旅，处顺一虚舟。"]},{"t":"江行次外舅吾字韵","f":"五言律诗","c":["橹滑谁催汝，山迎似唤吾。","意行从改岸，瞑坐得还珠。","黄卷真如奶，骚经未可奴。","霏微隔江雨，昨夜湿菰蒲。"]},{"t":"阻风泊塘阴寨登四望山用前韵","f":"五言律诗","c":["行藏端在我，富贵本非吾。","不是迷邦宝，休云被褐珠。","官方邻厮役，贤有隐佣奴。","所至何妨乐，车轮未朽蒲。"]},{"t":"舟行得顺风再次韵","f":"五言律诗","c":["抱关真漫仕，所好合从吾。","易乞高霞佩，难投明月珠。","飘蓬谙岁月，泛宅挈僮奴。","万事乘流耳，殷勤十幅蒲。"]},{"t":"入淮","f":"五言律诗","c":["淮水限南北，舟行洛水滨。","底须分尔界，何处不吾民。","好在关河旧，期来日月新。","片云无可翳，岂待净妖尘。"]},{"t":"端午日过左蠡","f":"五言律诗","c":["未识康庐面，惟闻左蠡名。","一朝窥壮观，五节记经行。","细把离骚读，时将浊酒倾。","波涛元不恶，风力更生成。"]},{"t":"诸暨道中早行","f":"五言律诗","c":["飞雪夜无声，窗虚倍得明。","司晨鸡有误，破梦蝶先惊。","何处吹烟湿，谁行马迹轻。","篮舆吾未稳，愧尔仆夫征。"]},{"t":"雪霁早行","f":"五言律诗","c":["蓐食挑镫晕，篮舆破晓氛。","雪开千嶂日，冰合一溪云。","久客年华度，求官道力分。","还乡定春及，物意觉欣欣。"]},{"t":"括苍道中次陈颐刚韵","f":"五言律诗","c":["山色随诗瘦，波光际野空。","行装秋思里，情话雨声中。","无补身如赘，多愁鬓似蓬。","惟馀沧海兴，酒后忆郫筒。"]},{"t":"酬居甫登后山","f":"五言律诗","c":["人老东山隐，春归北斗城。","精庐青嶂合，华盖碧云擎。","落日不愁晚，半蟾方接明。","端能数过访，无惜夜车声。"]},{"t":"送钱大受帅广东 其一","f":"五言律诗","c":["妙算无遗策，私忧有剧谈。","丰功期漠北，小试见湖南。","煖席君何暇，妨贤我甚惭。","诏将须尺一，象可应魁三。"]},{"t":"送钱大受帅广东 其二","f":"五言律诗","c":["淮甸为寮日，私钱奉令时。","同拚愞弱罢，争忍碎烦为。","报国存忠赤，逢人惜鬓丝。","相从又相别，勋业迫男儿。"]},{"t":"送才叔宰乌程","f":"五言律诗","c":["铛坐萤窗夜，肩随鹗荐年。","科名虽独后，官业更无前。","剧县三千水，修门尺五天。","秋风满孤屿，难驻处州船。"]},{"t":"送刘茂实赴连江丞二首 其一","f":"五言律诗","c":["三山七闽右，千竹二松间。","官地今为乐，官名丞更閒。","离支明夏谷，格磔响秋山。","收拾吟哦课，湘中寄一斑。"]},{"t":"送刘茂实赴连江丞二首 其二","f":"五言律诗","c":["弈以旁观审，书难掣肘绳。","一同兼利害，贰邑易声称。","但使知贤令，端为不负丞。","兹行子馀事，著语我何能。"]},{"t":"送潘才叔赴合肥录事二首 其一","f":"五言律诗","c":["镫火寒窗夜，声名弱冠年。","掇科君恨晚，用世我奚先。","饷道曾争辟，公车合荐贤。","圜扉聊鞠草，幕府且依莲。"]},{"t":"送潘才叔赴合肥录事二首 其二","f":"五言律诗","c":["官业盘根见，生涯破甑轻。","才堪当一面，句可敌长城。","亲待平反笑，时须慷慨清。","十连筹正远，三语意犹倾。"]},{"t":"送张说道县尉之官襄阳","f":"五言律诗","c":["一尉襄阳去，三年别旧游。","烦君登岘首，拭泪望神州。","勋业男儿事，依违我辈羞。","为言贤府帅，问讯橘乡侯。"]},{"t":"送薛子明赴歙县尉二首 其一","f":"五言律诗","c":["家世联三凤，才名擅一夔。","诗章谢池草，经术董生帷。","雁塔题名近，龙门点额迟。","一官聊一尉，民事是良医。"]},{"t":"送薛子明赴歙县尉二首 其二","f":"五言律诗","c":["新安今太守，癸未昔同年。","老手亲师范，良规得吏筌。","径须如渭尉，切勿效梅仙。","閒暇何妨学，科名是世传。"]},{"t":"送陈伯寿之子仲至迎侍赴嘉兴秋官","f":"五言律诗","c":["欈李官为李，春风饯此行。","义方非禄养，祖武是家声。","画诺须三语，哀矜在一成。","黄堂应坐啸，执别寸心倾。"]},{"t":"潘茂和才叔远访雨后饯别 其一","f":"五言律诗","c":["连璧远相访，断金情有加。","不因鱼抚铗，自是客思家。","好雨知人意，深杯艳烛花。","今宵真语别，孤屿在天涯。"]},{"t":"潘茂和才叔远访雨后饯别 其二","f":"五言律诗","c":["许种飞霞竹，仍求瓯浦梅。","思乡常梦寐，报国乏涓埃。","玉叶裁云脍，榴花染雪醅。","朝三吾已定，谪百便来归。"]},{"t":"送术士吴国材诗","f":"五言律诗","c":["自昔名家子，于今卖卜翁。","亲逢黄石老，曾验黑头公。","无术自医命，有奇祇堕空。","吹嘘吾岂敢，怜子又西东。"]},{"t":"次韵洪萃之太社真率之集三首 其一","f":"五言律诗","c":["畴昔三洪并，声名四海知。","灵光一老在，鸑鷟九成仪。","近有同朝喜，今无远室思。","双瞻最良誉，合瑞圣明时。"]},{"t":"次韵洪萃之太社真率之集三首 其二","f":"五言律诗","c":["鼎来那有说，铛坐太无哗。","击缶聊三奏，吹埙信一家。","劝时几礼醵，真率胜笾加。","老愧诗无律，新篇极叹嗟。"]},{"t":"次韵洪萃之太社真率之集三首 其三","f":"五言律诗","c":["诗翁甘独殿，我辈岂其班。","爝火自不息，斤风祇似閒。","秋容蟾桂里，归梦雁芙间。","物理因诗悟，新来豹一斑。"]},{"t":"和人见寄","f":"五言律诗","c":["一别三年久，无书堪往还。","自怜供吏役，长羡似僧閒。","契阔诗情在，提撕鬓影斑。","敲门湖上寺，居士已开山。"]},{"t":"和才叔次韵 其一","f":"五言律诗","c":["閒中宜可乐，病外复何愁。","块坐疑三刖，朋来散百忧。","琴弹欣改调，瓶罄喜归谋。","岂复行藏计，终朝只倚楼。"]},{"t":"和才叔次韵 其二","f":"五言律诗","c":["诗社久疏索，吟笺殊涩悭。","遥怜疑落落，近喜复斑斑。","柳密莺酬答，花深蝶往还。","春光顿如许，人事苦相关。"]},{"t":"次韵甄念八丈监簿诗","f":"五言律诗","c":["忆昔忘年旧，惟公不我遗。","分携频问讯，握手屡哦诗。","尘世千年梦，仙家一局棋。","得閒闻健好，振古只如兹。"]},{"t":"次韵广文锁试出院寄似","f":"五言律诗","c":["校文花事过，无句到苍苔。","芍药翻新砌，酴醾浸古罍。","竹枝歌唤起，春草梦惊回。","亦许山中老，相容和朅来。"]},{"t":"同年会拜三茅不及与呈袁侍郎同年","f":"五言律诗","c":["地秘三茅胜，班高玉笋明。","昔年同日喜，共拜一阳生。","造化何劳补，弥文意自成。","梅花开句眼，争得不关情。"]},{"t":"寄潘德久","f":"五言律诗","c":["新雨不可待，故人犹作疏。","有方能煮字，无策与脂车。","洒地亲霜簟，敲冰想玉壶。","端能乘月过，重赋碧芙蕖。"]},{"t":"怀郑仁叔 其一","f":"五言律诗","c":["近有河鱼疾，曾烦旧雨来。","又成三日别，未觉百怀开。","气合嗟同病，情亲忆把杯。","西湖荷盖底，谁遣画船回。"]},{"t":"怀郑仁叔 其二","f":"五言律诗","c":["斗大楼居窄，林深客思长。","雨凉欣破甑，风急凛垂堂。","倚禄生涯拙，忧时鬓发苍。","向来遮日手，祇合钓沧浪。"]},{"t":"病足少苏次常之韵三首 其一","f":"五言律诗","c":["挛拳尊足苦，伸缩楚囚声。","药甲新条在，医科旧贯盈。","百年双脚健，万事一沤轻。","独恨忘形友，终然少合并。"]},{"t":"病足少苏次常之韵三首 其二","f":"五言律诗","c":["休从詹尹卜，数亦不难通。","寄禄逾三品，论才祇下中。","器攲终必覆，药裹漫成丛。","痼疾元来有，惟知酒有功。"]},{"t":"病足少苏次常之韵三首 其三","f":"五言律诗","c":["蓝田纡古句，令我好怀开。","未敢为琼报，何从引玉来。","蒲萄江涨醁，桑落瓮留醅。","柳市人归未，随潮蚤晚催。"]},{"t":"三次澄鳞韵喜闻捷音","f":"五言律诗","c":["昨夜灯花喜，今朝吉语新。","犁庭真破竹，入境若无人。","何力裨洪造，擎拳爇宝薰。","从今愿诸将，献捷日频频。"]},{"t":"四次闻捷韵","f":"五言律诗","c":["身閒偏蚤起，边报逐朝新。","诸将休轻敌，中原尚有人。","定须申挞伐，安得杂莸薰。","祇愧浑无补，空歌捷咏频。"]},{"t":"闻捷五次转庵韵","f":"五言律诗","c":["周历绵绵远，汤盘日日新。","恭闻哀痛诏，愤激老癃人。","报答带仍砺，英雄沐更薰。","衰年扶杖听，折屐敢辞频。"]},{"t":"转庵催结局六次韵","f":"五言律诗","c":["汉仪重睹旧，秦暴尽更新。","应是天亡敌，从知国有人。","乾坤大开辟，华夏一陶薰。","收到昆崙北，诗应快李频。"]},{"t":"和转庵与洪共之说诗谈禅之什","f":"五言律诗","c":["铛坐听清话，鼎来宜笑哗。","诗谈五字律，禅说一枝花。","未肯传衣钵，先须借齿牙。","老婆心更切，黄檗正栽茶。"]},{"t":"又再和转庵且置诗话聊答说禅之什","f":"五言律诗","c":["见性元非说，传心岂得哗。","三更亲受法，五叶自开花。","虽遇夺衣岭，终摇度橹牙。","要知观自在，不异鸠盘茶。"]},{"t":"又复次韵为酬答说禅偈言","f":"五言律诗","c":["密传当正受，谛听勿高哗。","要结菩提果，须开顿悟花。","祖师禅上阵，大将拥高牙。","赴了斋时饭，大家同吃茶。"]},{"t":"次外舅遣侍人韵","f":"五言律诗","c":["关中萧相国，江左管夷吾。","人仰高山石，心宜赤水珠。","登临捐妓女，书札付官奴。","妙得安心法，绳床底用蒲。"]},{"t":"再次外舅韵戏呈舍人叔丈","f":"五言律诗","c":["接栋兄过弟，忘怀汝与吾。","缠头新办锦，买笑近量珠。","怒释泥中婢，欢全膝下奴。","使无驱豆法，亦合赌樗蒱。"]},{"t":"次外舅闻字即事韵","f":"五言律诗","c":["蘧瑗行年化，宣尼耳顺闻。","声名昭白日，富贵薄浮云。","天子方尝胆，中原未静氛。","加餐为时起，礼乐不徒云。"]},{"t":"再次韵并呈舍人叔丈","f":"五言律诗","c":["过访邻墙近，歌呼隔屋闻。","江收梅熟雨，川映蕊红云。","把烛杯仍艳，交谈篆接氛。","盘洲馀醉墨，吾亦欲云云。"]},{"t":"再次闻字韵","f":"五言律诗","c":["船屋香留润，衣篝冷却闻。","晚山新见月，别浦宿藏云。","岁月催人老，江湖净世氛。","望中愁不极，收拾费诗云。"]},{"t":"次韵德久","f":"五言律诗","c":["熟窥齐物论，懒赋畔牢愁。","浮世梦槐国，虚名种橘侯。","有身俱有患，无累即无求。","不啻如今足，何如取次休。"]},{"t":"次转庵韵 其一","f":"五言律诗","c":["节中期乐事，座上欠嘉宾。","雨帽何妨湿，云山自带颦。","午晴开喜色，归月入怀新。","有菊皆重九，无须更卜辰。"]},{"t":"次转庵韵 其二","f":"五言律诗","c":["有约惟真率，相忘任主宾。","拒霜方送喜，疏柳不争颦。","近复关原旧，频看邸报新。","吾侪何幸甚，投老得逢辰。"]},{"t":"三次转庵韵仍招小饮","f":"五言律诗","c":["有径望三益，杜门无杂宾。","只逢开口笑，绝胜捧心颦。","一色黄华在，双投白酝新。","速宜相尔汝，元不阔参辰。"]},{"t":"金鱼久不浮游喜而有作","f":"五言律诗","c":["买得黄金鲫，投将白玉池。","久晴虞涸辙，转壑漾深陂。","每施龟鱼食，偏怀网罟疑。","今晨水澄澈，梭影泛琉璃。"]},{"t":"有喜真爱亭梅花开走笔呈转庵","f":"五言律诗","c":["小园饶胜事，僮仆竞欢哗。","梅绽凌寒树，枝繁照水花。","病身俄勿药，诗思顿萌芽。","急报南邻友，新篘可当茶。"]},{"t":"和转庵白莲","f":"五言律诗","c":["虚籁一声蝉，通宵月正悬。","亭亭承露掌，历历涉波仙。","夜色起香雾，晓光收玉烟。","层冰不可致，清赋忆前年。"]},{"t":"诸葛忠叟初逢家垫池中产双莲求予扁榜并作五言勉诸甥","f":"五言律诗","c":["我爱濂溪说，君能喜种莲。","一经初建塾，双实遽呈川。","和气埙篪应，荣名棣萼联。","勉旃成宅相，学也是家传。"]},{"t":"麝香萱","f":"五言律诗","c":["南薰吹麝馥，背树染鹅黄。","里许香为德，中央色自庄。","洛津行夕佩，仙掌洗晨妆。","真为忘忧赏，看云恋故乡。"]},{"t":"煮茗 其一","f":"五言律诗","c":["止酒身多病，添书日正长。","睡魔推不去，茗碗熟难忘。","鹊过飞樵堕，蜂喧落粉香。","静中观物理，此乐未渠央。"]},{"t":"煮茗 其二","f":"五言律诗","c":["煮茗鸦窥井，哦诗蝶过垣。","笋高垂箨瘦，梅落坠枝繁。","白昼重闱静，新晴远市喧。","境缘看渐熟，吾亦欲忘言。"]},{"t":"显庵饷伊蒲索著语代简","f":"五言律诗","c":["却埽销长夏，来薰傍曲肱。","辘轳金井水，沆瀣玉壶冰。","避暑元无法，安心却粗能。","破除香积饭，供给在家僧。"]},{"t":"挽故丈母莱国夫人沈氏三首 其一","f":"五言律诗","c":["北使复南迁，尚书大节全。","长公身致相，冢妇世称贤。","象服宜偕老，鱼轩遽溘先。","哀伤动行路，谢傅况中年。"]},{"t":"挽故丈母莱国夫人沈氏三首 其二","f":"五言律诗","c":["林泉当丝竹，丞相巧安贫。","珍重承夫意，清修报主身。","指千随嗜好，体一写姻亲。","更有衔恩者，妻孥寄食频。"]},{"t":"挽故丈母莱国夫人沈氏三首 其三","f":"五言律诗","c":["爱女终身托，婴儿半路遗。","讣音非不达，忧思恐难支。","已及黄泉见，应怜白首期。","爱恩均罔极，泪尽挽歌词。"]},{"t":"元日登天长县城","f":"七言律诗","c":["元日登临一腐儒，感今怀昔愧微躯。","此城曾是千秋县，有水呼为万岁湖。","南渡向来纡翠驾，北征何日会京都。","祖功宗德无边际，可恨长淮限一隅。"]},{"t":"次常之元日复用韵","f":"七言律诗","c":["椒花祝处羽觞飞，第一春光勿愿违。","已是浃旬弹指过，可堪维暮转头非。","诗签络绎须盈袖，酒盏淋漓听满衣。","老去寸阴尤爱惜，久拚带减沈郎围。"]},{"t":"人日用常之韵寄才叔居甫","f":"七言律诗","c":["断肠梅作雪纷飞，似与金花巧胜违。","此日共怜人日是，今春谁道我春非。","閒中风月为莲社，醉里莺花即锦衣。","题寄草堂须记取，莫孤绿绕惜红围。"]},{"t":"人日","f":"七言律诗","c":["明当春日今人日，身到故乡胜异乡。","巧胜耐寒元故事，青丝传菜旧风光。","只将柏叶聊随酒，莫为梅花苦断肠。","南北两园多种接，閒居从此有閒忙。"]},{"t":"次韵宣甫约元宵入城不至","f":"七言律诗","c":["春已兼旬未脱绵，积阴顿扫柳条烟。","儿童戏放抟风鸽，老子惟看跕水鸢。","剪綵试灯新乐事，逢场作戏旧丰年。","诗翁不离陶溪隐，可是公房恋屋仙。"]},{"t":"王宣甫以灯夕入城而予偶无佳思阻同游有诗为寒食之约次韵奉酬","f":"七言律诗","c":["落梅声里惜馀芳，孤负灯光与月光。","偶以催租败佳思，阻随执事佐颜行。","春风已入青丝鞚，好句终归古锦囊。","能践清明重约否，须知岁月去堂堂。"]},{"t":"元夕之明日久阴乍晴月色皎然","f":"七言律诗","c":["连阴乍霁自新元，细雨梅花自可怜。","天意肯教人怅望，灯宵终放月团圆。","儿童鼓舞几通夕，我辈欢呼竟不眠。","老少相悬均此乐，去秋无此大丰年。"]},{"t":"次韵程判院春日","f":"七言律诗","c":["催得冬残是野梅，依然春傍柳边回。","不知鬓影星星去，只道年光恰恰来。","喜为农占秋有廪，懒于僧问劫经灰。","历头且复从今数，笑口都能几度开。"]},{"t":"二月晦日游木瓜园","f":"七言律诗","c":["亭成寄乐小裴回，野水粼粼傍酒杯。","未有政声追召杜，敢将诗律继欧梅。","春风已办催花絮，夜雨惟怜老菜台。","百二十春今恰半，不须扁榜记曾来。"]},{"t":"次韵谢余伯益节推","f":"七言律诗","c":["鹊喜声频去复回，亭成报我趣衔杯。","春风得意矜新柳，野水留春恋落梅。","何处笙歌催院落，一时车马走舆台。","搀先但得邦人乐，待约莺花殿后来。"]},{"t":"次韵谢刘太丞","f":"七言律诗","c":["世事羊肠有几回，功名随意芥为杯。","放教春色归繁杏，禁得东风是落梅。","天上有人调玉烛，边头何地筑金台。","朝廷仄席思耆旧，诏逐阳和蚤晚来。"]},{"t":"寒食日宿芜湖县廨","f":"七言律诗","c":["今年歧路足生涯，寒食芜湖感物华。","少为颜公成且住，绝怜杜老叹无家。","光风不禁吹香草，薄雾无端羃晚华。","已是惜春那惜别，无多酌我怕周遮。"]},{"t":"感春呈同社","f":"七言律诗","c":["静处聊将物理推，鸟啼花发苦因谁。","留连春事惟红药，管当行人是子规。","莫道柳绵无住相，也为萍絮媚清漪。","如何饱食閒终日，不课离骚不赋诗。"]},{"t":"四月晦日袁起岩同年雨中集聚景园","f":"七言律诗","c":["湖上名园属内家，湖边有客误乘槎。","风餐历历秦宫树，雨立亭亭汉节花。","乐事坐来添晷刻，题名帖后带烟霞。","春衫湿却它年话，合有新诗记物华。"]},{"t":"次韵常之五日禁竞渡","f":"七言律诗","c":["仍年此足为吾病，举世谁人似我閒。","思远楼前重禁渡，容成洞里独看山。","交游雨绝梅还溽，赓倡星分稿自删。","赖有松庐相慰藉，新篇时复到榆关。"]},{"t":"闰上浣同德久子侄辈避暑退居即事","f":"七言律诗","c":["说著退居心已惬，湖山何况傍绳床。","虽无瑟瑟松杉韵，自觉愔愔枕簟凉。","茗碗亲来诗有思，藕花多处语犹香。","一旬一日恩休沐，今日恩随日更长。"]},{"t":"再赋纪实","f":"七言律诗","c":["官身不办游山具，只有茶铛与笔床。","旋买鲈鱼供箸美，却携玉友待樽凉。","同来稚子听情话，更有幽僧炷妙香。","遥望画船云锦外，好风吹到笛声长。"]},{"t":"次韵酬张岩卿七夕","f":"七言律诗","c":["星文人事古难磨，女织男耕力最多。","河鼓有神司带犊，天孙垂象验飞梭。","因依鸿烈成桥语，泛滥长生旧殿歌。","伉俪流传钧是亵，玉川无赖太风波。"]},{"t":"次韵王宣甫秋夜书怀","f":"七言律诗","c":["静听高梧落甃声，遥闻丛雀转秋更。","星随斗极看时改，露湿天河彻底清。","老去心情惟药裹，病苏灯火惬书檠。","故人忽起关河思，触拨深愁怒瘿生。"]},{"t":"次韵陈仲全秋怀","f":"七言律诗","c":["一夜炎歊破甑空，萧然秋思雨声中。","江湖两鬓惊飞叶，岁月一身俱转蓬。","我自由来为性癖，子今无乃坐诗穷。","男儿穷达终相似，却是难教凿枘同。"]},{"t":"九日次常之柳市秋怀韵","f":"七言律诗","c":["柳市留连爱别坰，归来诗与字俱清。","閒居揫敛全生理，老境行藏见物情。","恨把菊花随雨过，醉敲瓦缶作雷鸣。","千年张翰风流句，却是生前不愿名。"]},{"t":"次韵才叔九日家宴阻访媚川","f":"七言律诗","c":["一秋天气属吟家，九日风光爱物华。","对妇举杯胜俗客，逢辰得酒值黄花。","大难富有成糜季，小异谁知落帽嘉。","独坐媚川空怅望，半蟾分挂夕阳斜。"]},{"t":"次才叔和龚司令九日韵","f":"七言律诗","c":["满院西风把菊天，官身閒暇亦悠然。","恍思杜老浮舟日，绝胜彭城戏马年。","岂待白衣开笑口，不妨乌帽庇华颠。","却愁明发还多事，诗在龙山落照边。"]},{"t":"九日简德久","f":"七言律诗","c":["登高每恨尊无酒，近节今欣菊绕篱。","风日正佳关气数，心情不分减年时。","爱将雪鬓攲纱帽，惬把霜螯对酒卮。","意到潘郎宁易败，催租端自不妨诗。"]},{"t":"次转庵九日韵","f":"七言律诗","c":["窗前白白黄黄菊，门外疏疏短短篱。","择胜任从追赏日，有年即是太平时。","呼鹰戏马人千古，缀席浮舟酒一卮。","五百年间张翰句，风流犹待谪仙诗。"]},{"t":"九日小饮用后山居士韵简转庵","f":"七言律诗","c":["连日欣晴卜暮霞，晨曦闪闪舞群鸦。","时丰都市人多醉，节近重阳菊有花。","万事悠然山正好，三杯可以我何加。","自怜犹有童心在，爱把茱萸系绛纱。"]},{"t":"再用后山韵","f":"七言律诗","c":["懒惰无心赋落霞，醉馀吟笔大如鸦。","但欣有酒酬佳节，犹胜无钱对菊花。","小异孟嘉今老去，知非蘧瑗叹年加。","登临无奈秋光好，归傍窗前月印纱。"]},{"t":"九日同从班诸公自南山过苏堤登宝叔塔","f":"七言律诗","c":["柳下芙蓉锦作裳，画船波底见秋光。","登高自昔须吾辈，戏马从人上宝坊。","白发未嫌纱帽黑，紫萸偏称菊花黄。","常年风日无如此，争不从容入醉乡。"]},{"t":"次韵解颐叟九日登楼唐律二首 其一","f":"七言律诗","c":["诗翁九日独登楼，怅望当年浅碧洲。","菊径全稀虚过节，橘乡无术敢当侯。","汉庭非晚咨良策，边算于今待远筹。","曾得合肥家信否，未应胡越可同舟。"]},{"t":"次韵解颐叟九日登楼唐律二首 其二","f":"七言律诗","c":["规模器业足资身，合是兰宫第一人。","风月难兄居半刺，文章经国肯全贫。","身丁近免家家喜，首述长谣句句新。","预卜他时康济事，定应不负白纶巾。"]},{"t":"三月二十七日玉堂夜宿","f":"七言律诗","c":["以玉为堂未是誇，金林禽谢有金沙。","稍传禁漏提初点，旋听周庐递晚衙。","春尽犹寒欺梦草，晴多未雨渴檐花。","自怜虽是文章力，肯把凡驽污白麻。"]},{"t":"玉堂宿直次高内翰九日前一日草妃子麻毕题案上韵","f":"七言律诗","c":["岁稔时和庶事康，未央称寿捧瑶觞。","宣将銮殿金为炬，草就麻词玉作堂。","自是关雎思淑女，不同飞燕在昭阳。","儒臣信得文章力，捧赐看花一样黄。"]},{"t":"宿社祭斋宫与张野夫廨舍为邻信笔代简","f":"七言律诗","c":["经时不见小于湖，已觉心源少辘轳。","漫道斋宫邻廨宇，何殊弱水隔蓬壶。","清谈每想追前辈，快睹何从换故吾。","大阮端忧更堪忆，平安曾得近书无。"]},{"t":"九月十一日龙华寺斋宿礼部陈同年见余嵬字韵诗宠和惠示复用韵奉酬","f":"七言律诗","c":["雁塔同登惊岁月，龙华共事陟崔嵬。","诗从瑞锦窠中出，人是黄花节后来。","顾我何堪毗右府，如公端合上东台。","清时胜日才兼美，平步功名不用催。"]},{"t":"陈同年再次韵为谢而王才叔判院和篇继至复用韵并谢","f":"七言律诗","c":["铛坐斋宫喜敬陪，高轩二妙屹崔嵬。","旧诗古庙香炉去，新句风樯阵马来。","但有黄花堪落帽，不应白发怕登台。","留连月色须明发，未受秋更密点催。"]},{"t":"酬才叔再用韵","f":"七言律诗","c":["三日斋馀过九日，今朝方得上崔嵬。","日随鸿影翩翩去，句逐湖声衮衮来。","肯为龙华留胜迹，何须戏马羡高台。","黄花未必相欺得，正要诗翁著句催。"]},{"t":"致斋祷雨次转庵韵","f":"七言律诗","c":["夏中春闰合炎蒸，何事凉风日夜清。","大旱望霓如许切，密云不雨太无情。","何妨闭阁斋三日，有愧闻蝉第一声。","遥想转庵同此际，苦辞犹作渴蛙鸣。"]},{"t":"祭龙前一日致斋雨大作邑人以为数年未之有也作此呈养正明府","f":"七言律诗","c":["斋宿临场早有期，邑官齐出去陪祠。","祇应日脚埋云处，便是山头戴帽时。","此雨近来都未有，丰年向去更无疑。","请公买取千钟酒，从此琴堂日展眉。"]},{"t":"次韵广文贺太守祈雨感应","f":"七言律诗","c":["天上为霖正玉衡，农家占雨验书檠。","黄堂恳恻烦精祷，绿野欢呼得遍耕。","束晰未游犹要雨，苏端好过莫教晴。","广文饭足浑閒事，吉语时闻更动情。"]},{"t":"骤雨忽至","f":"七言律诗","c":["未茨山宇趣储材，屐齿怜穿称意苔。","础石润时云气动，茶烟凝处雨声来。","蚕家次第三眠柳，江国凄凉五月梅。","电脚未收雷殷殷，老农争不笑颜开。"]},{"t":"舟中喜雨","f":"七言律诗","c":["骤雨飙风趁急雷，画船系缆小裴回。","隔帘大点欺窗纸，入户微筛供酒杯。","一夏屡忧无计奈，半秋频喜傍怀来。","世间好事无全美，濡首牵夫可念哉。"]},{"t":"积雨简百七丈郎中二首 其一","f":"七言律诗","c":["乡里从游不乏贤，薛侯令我自拳拳。","笔端有力能扛鼎，饮量无涯可吸川。","宁屈乘轺纡郡绂，岂容谢事引官年。","皇天有眼难从欲，暂许祠庭作散仙。"]},{"t":"积雨简百七丈郎中二首 其二","f":"七言律诗","c":["社中真率数追陪，合有閒缘带得来。","十日顿疏新旧雨，百年犹负浅深杯。","护持卢橘黄金实，准拟榴花绛雪醅。","但有菖蒲皆是节，不须端午始欢咍。"]},{"t":"新晴","f":"七言律诗","c":["两旬衰病与阴霖，徒有幽园日涉心。","晓色半窗惊睡起，鸟声丛树索诗寻。","熙怡意象池亭满，履历工夫杖屦深。","掉脱乌巾向人说，市朝不乐似山林。"]},{"t":"次韵刘参议喜得雪","f":"七言律诗","c":["勒回羲驭感苍苍，酝酿风威铄夜缸。","才喜筛寒初集霰，已怜洒急正闻窗。","忘年有约将寻戴，好语先施合拜庞。","不惜登临矜共赏，万妃正舞玉幡幢。"]},{"t":"次韵谢傅公谋贺雪","f":"七言律诗","c":["寒入冰丝响玉琴，燎炉宿火费添薰。","梦惊窗眼疑留月，起看檐牙有堕云。","三白预知开岁稔，一杯聊敢破朝醺。","踵门佳士欣相顾，袖出名章过所闻。"]},{"t":"喜雪 其一","f":"七言律诗","c":["静听微雨落乾声，晓见平檐粉似匀。","去岁鸳鸯何苦热，今朝鸥鹭太无尘。","眼空色界聊矜富，酒极诗豪自觉神。","踏碎琼瑶无过棹，虚教新酿熟经旬。"]},{"t":"喜雪 其二","f":"七言律诗","c":["拥火观书砚不冰，梅将雪访有交情。","一寒依倚回春谷，三白牵连不夜城。","玉烛试于调鼎见，金穰安待剪幡迎。","代耕无补妨贤甚，归去容成小筑成。"]},{"t":"立春前一日喜雪","f":"七言律诗","c":["司寒颛帝职云虔，肯许勾神挠雪权。","双胜迎春犹卜夜，六花殿腊已书年。","太阳更不亏元日，圣德由来格上天。","惭愧小臣无补报，巴歌敢共郢争妍。"]},{"t":"和袁同年接伴谒洪泽镇龙祠韵","f":"七言律诗","c":["鬼神为德著冥冥，不在牲牷只在诚。","护客往来今九度，感神昭假等三成。","长安妥帖平于席，画舫夷犹稳作程。","应鉴微衷有孤愤，中原却隔泗州城。"]},{"t":"观新堡寨因登平山堂次接伴袁同年韵","f":"七言律诗","c":["换得玻瓈千顷湖，醉翁遗胜在江都。","登临山色依然在，拂略秋容澹欲无。","新堡似云屯戍久，旧臣何日策勋殊。","王人按垒非寻胜，归报前游有远图。"]},{"t":"访旧隐","f":"七言律诗","c":["自知樗栎任天材，閒爱浮萍静爱苔。","归有幽栖邻佛住，时因佳客下山来。","青云乳酒聊倾尾，白雪形盐旋摘梅。","有月有琴君勿去，百年怀抱待君开。"]},{"t":"买山石航海有怀故园","f":"七言律诗","c":["它山移却伴疏篁，磊砢坚于百鍊刚。","斸地尚馀苍藓篆，傍栏偏映紫荷囊。","湿云矫矫飞还凝，煇凤亭亭舞复翔。","竹弟石兄应共语，故园那得负风光。"]},{"t":"益老过灵岩看筑塘因慰藉小隐索诗","f":"七言律诗","c":["孤云一片自由身，古刹随缘有夙因。","小隐未容蚕作茧，灵岩要看海扬尘。","筑塘衣钵时时唱，信笔诗篇句句新。","昼绣不须归相里，闻师自是雁山人。"]},{"t":"题州宅安航","f":"七言律诗","c":["以涉名斋敢自遑，朅来何事得安航。","极知平地风波少，得似閒居气味长。","旋了儿痴便退食，聊为僧坐静焚香。","君恩未报空华发，孤屿扁舟忆故乡。"]},{"t":"潘德久将出疆之前三日移居作诗奉邀","f":"七言律诗","c":["久住京华似故乡，迁居又复一番忙。","此非子坐争悬榻，何以家为便出疆。","屋下已听湖水过，楼头不奈柳梢黄。","今朝元巳佳天气，试拨忙来共一觞。"]},{"t":"喜闻转庵新结暖阁因赋","f":"七言律诗","c":["老来百事一无能，寒燠随宜护寝兴。","小院回廊慵勃窣，围炉暖阁便瞢腾。","向阳挟策明开牖，隐几听歌厚覆凭。","闻道转庵新结束，宛同臭味我良朋。"]},{"t":"次韵转庵步城南有卜居依壑意乃古巽吉庵之旁","f":"七言律诗","c":["出郊缓步当乘流，依壑幽寻少饯秋。","水过斗门知浦口，庵当巽地见峰头。","赏心便拟为邻卜，志喜姑先著句留。","祇恐据鞍方矍铄，未容此处就菟裘。"]},{"t":"适庵","f":"七言律诗","c":["庵居奚以适为名，痒处能爬是适情。","社后有谁留去燕，春来何处不迁莺。","物情雅与閒相会，酒兴酣时句自成。","要识适庵同一切，客来不用举深觥。"]},{"t":"净光丈室开小窗颇得江山之胜次璧老壁间韵","f":"七言律诗","c":["车马憧憧走皂台，面皮三寸积黄埃。","禅房永日窗开阖，天际孤帆潮往回。","二月风光供远眺，十年羁旅惬重来。","现前一宿圆成案，懒向胡僧问劫灰。"]},{"t":"益老于雁山筑庵名曰来风小隐来求诗且约相见 其一","f":"七言律诗","c":["师住灵岩饱看山，结茅犹欲老山间。","悬知客路红尘软，输与禅房白日閒。","蔬笋忘来诗格瘦，枫梧落后鬓丝斑。","烦师护取龙湫水，待觅涓涓洗我顽。"]},{"t":"益老于雁山筑庵名曰来风小隐来求诗且约相见 其二","f":"七言律诗","c":["未终棋局烂腰柯，系日长绳竟若何。","报国有心祇皎洁，效忠无力恐蹉跎。","秋怀拟向樽前遣，归梦偏于马上多。","八月钱塘江上景，可能作意莫相过。"]},{"t":"邀德久兄灵芝纳凉","f":"七言律诗","c":["曾许西湖三百首，官身其奈苦相妨。","追陪岁月多遗策，零落风烟有断章。","人道拾遗无好句，天教老监学清狂。","且邀海内忘形友，领揽招提半日凉。"]},{"t":"高峰寺","f":"七言律诗","c":["四面峰峦玉斲成，团栾真是梵王城。","名山胜绝兹为冠，墨客冥搜远作程。","清酌献茶修薄供，摄心归敬誓馀生。","全家饱煖君恩重，佛日光中祝圣明。"]},{"t":"袁性之自号为湖山遗老曩和予北征绝句因与其族人赴举复见访坐间求书湖山隐居扁榜因为著语","f":"七言律诗","c":["湖山本为吾侪设，家世今为隐者居。","岁稔石田犹可饱，诗成霜叶正堪书。","因观后进鏖勍敌，肯访閒人款敝庐。","醉觅扁颜吾敢靳，和篇曾枉百砗磲。"]},{"t":"隐居即事有怀潮州三首 其一","f":"七言律诗","c":["屋后如屏拥碧岑，爱山叠石尚同心。","肩舆不解劳人力，振策惟便助足音。","未掷裹巾行晓色，不眠乘月坐秋阴。","幽忧莫道都无景，十月移春要满林。"]},{"t":"隐居即事有怀潮州三首 其二","f":"七言律诗","c":["载花航石自都城，惭愧波神每不惊。","官职有何消得处，园池亦只信缘成。","赏心择胜难扁榜，信口哦诗莫主名。","无奈新开城上路，江山如画总相迎。"]},{"t":"隐居即事有怀潮州三首 其三","f":"七言律诗","c":["忘形海内鲍潮州，迟次天教得共游。","行李未还长问讯，扶藜才过许赓酬。","湖光催我频携酒，花影何时傍结楼。","昨夜满庭秋月色，一年无此亦知不。"]},{"t":"为季和弟作溪堂扁榜赋唐律一首纪实","f":"七言律诗","c":["鸰原分派住松山，溪绕山围屋数间。","今少蓬成今宅相，旧将军写旧堂颜。","移来城市真堪贵，才混嚣尘便等閒。","教子教孙风月夜，琴书声里水潺潺。"]},{"t":"清卿求作混碧楼额因赋唐律 其一","f":"七言律诗","c":["三十声名晚合酬，前衔久自是潮州。","尚须汉吏二千石，聊卧元龙百尺楼。","混碧缪书波画去，醉红忆为海棠留。","从今只愿抟扶上，还许澄鲜守舍不。"]},{"t":"清卿求作混碧楼额因赋唐律 其二","f":"七言律诗","c":["欸乃声中自答酬，湖山迥阔冠吾州。","际天野色青环坐，照水岚光翠拥楼。","莲浦渺瀰无路到，松亭依约有船留。","澄鲜近市翻堪恨，混碧能容数过不。"]},{"t":"袁起岩侍郎采予无尽意诗语以一段奇为净相别室扁榜有诗次韵","f":"七言律诗","c":["一段奇中无尽意，西湖风月契三生。","只今扁榜成佳话，它日寻诗有旧盟。","得失鸡虫何日了，去来凫雁逐时更。","痴儿尚欠梅花句，已拟长歌出塞行。"]},{"t":"高秀才绅十年前有同邸之旧以剑名堂求诗","f":"七言律诗","c":["沙河灯火闇残更，客舍犹闻讽诵声。","科举累人须要了，词章似子岂无成。","勋名合是男儿事，通塞能忘造化情。","莫向斗牛占气采，夜深只愿少微明。"]},{"t":"范湘潭岸花楼","f":"七言律诗","c":["杜若青青湘水深，长官为政见瑶琴。","飞花几度春来去，行客自如人古今。","天池百年供旅寓，江山一色费登临。","楚峰驿伴湘中馆，更有高楼待赏心。"]},{"t":"侣鸥亭","f":"七言律诗","c":["世态浮云转首非，孰于静处见天机。","爱憎随俗乌能好，爵禄无心牛自肥。","此乐尚忧儿辈觉，斯人休祝我公归。","公如略起功名念，鸥鸟惊人已浪飞。"]},{"t":"题富览亭","f":"七言律诗","c":["万峰如鹜万波同，擘浪双鳌跃势雄。","山过江来垂斗柄，水朝宗去涣文风。","家家洙泗弦歌里，处处蓬瀛图画中。","莫笑先生徒壁立，一番登览兴无穷。"]},{"t":"登忆谢亭并呈质弟","f":"七言律诗","c":["争不游山忆谢公，亭成孤屿恰当中。","山低山仰今朝异，潮落潮生自古同。","几欲弄舟移白日，何当把钓待秋风。","惠连幸自还乡里，独恨池塘句不工。"]},{"t":"题春风亭","f":"七言律诗","c":["亭成秋日榜春风，岁稔时和荷化工。","佳事感伤多白发，壮怀突兀祇孤忠。","汉兴即有中天运，吏惰元无辟地功。","只把春风宣圣化，物华都在发生中。"]},{"t":"题外祖母夫人李氏墓陟屺亭","f":"七言律诗","c":["陟屺哀哀八十亲，渭阳念母我伤情。","等为孝子终身慕，最惨婴儿半路声。","已把山光占塾教，底须宅相写亭名。","登亭更望芙蓉顶，吹棘风前泪并倾。"]},{"t":"春晚登钤冈","f":"七言律诗","c":["簿书抛罢一登临，恰有黄鹂送好音。","溪涨未消知雨近，林疏顿密见春深。","诗源久废如枯井，宦况多磨似鍊金。","手种故围三四竹，新梢拂拂想成阴。"]},{"t":"游金山寺","f":"七言律诗","c":["何年浮玉奠中川，潮去潮来故屹然。","世事只随波上过，佛身元向定中圆。","妙高得月天无际，雄跨看云雨带烟。","孤屿扁舟无活计，又拿杨子渡头船。"]},{"t":"登江山伟观","f":"七言律诗","c":["江山如抱画难加，伟观标名似太誇。","千古云烟无尽藏，百年登览足生涯。","诗情与客来天际，潮汛邀人上斗槎。","自是皇恩聊许借，儿童莫便认吾家。"]},{"t":"题石乳洞","f":"七言律诗","c":["山前老石碧巑岏，山后萦纡洞府宽。","妙处通行随步武，到头平坦上团栾。","宝钟池秘金为奏，甘井天成玉作栏。","古怪洪阳清石乳，平章留与后人看。"]},{"t":"游仙都","f":"七言律诗","c":["我来古括经行熟，欲到仙都有底难。","漫道蓬莱环弱水，始知方丈近三韩。","千山开阖神仙迥，一柱岧峣宇宙寒。","信有真人足官府，不妨容我暂鞭鸾。"]},{"t":"初入雁山见双峰","f":"七言律诗","c":["钟鼎山林昔罕兼，久污清贯大伤廉。","移文谢客颜情厚，弹劾归耕喜属餍。","才下盘山为邑里，已排胜境入诗签。","年来百虑消磨尽，只有双峰不退尖。"]},{"t":"再游雁荡观双峰","f":"七言律诗","c":["不到双峰一纪年，梦随清磬上高圆。","重来惯识羊肠路，兀坐慵谈兔角禅。","欲刬旧题无好语，羞将华发照清泉。","男儿问学全无用，愧尔耕夫垦石田。"]},{"t":"游南明山","f":"七言律诗","c":["路上崔嵬断复连，危亭却立虎溪边。","石梁架厂疑无地，岩窦梯云欲近天。","客子诗情专物色，老僧禅悦解行缠。","亦知太与尘凡隔，时遣钟声落市廛。"]},{"t":"下四十九盘","f":"七言律诗","c":["了知四十九年非，七七盘中共一机。","世路险夷行处是，身名荣耀眼前稀。","此生待足何时足，平日思归今得归。","厚禄故人如问讯，为言留得故山薇。"]},{"t":"春园","f":"七言律诗","c":["用世无功孰取材，诛茅作计剔荒苔。","花随浅绿流春去，山拥新青入坐来。","宽辟轩窗便过夏，高藏书画待经梅。","菊苗先晚丁宁种，更要秋光次第开。"]},{"t":"喜子仪侍郎同游","f":"七言律诗","c":["拟访南山自北山，长堤信马只如閒。","画船瞥见矜红粉，紫燕惊飞透白鹇。","三过名园成选胜，再临高阁似知还。","兹游不负花时节，寡和阳春更许攀。"]},{"t":"题洪阳洞","f":"七言律诗","c":["划开灵怪几千年，传与洪阳二老仙。","石室尽头真境秘，天窗明处葆光圆。","乳泉煖滴烧丹井，芝径畦分种玉田。","不是到来须束火，故应名胜限嚣廛。"]},{"t":"闻转庵游西湖奉寄","f":"七言律诗","c":["马上春光过若驰，不须纪历校花时。","青于前日长街柳，白似去年双鬓丝。","强学后生须藉酒，苦邀同社索题诗。","朝回要便西湖去，输与安仁尚黑髭。"]},{"t":"酬常之换韵和江心寺诗","f":"七言律诗","c":["千峰屏绕浪环铺，莫把金焦作对呼。","绝境谁窥全体现，小亭人号媚川图。","市声非远尘难到，塔影虽双屿只孤。","大似橘洲浮不去，岳根元插赤沙湖。"]},{"t":"再次常之换韵题江心寺诗","f":"七言律诗","c":["山川如画镇长铺，每坐危亭谓笑呼。","大艑扬帆飞略彴，巨鳌出水载浮图。","锦袍仙想前峣古，饭颗神游绝境孤。","不是谢公亲历览，相忘祇竟渺江湖。"]},{"t":"媚川图亭上观江心寺","f":"七言律诗","c":["三山海上失双峰，插作中川镇水龙。","高出赭垣尊御寝，长拖粉庑过僧筇。","夜敲图绕千灯磬，晓击声闻两岸钟。","莫恨无缘随展钵，时来亭上足从容。"]},{"t":"某谬题媚川图江心寺晚荷仲归兄依韵宠和至再愈工勉酬厚意终惭辞费","f":"七言律诗","c":["孤亭面直海坛峰，真睹龙翔瑞应龙。","长羡僧行图上境，不劳杯渡水边筇。","推移日月东西塔，透彻天渊昏晓钟。","妙处难将声相见，吟摹终恐费形容。"]},{"t":"酬翁常之和媚川图上观江心寺诗","f":"七言律诗","c":["江北屯云翳列峰，江心灵雨走神龙。","已拚阮子一生屐，更倚仙人九节筇。","晻霭孤帆昏野渡，霏微两塔湿疏钟。","何须小米模糊笔，潘令新诗足写容。"]},{"t":"送吴待制安抚襄阳 其一","f":"七言律诗","c":["天借琳琅镇上流，西风作意送行舟。","去看岘首何因感，遥见长安却是愁。","平昔勋名期带砺，向来谈笑饱貔貅。","轻裘少展筹边略，归问君王觅酂侯。"]},{"t":"送吴待制安抚襄阳 其二","f":"七言律诗","c":["如君自是急难材，牛斗光芒未烛台。","何以家为人咄咄，维其时矣诏来来。","临湖尽去封侯橘，度地先栽调鼎梅。","恶语流传真引玉，满怀明月向人开。"]},{"t":"送何正言持节湖南","f":"七言律诗","c":["山庄寂寞信惊猿，鹓鹭行疏亦断魂。","持节过家天借便，引嫌得请帝疏恩。","湘云开处峰峰好，谏纸藏来字字温。","只恐夜深思贾傅，长沙宁久驻轺轩。"]},{"t":"送赵端明帅蜀","f":"七言律诗","c":["谋深无位可酬功，端殿几廷礼数同。","尽以四川归节制，重乘九折见精忠。","平生清白天垂相，简在登庸帝降衷。","万里桥头莫言远，恩波只在大江通。"]},{"t":"送邹国遂武博知濠州二首 其一","f":"七言律诗","c":["长髯如戟气如虹，只欠吾曹抹额红。","右序谈兵瓴建水，上前论事殿生风。","恳辞射策登宾阁，乞许分符立战功。","他日濠梁真得意，要看鱼水得君同。"]},{"t":"送邹国遂武博知濠州二首 其二","f":"七言律诗","c":["孤屿秋风忆钓蓑，因君理棹起劳歌。","分留乡思从兹始，报答君恩奈若何。","陶令篱傍犹有菊，伯龄石上苦无禾。","问言何补青蒲事，为道新来白发多。"]},{"t":"送毛监丞知漳州","f":"七言律诗","c":["参裨不解力吹嘘，掺别何劳叹索居。","子去定为慈父母，邦人应得乐田庐。","临漳从此无苛吏，严濑曾闻治猾胥。","暇日若亲横槊赋，为言珍重百砗磲。"]},{"t":"送胡司谏同年赴湖北漕","f":"七言律诗","c":["洞庭青草碧相连，使节经行别有天。","又辍谏官湖外去，要苏民力未央前。","一枝腊雪边江驿，百丈春潮上水船。","小驻轺轩私雨露，司存及早侍甘泉。"]},{"t":"送潘德久都干为贺生辰使属","f":"七言律诗","c":["乃翁旧取燕山第，子恰从人去使燕。","孽子孤臣应有泪，祖功宗德本无边。","离离故国摇鞭影，耿耿新诗贮腹便。","父老相逢勤劳苦，为言咫尺中兴年。"]},{"t":"送张子仪尚书镇福州","f":"七言律诗","c":["暂违天陛星辰履，便上春风李郭船。","两地逼人真勇退，三山去路俨登仙。","循环花甲趋庭日，遗笏棠阴在镇年。","盛事相望已无匹，宝奎新赐更光前。"]},{"t":"送直院楼尚书同年以阁学知婺州二首 其一","f":"七言律诗","c":["受敌词章八面全，庆元书诏四方传。","星辰听履聊纡步，笔墨论功即化权。","将母愿为符竹计，投诚径缴冕旒前。","暂烦明月双溪照，两两台星尺五天。"]},{"t":"送直院楼尚书同年以阁学知婺州二首 其二","f":"七言律诗","c":["隆兴最盛初元榜，当日曾推第一人。","出世经纶知几佛，看君意度不无神。","居然勇退非惊俗，行矣追随亦为亲。","只恐苦无明月句，经行难作隐侯宾。"]},{"t":"送禹之皋之舅赴调二首 其一","f":"七言律诗","c":["我是次公门下客，登龙因许与乘龙。","只今击柝从关吏，渐可扶犁作老农。","莫报黄垆埋白玉，满看清庙列金钟。","二难自是从来誉，勉事功名定亢宗。"]},{"t":"送禹之皋之舅赴调二首 其二","f":"七言律诗","c":["九年清梦落鸣珂，尊酒相逢奈乐何。","但恨醉人成谬误，莫嗔惊汝感摩挲。","行装忽指吴门道，别意今随楚水波。","若访水仙逢处士，为言新句苦无多。"]},{"t":"用楼尚书韵饯同年曾寺丞守温州","f":"七言律诗","c":["三十三年同日喜，忆曾书札问淮堧。","造朝合究三千牍，出守聊违尺五天。","官舍君应思系马，家山我亦念斜川。","政成的有天官列，不拟攀辕拟执鞭。"]},{"t":"送刘东玉提干之官茂苑","f":"七言律诗","c":["共论隶古弄文漪，酌别宁忘载酒卮。","去去台中摅婉画，行行箧里富新诗。","向来阀阅多丹禁，岂有人门后白眉。","九万扶摇从此始，他年书劄问茅茨。"]},{"t":"送石谦伯就许襄阳辟","f":"七言律诗","c":["襄阳耆旧流风在，幕府文书并省馀。","勿以脩涂愁泛宅，不妨胜处憩安舆。","碑存岘首堪怀古，诗忆槎头匪为鱼。","万里功名从此始，勉旃声价百砗磲。"]},{"t":"送郑仁叔宰长溪","f":"七言律诗","c":["清于道骨澹于僧，海内忘形得此朋。","作县只如诗思苦，能官已被荐书腾。","下车搏虎真堪笑，入境无蝗定有称。","我亦孤愚谙此味，愿言加饭履春冰。"]},{"t":"黄叔万知县以鲁名斋求诗将赴公安并以为饯","f":"七言律诗","c":["堂堂张也竟难为，一唯工夫鲁得之。","得兔故应忘百虑，亡羊正尔失多歧。","千林摇落青还在，孤月当空影自随。","昔日校官今作县，鲁斋行处即吾师。"]},{"t":"送王子大知县","f":"七言律诗","c":["金闺通籍绾铜章，荔子黄时恰到乡。","僧夏相期尘外住，官期将趣橐中装。","倾心栖棘仇香地，侧耳鸣弦单父堂。","说著江西如故里，南城春色胜河阳。"]},{"t":"送余伯益知县","f":"七言律诗","c":["建章万户及千门，博物如君自不群。","入幕向来争论荐，鸣琴此去定知闻。","官惟作县堪行志，闽独于盐害未分。","剖竹乘轺同臭味，愿求长策献吾君。"]},{"t":"送郑节卿赴新喻丞并呈李谏议","f":"七言律诗","c":["南漳抚字溢三年，当路文章喜荐贤。","鹤发有亲须禄养，鹗书无地足常员。","为丞盍过滕王阁，诣府欣依刺史天。","谏议恩深曾一顾，烦君为我道拳拳。"]},{"t":"送郑廷玉教授之官邵武","f":"七言律诗","c":["太学声名十五年，鸡林副墨竞流传。","诸生定满升堂履，独冷何愁坐客毡。","预恐上方催给劄，便应西笑去朝天。","君王若问安边策，上药良医有十全。"]},{"t":"沈架阁席上送沈教授之官邵阳二首 其一","f":"七言律诗","c":["祝融七十二峰尊，诸老相望古道存。","二邵人才元有种，三湘风物向曾论。","先生此去行师说，弟子从今记善言。","为访衡山戴监岳，可能略不傍华轩。"]},{"t":"沈架阁席上送沈教授之官邵阳二首 其二","f":"七言律诗","c":["郡侯名字祖鞭先，郡倅风流世有传。","更著广文铛脚坐，亦怜委吏鼎科年。","江山莫道非吾土，官舍曾无有此贤。","自是蓬莱山上客，枉教予作送行篇。"]},{"t":"送简寿王主簿之官番禺","f":"七言律诗","c":["住久江西近物情，闻名虽旧盖初倾。","未听健论折髯喜，况有新诗出袖清。","为簿免从高士例，饮泉要改昔人名。","为言牧伯乘骢旧，愧尔传家折槛声。"]},{"t":"次韵临川傅簿经过道旧之什","f":"七言律诗","c":["倾盖临川卜再逢，岁华飘忽老秋风。","汗颜何补千人聚，过眼还惊万马空。","今子所淹栖棘地，曩余曾掌采芹宫。","种松已长烦公问，梁栋如今中未中。"]},{"t":"送鲍清卿运干调官还里二首 其一","f":"七言律诗","c":["笔端有印印金泥，榜榜名高米样齐。","两郡漫游官似水，七阶懒觅荐为梯。","登瀛已近帆惊转，入幕虽卑首愿低。","举士引嫌堪自愧，眼看湖海放凫鹥。"]},{"t":"送鲍清卿运干调官还里二首 其二","f":"七言律诗","c":["家住城南水竹村，羡君月榭与风轩。","头颅已料书生骨，言语难酬明主恩。","何日致还归里社，也教依样买山村。","弹边求炙君怜我，许种名葩寄后园。"]},{"t":"送范南宫守彭归蜀","f":"七言律诗","c":["起草南宫著作庭，历阶亦合侍承明。","乞身只拟分符去，持节何妨衣锦行。","道在不孤知己旧，才难偏怆语离情。","极知便下思贤诏，其奈巴江白发生。"]},{"t":"送黄元章秘书还馀杭待次荆门","f":"七言律诗","c":["蓬莱云色正飞浮，猛乞分符向玉州。","抵鹊信嫌三献辱，如虹肯要万金酬。","勋名不朽山为砺，轩冕随缘芥作舟。","却憾渥洼求汗血，不如天厩出骅骝。"]},{"t":"送郑节推胜弃职归省","f":"七言律诗","c":["慷慨中原泣夜阑，一门忠孝只南冠。","来归九死赊犹易，就养一官轻底难。","幕府礼罗留莫住，清时长铗惜休弹。","男儿富贵寻常事，要取功名与世看。"]},{"t":"送郑南秀解秩东归","f":"七言律诗","c":["小麦茸茸短覆泥，如何熟得济民饥。","青黄未接我狼顾，黑白既分君解龟。","已拜一言真苦口，极知三折是良医。","从今洗眼看华要，书札无忘慰梦思。"]},{"t":"送谷仲归谦谢以诗次韵奉酬","f":"七言律诗","c":["一乐长存抵万金，百年谁肯放愁侵。","饭蔬饮水真吾事，怀宝迷邦岂本心。","桑户琴歌奚此极，孔门弦诵有遗音。","新诗当暑时时至，每读清风自满襟。"]},{"t":"送解省元赴南宫","f":"七言律诗","c":["过庭有子即同登，学圃承家岂足称。","刻画无盐容更丑，宠光蕙草句全胜。","名场自此一投足，宦路不须三折肱。","累月笞儿吾岂敢，短檠犹可课秋灯。"]},{"t":"送林定国赴秋试","f":"七言律诗","c":["读却床头满架书，时文元不费工夫。","向来点额关奇数，今日焚舟合壮图。","去去秋风趋北阙，行行春色满西湖。","痴儿未了书生事，珍重青衫报国躯。"]},{"t":"送刘守之上舍赴试","f":"七言律诗","c":["乃翁壮誉动贤关，晚把州麾苦要閒。","细字尚陪灯火课，淡书端要姓名攀。","扶摇稳泛鱼三级，文采曾窥豹一斑。","舍弟若为同日喜，两家亲老想开颜。"]},{"t":"次韵饯振之之行","f":"七言律诗","c":["半生经吏竞分阴，奏牍三千几汗青。","技到屠龙从俗笑，志存流水有人听。","故园勋业千株橘，世路生涯一草亭。","却笑刘商长得醉，为无管属爱浮萍。"]},{"t":"送安福刘秀才谋卿仍简分宜傅公谋","f":"七言律诗","c":["昨夜西风入楚扉，登临游子倦将归。","璧廱未顿新书笥，锦里还寻旧钓矶。","平世勋名赊马革，男儿贫贱且牛衣。","傅岩词客如相问，说是今非昨更非。"]},{"t":"送德友之长沙章贡并怀薛叶二兄","f":"七言律诗","c":["篇章足可慕渊明，其奈田无二顷耕。","甥馆久居谁厌汝，客涂远问我怜生。","湘山物色留新句，使节绨袍有故情。","并语郁孤东道主，春风吹梦到容成。"]},{"t":"送陈西老西上并简张功甫","f":"七言律诗","c":["二月春光韵管弦，琴书独上馆头船。","箧中未有西湖句，阙下曾传乐府篇。","名胜难逢分手易，游从虽晚服膺先。","有如尚待金门诏，须访南湖桂隐仙。"]},{"t":"中川席上送陈同甫","f":"七言律诗","c":["眼底男儿隘六区，似君豪气有谁如。","中原赤子头今白，天下苍生力未纾。","北阙有书流涕上，西山无地带经锄。","共谈世事何时了，劝子加餐返故庐。"]},{"t":"送俊老再住惠因","f":"七言律诗","c":["天台自是金仙窟，而况师曾住惠因。","祖令全提馀作略，旧营重按想精神。","绝怜老宿参辰象，何限名蓝甲乙人。","若遇毒龙师摄取，经行杯渡熟知津。"]},{"t":"送清监寺往平阳化缘清乃王詹事女","f":"七言律诗","c":["詹事家中灵照女，月圆会下祖师禅。","一条见地如丝直，百架脩廊尚结缘。","飞锡先从坳里去，掷杯聊当渡头船。","更于何处求真佛，说似檀那领现前。"]},{"t":"喜德久从人使北来归","f":"七言律诗","c":["诗翁万里恰归来，涤面那无一点埃。","生马谙骑便武事，故京熟览动诗才。","别来我已成炊梦，此去君应悟劫灰。","见说北庭犹假息，可无尊酒沃崔嵬。"]},{"t":"和袁同年接伴赓从客陆成文韵","f":"七言律诗","c":["雁塔题名不记年，相从淮海喜跫然。","了知鹏鴳悬微分，祇觉夔蚿有故怜。","共泛仙舟凌浩渺，赓吟醉墨堕芳鲜。","少游陈迹无寻处，小五湖中水拍天。"]},{"t":"和袁同年接伴赓从客霍希文过楚州韵","f":"七言律诗","c":["一水分流西复东，画船随水去匆匆。","晚风鼓角增悲壮，高垒营屯足长雄。","粮道已无清口应，舟师会把朔庭空。","眼中方略全图在，未肯轻将属画工。"]},{"t":"次韵袁同年回程见示","f":"七言律诗","c":["秋风日日动诗情，人与诗篇一样清。","归去星辰添秀润，经行草木倍精明。","河山未阂功名志，岁月徒催鬓发生。","送客微言何足录，便将佳句榻前呈。"]},{"t":"吴门次韵颐刚严陵留别过新安","f":"七言律诗","c":["功名破甑等虚空，身世随缘邴曼容。","行色过于秋澹薄，离情恰似酒醇浓。","想君时看水西景，顾我方听夜半钟。","莫计升沉须强饭，男儿爱惜鬓星松。"]},{"t":"因振之之行过新昌怀鲍清卿","f":"七言律诗","c":["新昌令尹鲍参军，中的声名孰似君。","未免徒劳纡墨绶，不教平步上青云。","句如冰柱当庚伏，心似秋空纳世氛。","岂为求齐工鼓瑟，知音合遣九霄闻。"]},{"t":"怀转庵饯客","f":"七言律诗","c":["一水经行昔饱谙，故乡真似是淮南。","杏花岩畔春携酒，杨柳堂前夜驻骖。","邻境不停科甲马，吾民常喜足田蚕。","风谣物色堪诗句，饯客归时问转庵。"]},{"t":"南省帘外唱和五首 其一","f":"七言律诗","c":["句读江西独亢宗，笔裨造化蚤论功。","相逢客已传河尹，未见天教忆戴公。","欻讶鞭鸾仙尚散，犹怜小草味能同。","明朝遣客方公事，醉墨何妨落暮鸿。"]},{"t":"南省帘外唱和五首 其二","f":"七言律诗","c":["寒似西来不立宗，酒兵屡敌故难功。","诗成染笔能忙事，勘罢糊名也自公。","细雨烧灯惊节过，清尊华发与君同。","故园花讯新来少，欲问平安无过鸿。"]},{"t":"南省帘外唱和五首 其三","f":"七言律诗","c":["画史何人更姓吴，梁园重与续成图。","晴泥正好一犁雨，归思还先六幅蒲。","院锁馀寒春力峭，书残午后客情孤。","新诗剩喜相料理，已觉胸中隘五湖。"]},{"t":"南省帘外唱和五首 其四","f":"七言律诗","c":["桃李枝头锁冱寒，天工一笑发嫣然。","唤回雪苑阳春脚，幻出琼壶小有天。","欻看南图羊角上，恍思西抹阿婆年。","政须点勘频呵护，准拟开函近御筵。"]},{"t":"南省帘外唱和五首 其五","f":"七言律诗","c":["不因呵手轴书帘，颛帝司寒盍解严。","已放官梅撩杜老，更堪园柳忆陶潜。","定无裁鉴追王谢，敢别妍媸摈嫫盐。","尔许空餐已知愧，底须自喜作沾沾。"]},{"t":"次韵留守刘观文鹿鸣之什","f":"七言律诗","c":["一时天府姓名登，三载文翁礼俗型。","已著衮衣亲劝驾，更施燕席共谈经。","杏园路逐三春暖，星汉槎通八月灵。","圣策若询黄发老，为言轻重系朝廷。"]},{"t":"刘正言讲筵视职初直玉堂见案上所和高紫微阳字诗宠和二章见示因用韵答以一首深愧短拙","f":"七言律诗","c":["措世规模岂小康，八荒寿域万年觞。","谏行膏泽苕溪水，讲劝渊源养浩堂。","遇合共欣鱼纵壑，阔希真见凤朝阳。","檐花细雨金銮直，预卜为霖喜色黄。"]},{"t":"次韵常之岁晚督才叔诗课","f":"七言律诗","c":["流年舍我疾于飞，受岁于予孰敢违。","有愧渊明新觉是，自怜伯玉旧知非。","盍簪烈炬昏骑马，博簺相欢夜倒衣。","岂复少年豪气事，诗坛聊为解坚围。"]},{"t":"次韵卢次夔直学投赠二首卢之父有师法方训长孙铸而次夔近绎子屈致教参孙发蒙 其一","f":"七言律诗","c":["大难过访忆曾酬，谒入徒惭刺字留。","惠我新诗堪照夜，喜君逸气正横秋。","时哉好去陈三策，老者那能画一筹。","暇日太丘如共款，忘炊肯更作糜不。"]},{"t":"次韵卢次夔直学投赠二首卢之父有师法方训长孙铸而次夔近绎子屈致教参孙发蒙 其二","f":"七言律诗","c":["老眼青灯字字愁，犹能宅胜复栖幽。","要追野叟田夫辈，愿作渔乡橘里侯。","蚤取科名辞举业，来陪散吏入诗流。","小孙勤苦童蒙训，未解知名杜若洲。"]},{"t":"约转庵","f":"七言律诗","c":["半夜月明晨起风，不眠附火鬓搔蓬。","窗虚洒急疑霰集，閤暖香微知菊丛。","便拟南枝开摘索，只愁卯酒醉冬烘。","行吟真爱亭前路，梅蕊已如椒子红。"]},{"t":"谢观复长髯垂膝俨然山泽之癯弃去儒业从皇甫道士于庐阜余见之三茅以所编老君实录见赠赋此奉酬","f":"七言律诗","c":["真是儒仙薮泽姿，长髯合住谢家池。","香炉峰下看云坐，碧玉壶中倒景窥。","妙旨五千归日用，纂言十万见宗师。","故交幡起逃儒恨，不值青藜夜访时。"]},{"t":"酬刘孝若二首 其一","f":"七言律诗","c":["春去堂堂已浃旬，幽花耿耿尚能春。","细思造物尤恩我，晚著家山剩庇身。","客至情亲惟话旧，诗成意足不求新。","长年道路多疏隔，如子相过正要频。"]},{"t":"酬刘孝若二首 其二","f":"七言律诗","c":["回首城南同舍时，参辰相望更为谁。","杜门正愧衰兼懒，枉句多惭颂不规。","新竹筛金鸣粉箨，初荷擎盖弄纹漪。","小园景物堪供给，剥啄何时共说诗。"]},{"t":"次韵酬王宣甫","f":"七言律诗","c":["老去才衰非曩时，如今何处有新诗。","陶溪已过黄初作，漳浦曾同郑老期。","近喜高轩能肯顾，翻催归棹起相思。","杖藜固有慇勤约，逸驾愁难十驾随。"]},{"t":"奉酬沈仲归","f":"七言律诗","c":["刘墙屈垒敌金汤，今继薰风写拒阳。","久住扬州诗富艳，暂归孤屿句清凉。","檐声叠喜随花落，野色方期共竹光。","偶苦河鱼今少愈，不应樽酒负鹅黄。"]},{"t":"次韵酬才叔仍送酒","f":"七言律诗","c":["逸驾翩翩莫可攀，飞腾岂久住乡间。","秋风便起东西玉，郢雪姑吟大小山。","仅喜借居邻竹院，能无持酒到松关。","楼成约共鱼轩过，急遗双壶且破颜。"]},{"t":"再用韵酬才叔","f":"七言律诗","c":["试听剥啄莫寻推，竹院来过更有谁。","紫凤迎门披裋褐，小龙入臼破新规。","映空白鹭排青障，照水黄鹂点碧漪。","春去自应留物色，眼前何事不供诗。"]},{"t":"融州和孝若韵见寄并谢真爱赏梅之集复次韵奉酬 其一","f":"七言律诗","c":["城南家训不籯金，曾共青灯课夜吟。","往行二刘元作则，后人六艺尽师心。","经传乡派源流远，诗到孙枝志思深。","玉润风流今鲍叔，卜邻佳处到于今。"]},{"t":"融州和孝若韵见寄并谢真爱赏梅之集复次韵奉酬 其二","f":"七言律诗","c":["同病齐年各老成，喜君勿药近安平。","篮舆不惜寻梅过，藜杖何妨倒屣迎。","潘令剧谈听至夜，刘郎新句和来清。","疾行每愧穿杨手，金榜君居第十名。"]},{"t":"次韵酬石谦伯二首 其一","f":"七言律诗","c":["拂云著句未能奇，聊为溪山且发微。","过矣琼瑶烦答赠，居然怀袖有光辉。","经时苦雨无佳思，几日占晴望落晖。","石友不来春自老，登山临水送春归。"]},{"t":"次韵酬石谦伯二首 其二","f":"七言律诗","c":["石兄兄石不兄钱，卜筑山边复水边。","位置亭台依茂密，剔疏岩壑听潺湲。","拂云脩竹还通月，擎盖高松不记年。","预恐陶君回俗驾，拟乘下泽疾驱前。"]},{"t":"酬木伯初仍简才叔常之","f":"七言律诗","c":["惠我诗章有琢磨，传家学力见功多。","恍惊社里摛文手，夺得天边织锦梭。","竞约芳洲容与戏，预欣清夜醉时歌。","熏蒸浪泊看鸢堕，不念垂垂老伏波。"]},{"t":"次韵酬潘才叔","f":"七言律诗","c":["杜老添愁怜晦日，阆仙不睡惜残春。","闰馀宽我花枝眼，年事逾君卦气身。","架上酴醾香已歇，阶前红药色方新。","新晴肯访山园否，闻健闻閒莫厌频。"]},{"t":"再酬同社","f":"七言律诗","c":["殷勤春事尚弥旬，岂是榆钱买得春。","映水残阳开句眼，满园新绿庇花身。","论文把酒交情旧，对弈忘机局面新。","信笔题诗无好语，多情乌鹊喜声频。"]},{"t":"酬沈仲归 其一","f":"七言律诗","c":["曾倚平山望远峰，桥过真主昔回龙。","词翻十事温卿阅，句敌三都蜀岭筇。","置驿家风罗四面，挥毫帅守角千钟。","来归肯作萧閒伴，一诵新篇一起容。"]},{"t":"酬沈仲归 其二","f":"七言律诗","c":["田家渴雨望云峰，掣电驱雷起蛰龙。","喜极三农俱合爪，争扶百拜各抛筇。","先生不用愁经笥，老子惟须办饮钟。","换韵题诗应有句，何人起舞为予容。"]},{"t":"次韵酬梅南寿旧曾和予梅花词","f":"七言律诗","c":["衣钵欧梅无别峰，天悭发处妙屠龙。","琼瑶有句传商鼎，金石留声在蜀筇。","三叹少曾赓俚曲，五音全得列编钟。","末章压倒君馀事，不道承家有愧容。"]},{"t":"自和","f":"七言律诗","c":["净尽繁红但碧峰，药栏犹有绿盘龙。","风光何限供吟笔，霜鬓尽添宜老筇。","岂必愁来方酌酒，底须句到始撞钟。","閒中作乐真吾事，多谢天工久见容。"]},{"t":"用韵酬常之才叔","f":"七言律诗","c":["西山爽气挟莲峰，碍眼何尝恕箨龙。","近种猫头未成竹，拟求人面替扶筇。","春归意绪愁千斛，病起情悰酒一钟。","莫话朝鸡萌妄想，形骸老丑若为容。"]},{"t":"酬翁常之次韵","f":"七言律诗","c":["云间声价仰高峰，今向诗中识士龙。","传诵废餐惟阁笔，行吟须杖转思筇。","晚欣乡里才华盛，故是江山秀气钟。","竹院过从烦答似，坐来起敬有羞容。"]},{"t":"再酬梅南寿","f":"七言律诗","c":["看云注日爱奇峰，撼壁鱼梭欲化龙。","凤沼催诗欣在手，骊珠夺目急扶筇。","老惭尚窃祠庭禄，閒觉惊闻夜漏钟。","报答一春无好语，更怜同社曲优容。"]},{"t":"用韵酬常之","f":"七言律诗","c":["老惭匿影爱岚峰，已愧家声昔二龙。","凿井得泉思种橘，寻河知路记因筇。","加餐漫说囊中法，应俗多违饭后钟。","同社朋来欣已诺，何时倒屣却从容。"]},{"t":"叠用韵酬常之","f":"七言律诗","c":["迢迢起顿两三峰，石窟门边有断龙。","致爽君能豪拄笏，策疲我愧老支筇。","论诗句句谐唐律，举酒时时敌汉钟。","谢客分留馀物色，可能无意更形容。"]},{"t":"用韵酬侯居甫","f":"七言律诗","c":["玉树风前映玉峰，吾家安得此乘龙。","书林未照青藜杖，甥馆肯陪高节筇。","归棹喜闻明月载，哦诗想带夕阳钟。","从今社里添光宠，咳唾珠玑有仲容。"]},{"t":"再用韵酬居甫","f":"七言律诗","c":["凌云健笔耸云峰，夺得标归信是龙。","官似梅仙非素隐，山经谢屣伴栖筇。","柳边待起明光草，花外要闻长乐钟。","暂肯闻閒入诗社，来篇三复叹南容。"]},{"t":"酬郑千之","f":"七言律诗","c":["契托尊公千佛名，思瞻生气属丹青。","爱君克肖充眉宇，将母通家过里亭。","难韵更能陪我和，苦吟想见彻邻听。","勉传衣钵穷年计，入学元非一仲丁。"]},{"t":"自和","f":"七言律诗","c":["扰扰人生漫百营，思量蒲柳岂长青。","四时代谢真邮传，百岁光阴寄客亭。","眼底浮华非我有，静中真乐要人听。","故吾不惜全还我，二十三前是白丁。"]},{"t":"和居甫仍喜其得雄","f":"七言律诗","c":["归巢倦翼底须营，家近容成取次青。","笑我崎岖山上路，羡君潇洒竹间亭。","弄璋已觉门阑喜，引玉尤惊里巷听。","得子且欣容易养，庚壬乙丙况藏丁。"]},{"t":"德久寄南游诗卷内和丁字韵凡九因次韵寄酬","f":"七言律诗","c":["三径虽荒可更营，归来因得课樵青。","岩栖宁著高低屐，世路怕过长短亭。","厚禄故人新枉句，高山流水旧知听。","案头展卷勤收拾，却恐天官敕六丁。"]},{"t":"酬常之","f":"七言律诗","c":["连朝晴霁有何营，静对脩篁照眼青。","旌节花迎门外客，发扬荷傍水边亭。","双呼鸠语元无据，一个蝉声已可听。","鹊鹊飞来还送喜，吉丁新句遣家丁。"]},{"t":"奉酬常之仙药课畦丁之什","f":"七言律诗","c":["在勤生计合勤营，手斸山园药甲青。","首辨君臣严位置，次看炎冷各调亭。","有身为患那能见，未说能仙自喜听。","肘后传来须记取，种时端是戊衔丁。"]},{"t":"酬孝若","f":"七言律诗","c":["自笑求田了不营，竭赀结屋为山青。","尚怜远岫光倾座，犹欲平崖稳著亭。","同社唱酬虽数至，扣门剥啄未尝听。","故交要识今吾面，不是遗民即隐丁。"]},{"t":"酬南寿 其一","f":"七言律诗","c":["穷当坚似亚夫营，谁似任安事卫青。","欲使威仪还汉旧，未伤风景隔新亭。","功名薄处书慵读，志节高边我爱听。","过午尚思茶一碗，休将后蔡比前丁。"]},{"t":"酬南寿 其二","f":"七言律诗","c":["身世悠悠莫苦营，是他松柏只长青。","宽于茧瓮茨为舍，大似鸡栖草作亭。","虫臂鼠肝元自定，龟毛兔角惯曾听。","胪传天语君须记，第四科名合是丁。"]},{"t":"仲归以结局丁字韵二诗七夕乃连和四篇至如数奉酬 其一","f":"七言律诗","c":["年衰病怯思怔营，惟见诗筒眼便青。","连和旧篇才结局，高吟新月恰当亭。","敢轻勍敌婴生力，正恐陈言厌熟听。","入社莫言诗殿后，此时孤律梦方丁。"]},{"t":"仲归以结局丁字韵二诗七夕乃连和四篇至如数奉酬 其二","f":"七言律诗","c":["君诗纪律似坚营，气王东南帜赤青。","涌思急于流峡水，疾驰快似速邮亭。","想当惬意须频读，说与齐眉更喜听。","击钵工夫胜刻楮，卖文却笑隐吾丁。"]},{"t":"仲归以结局丁字韵二诗七夕乃连和四篇至如数奉酬 其三","f":"七言律诗","c":["年逾卦气易身营，除一君犹鬓发青。","岂但文章难匹敌，只量筋力敢秤亭。","诗如博弈聊贤已，调似渝歌且易听。","除却吟哦无一事，斋心惟敬六神丁。"]},{"t":"仲归以结局丁字韵二诗七夕乃连和四篇至如数奉酬 其四","f":"七言律诗","c":["聘钱犹欠入驱营，野语传讹乱史青。","河鼓牛郎隔河汉，成桥乌鹊为津亭。","随缘乐事从心赏，妄想佳期莫耳听。","见说老人星合见，更占秋丙看春丁。"]},{"t":"次韵湘西许老","f":"七言律诗","c":["困倚床头未当痴，结庐取次不涂茨。","常留真火添丹灶，任使清霜上两眉。","入市有钱时施药，还家无藁自吟诗。","不因乘兴来过我，老子姓名谁得知。"]},{"t":"次韵王宣甫","f":"七言律诗","c":["佳句驰来合斩关，家童岂得嫉渠顽。","好怀偶苦催租至，厚意虚教垂橐还。","近社赓酬几寂寞，旧诗涂改廑斓斑。","转庵方示维摩病，犹望崇斋大小山。"]},{"t":"次韵孝若谢报谒二首 其一","f":"七言律诗","c":["访旧论交忆断金，闭门宣想日高吟。","应思后牧长回首，更学阴何苦用心。","顾我自知经世浅，如君何苦爱人深。","相逢休说东山话，已觉昨非犹至今。"]},{"t":"次韵孝若谢报谒二首 其二","f":"七言律诗","c":["如悬夜雨润冬晴，菜本朝来翠浪平。","菊老容成宜退听，梅开真爱欲相迎。","拥炉静坐心非想，把笔题诗思过清。","写寄城西老朋友，数能过访不无名。"]},{"t":"次韵卢康伯别家塾后示惠二诗 其一","f":"七言律诗","c":["投老投閒袖久通，何妨搔首鬓如蓬。","故人索我形骸外，春事开予笑语中。","别去未几情似阔，诗成倏至福何洪。","倦从远役宁株守，人讶相从臭味同。"]},{"t":"次韵卢康伯别家塾后示惠二诗 其二","f":"七言律诗","c":["如君摸索不难知，匡鼎来时解说诗。","莫作瓜分甜后蒂，已拚樗散鬓成丝。","闻閒岁月壶中永，取静光阴隙外驰。","莫道广文心似铁，知心犹有赋梅诗。"]},{"t":"次谏长韵 其一","f":"七言律诗","c":["缭垣虚昼静沉沉，两行槐阴一径深。","细雨入帘供洪溽，清谈参坐共萧森。","柳边花底随官事，绿暗红稀惜壮心。","正以头风无藉在，诗翁佳句敌陈琳。"]},{"t":"次谏长韵 其二","f":"七言律诗","c":["檐溜涓涓响涧涔，湿飞蝴蝶见深深。","乳鸦雏雀自酬答，老柳古槐惟蔚森。","同省三人惭未至，许身一字愧初心。","妤风隔院动修竹，随意题诗倾碧琳。"]},{"t":"再次仲归临池韵","f":"七言律诗","c":["圣时下士若卷阿，鸿笔词源走万波。","南省只教韩愈到，北飞犹障禹门过。","男儿器业偏成晚，夫子才名独患多。","地辟天开知有日，中兴宜颂更宜歌。"]},{"t":"次韵刘孝若二首 其一","f":"七言律诗","c":["每思忝窃长知愧，何有行藏可待明。","壮不如人祇录录，老将及耄更平平。","故交契予情文厚，佳句驰来格律清。","拟策疲驽追逸步，却愁重趼趣脩程。"]},{"t":"次韵刘孝若二首 其二","f":"七言律诗","c":["宜男草长欲忘忧，含笑花开却似羞。","转蕙有风凉意动，重梅过雨涨痕留。","幽閒岁月难消受，香火朝昏未答酬。","珍重友朋相慰藉，鼎来赓和得因由。"]},{"t":"次韵转庵幽禽到研边之什","f":"七言律诗","c":["梅风拂拂动薰弦，久雨休疑是漏天。","有客方怀吟泽畔，无楼那得住山边。","添香遣日愁难破，换韵传诗喜欲颠。","犯戒成章贤博弈，门人已废蓼莪篇。"]},{"t":"次潘茂和韵","f":"七言律诗","c":["久向竹林闻小阮，恨无此客岂无毡。","文章未可为馀事，子弟何妨自太鲜。","老去懒兼衰作病，传来诗与月俱圆。","瓣香合为床头易，笞凤鞭鸾不是仙。"]},{"t":"袁同年过扬州递书并诗再次韵约同留维扬观春色","f":"七言律诗","c":["一缄书札故人情，中有新诗字字清。","邮置传来心已醒，秋镫读处眼偏明。","扬州路近帆能疾，瓜渚潮来水似生。","少驻星轺问遗俗，春风生帐有诗呈。"]},{"t":"再次韵仲归","f":"七言律诗","c":["身名已愧凤巢阿，世念难教古井波。","老觉病时终是懒，话当情处爱相过。","闻閒莫惜朋簪盍，服义相将户履多。","意到会能拚剧饮，与君同赋醉时歌。"]},{"t":"席上次刘振之贤良韵","f":"七言律诗","c":["眼底扶疏绿渐稠，傍林轩槛转清幽。","空餐敢拟过僧夏，闵雨犹怜近麦秋。","客有好怀廑夙驾，袖将佳句豁牢愁。","焚香饷客无多景，静听呼雏鸟雀啁。"]},{"t":"子仪侍郎欲携家泛湖不及践旬休之约再次韵","f":"七言律诗","c":["案头故纸积如山，春去能无半日閒。","已约旬休同此集，预愁阴雨在其间。","时清不禁无何饮，昼永从教竟日还。","只恐扁舟成拔宅，同游无路可追攀。"]},{"t":"再次韵子仪侍郎用沈察院韵","f":"七言律诗","c":["杜宇来时忆故山，簿书丛里且闻閒。","流传旧体湖山外，赓唱新声伯仲间。","雨霁园林莺亦喜，风轻帘幕燕知还。","苏公堤上明寒食，逸驾翩翩不可攀。"]},{"t":"次王宣甫韵","f":"七言律诗","c":["一春无计接茵凭，野草閒花漫自荣。","留得小栏红药在，待看新径绿阴成。","亦怜酒盏疏谈柄，肯寄诗筒督课程。","多病感君勤问劳，肱三折后万缘轻。"]},{"t":"重阳前两日集转庵同社而今日忽雨次转庵韵","f":"七言律诗","c":["搀先登眺高为节，片段芙蓉锦作花。","赖得前朝曾此集，有如今雨欲何加。","欢浓未分玄成白，客醉犹怜酒胜茶。","犹恨梅川无好句，更须君赋为传誇。"]},{"t":"次常之韵","f":"七言律诗","c":["身閒城市即郊坰，况是秋高气倍清。","酬唱篇章惊句眼，往来节物见交情。","重阳槛菊明朝摘，细雨檐花昨夜鸣。","晚霁嘉宾不重赏，灵山空自爱嘉明。"]},{"t":"寄陈颐刚","f":"七言律诗","c":["眼见交游半陆沈，可无百丈引清深。","注成兵法有奇志，閒过壮年应苦心。","几度梅花开怅望，有时杨叶梦追寻。","男儿机会何终极，莫遣愁将鬓发侵。"]},{"t":"简转庵","f":"七言律诗","c":["扣门有碍吾何适，排户顿疏君作难。","不对桃花倾社酒，谁怜燕子怯春寒。","便过熟食过元巳，尚看酴醾看牡丹。","却笑今年诗厄闰，略无好语入毫端。"]},{"t":"简才叔","f":"七言律诗","c":["坐看母竹长龙材，衣上新痕染碧苔。","杜宇不随春老去，黄鹂偏傍水光来。","摇摇书带连香草，冉冉凌霄上古梅。","此意转庵同领解，更须潘令好怀开。"]},{"t":"入南乡检旱纪所见","f":"七言律诗","c":["分宜南北两乡分，路入南乡过所闻。","荞麦满山明积雪，晚禾匝野涨黄云。","寸田必垦怜农父，五斗空餐愧令君。","惜许早田成旱损，不成乐岁答民勤。"]},{"t":"纪所见","f":"七言律诗","c":["百年厦屋尽良材，客位经年长紫苔。","失马塞翁翻有得，抚松陶令盍归来。","门前婀娜千行柳，墙角轮囷一树梅。","满壁图书非诧事，锦囊成箧未曾开。"]},{"t":"夜渡分宜水南","f":"七言律诗","c":["一水弯环抱县流，水南物色总清幽。","案头故纸看成叶，眼底青山见即愁。","夜唤扁舟乘月渡，静听鱼网沥波收。","忽思孤屿中川畔，满意秋风落钓钩。"]},{"t":"括苍道中次陈颐刚韵","f":"七言律诗","c":["诗翁四十九行年，说著行边喜欲癫。","介妇滩头随水宿，冯公岭上伴云眠。","趋时萍实甜于蜜，阅世匏壶老更坚。","冀北须君空一洗，眼前驽马太劳鞭。"]},{"t":"宿建德驿追次张于湖壁间韵","f":"七言律诗","c":["此驿阅人多似我，于湖去后有谁来。","诗留版壁经年在，门对岩扃尽日开。","天上有文修白玉，人间无句对苍苔。","相逢莫问滔滔事，荷蒉曾过有意哉。"]},{"t":"舟行早起处州溪上","f":"七言律诗","c":["溪容雾气扑清芬，野色微兼晓色分。","樯表已迎山背日，缆端犹系石根云。","打头风信看来转，当面滩声语不闻。","遥唤渔舟倦回首，人鸥那得更同群。"]},{"t":"早起","f":"七言律诗","c":["归来百事尽摧藏，卦气行年分所当。","未晓不眠真是老，才明便起有何忙。","移山种石愚翁癖，遇酒逢歌楚客狂。","此外胸中无个事，有时信口作篇章。"]},{"t":"睡起","f":"七言律诗","c":["饭了晴窗睡足时，杖藜徐步出荆扉。","若无俗事关人意，只有杨花点客衣。","黄鸟怨春浑不住，杜鹃知我亦思归。","邻家酒熟容赊买，竹笋初生韭菜肥。"]},{"t":"书债山积久逋余丞相报缄连发二书毕喜作口号","f":"七言律诗","c":["自思堪笑亦堪怜，懒与顽兼不可镌。","两纸书成大功业，三杯酒罢小神仙。","每当静处常追悔，何似閒时旋补填。","害性苦心从古病，不如归去乐残年。"]},{"t":"汤晋卿善谈命求诗纪实","f":"七言律诗","c":["已近无闻半百年，枉烦明镜照华颠。","湴河驿马妨乘鄣，氐宿苍龙分委天。","告我三阳闻好语，验君三命有真传。","预愁一字终无补，何日归欤阿对泉。"]},{"t":"德久和韵以予请外之力预为怅然再用前韵","f":"七言律诗","c":["已是于思去复来，自惭无补效涓埃。","粗官只合供烦使，昭代惟须急异才。","名士不应诗作祟，诸公方拟管吹灰。","且容一舸江湖去，庐阜烟萝锁碧嵬。"]},{"t":"才叔调倅归","f":"七言律诗","c":["五月征行思竹院，半年赓倡负松庐。","水西风月分归后，巷北交朋过访馀。","携具洗泥曾醉否，逃禅得句定真如。","涉斋终日攒眉坐，正赖清新为起予。"]},{"t":"病赤目从薛山甫借荷叶巾","f":"七言律诗","c":["赤目朝来势转加，病身观妄有生涯。","火平文武宽心地，酒远圣贤疏肺家。","虚白已能生暗室，空青不用点昏花。","小冠预拟更名字，借与团圆藕叶纱。"]},{"t":"次韵仲归病中垂问","f":"七言律诗","c":["痼疾多年久一翁，医方验后自难功。","已惭兀者犹尊足，敢企泠然欲御风。","觅句未能生处熟，论交正要苦辞攻。","凭君莫话沙堤事，此语终谀不是公。"]},{"t":"次韵呈支茂先贤良","f":"七言律诗","c":["烟蓑不尽四山青，古道长将古意评。","辟谷久知疏药裹，纂言今见满书檠。","尧年请祝新抛隐，宋范争抄近荐名。","圣世埋光那可得，清台恰奏少微明。"]},{"t":"喜宣甫至戏呈","f":"七言律诗","c":["陶溪路远强跻攀，犹得诗筒暂往还。","有便催租俄败意，无心听鹊忽承颜。","菊花满径成三老，梅萼穿林见一斑。","肯为转庵聊且住，预愁约束裹粮悭。"]},{"t":"次王宣甫题媚川图韵","f":"七言律诗","c":["底须屏障写天吴，绝境横前与画俱。","两塔屹波流不去，千帆破浪远如无。","空明水月光争媚，开阖云山妙莫摹。","扁榜首蒙摩诘句，小亭从此有诗图。"]},{"t":"韩干四马诗戏赠世京","f":"七言律诗","c":["吾闻北马来西极，骧首蹑云无定姿。","俯视双瞳真皎镜，遥怜一骨独权奇。","何年惨澹经营处，此日飞扬奔放时。","把玩不须嗟岁晚，会看天厩著金羁。"]},{"t":"谢鲍潮州惠归正李媪所作外国图因题卷后二首 其一","f":"七言律诗","c":["两年贰郡半专州，濠上鱼涵惠泽游。","慨念中原变荆棘，图成外国别冠裘。","故宫禾黍悲清汴，落日风沙惨白沟。","汉节提携曾记别，居然展卷涕横流。"]},{"t":"谢鲍潮州惠归正李媪所作外国图因题卷后二首 其二","f":"七言律诗","c":["健妇真能胜丈夫，丹青人物妙难摹。","百年画手承平久，万折归心守节孤。","辄此珍藏为我有，从渠远致更能无。","伤心故国流风在，不是成周王会图。"]},{"t":"题元祐诸公跋窦三川诗卷后","f":"七言律诗","c":["门前流水古犹今，不见钟期但苦心。","每忆承平爱人物，有谁埋没向山林。","一官黄绶甘肥遁，百首清诗共赏音。","自笑抱关人录录，亦将名字托碑阴。"]},{"t":"次韵仲归渔父","f":"七言律诗","c":["风静波恬没是非，雨蓑烟笠当冠衣。","移将兰棹垂纶去，钓得金鳞带月归。","到处茅柴赊可准，有时莼菜滑仍肥。","旁人道是忘机叟，到底从来不识机。"]},{"t":"王宣甫以新妇鱼能斗为胜负鱼有诗释其讹谬次韵戏答","f":"七言律诗","c":["斓斑红黛斗芳塘，新妇鱼儿著底忙。","岂为长陵矜先后，不知濠上乐彷徉。","诗来解辨吾伊谬，我欲兼将胜负忘。","蚌鹬相持堪惜许，须知旁有谢三郎。"]},{"t":"闻砧","f":"七言律诗","c":["秋来风物自凄清，叶叶枝枝策策鸣。","近砌不堪催织语，远砧更送断肠声。","苦心且作丁当和，积恨终凭熨帖平。","寒女终身无褐彩，绮罗通夕课寒檠。"]},{"t":"观郭殿岩打毬于冲天观旁","f":"七言律诗","c":["峰顶毬场剪似平，汾阳号令素精明。","万蹄攒逐一星过，两队欢呼众乐鸣。","静看穿杨矜妙手，醉观过翼觉身轻。","摩挲亭下排衙石，拟赋将军射虎行。"]},{"t":"听转庵弹琴","f":"七言律诗","c":["竞春人去客苔侵，喜对安仁理玉琴。","百尺游丝非助我，一声啼鴂是知音。","湘桃作意红兼白，碧柳随宜浅更深。","昨日胭脂今日雪，可怜墙角两来禽。"]},{"t":"次韵仲归观弈","f":"七言律诗","c":["绿阴昼静熟观棋，横出宁分正与奇。","要处不容留活眼，忙时翻笑敛愁眉。","手谈大似衔枚战，坐隐几同过枕师。","著罢了然无胜负，机心却许白鸥知。"]},{"t":"酬转庵畏酒之什","f":"七言律诗","c":["绝境夤缘有路攀，隔波楼影塔中间。","才收梅溽经旬雨，已放莲峰几朵山。","胜处得閒真阆苑，醉馀忘世即函关。","诗高不饮妨何事，恐对湖光自忸颜。"]},{"t":"谢鲍潮州送新酒","f":"七言律诗","c":["浊醪青蕊作重阳，才入开炉月果良。","佳酿遣销彭泽恨，好怀肯对马军尝。","清新有句须留待，风味如君不可忘。","只俟高轩共杯酌，四时岩桂尚能香。"]},{"t":"还杜叔高诗卷送酒","f":"七言律诗","c":["三衢三杜人能说，我亦曾窥仲叔间。","软语接来真有味，好诗吟到祇如閒。","名场偪仄云垂翅，泽国冥濛雨蔽山。","不有客楼何地著，可无尊酒破天悭。"]},{"t":"次韵酬显庵寄茶","f":"七言律诗","c":["显庵多别又多年，小草蝇头越瞭然。","觅句不为禅所缚，住山长是佛相怜。","无从饮酒过莲社，尚肯分茶到玉川。","肉食正惭无补报，归心已驶不须鞭。"]},{"t":"郑文之许惠乌髭方戏简","f":"七言律诗","c":["堕甑功名久任缘，形骸老丑孰蚩妍。","了知白发关吾事，敢学乌髭趁少年。","人谓黄金容可作，君藏鸿宝乃能铅。","一皤正博妻孥笑，许惠良方试与传。"]},{"t":"王宣甫以予有诗求郑文之染髭法与其旧作暗合因录示次韵酬之","f":"七言律诗","c":["细看绿绕与红围，此地何曾著白髭。","顾我全惊缁鬓改，羡君犹有黑丝垂。","一皤博笑几同调，两丑相看莫敛眉。","正使醉中巾帻堕，不妨齐唱赤壶词。"]},{"t":"戏赠","f":"七言律诗","c":["不鼓君家爨下材，渴心古井欲生苔。","柳枝未放行云去，巫峡又还为雨来。","似染霜髭欺黑漆，尚禁醋齿试青梅。","不妨雨过同心赏，一架酴醾花正开。"]},{"t":"三赓许令侄砚之什","f":"七言律诗","c":["转庵蓄砚有奇材，受墨逡巡落海苔。","异品已堪相甲乙，馀波足可畀云来。","许分阮侄邀金竹，预想将军慰渴梅。","尤物匪珍才可惜，芝兰正要满庭开。"]},{"t":"次韵王宣甫谢笔","f":"七言律诗","c":["笔冢前头几泣鱼，笔耕无获匪才疏。","寄将毛颖烦为传，恰值虞卿正著书。","千兔难酬终送似，两家托契更谁如。","词章老去输豪放，琼玉从君要佩琚。"]},{"t":"谢益老寄英石","f":"七言律诗","c":["淡交如水足生平，晚岁烦师托石兄。","曾解点头听半偈，定能发笑验三生。","丛林住遍归来好，长物分将过去轻。","闻道肯为邻舍佛，锦衣只在雁山行。"]},{"t":"旧藏英石沈俭夫族人处谢俭夫转为取还","f":"七言律诗","c":["百好残年心已灰，石君久去绝嫌猜。","故人诺重金难比，族里言温璧径回。","曾与话禅听翠竹，亦资醒酒卧青苔。","如今相见休相叹，各是因人归去来。"]},{"t":"济叔辍案上石菖蒲为惠石与菖蒲俱佳拙语奉酬","f":"七言律诗","c":["苍然拳石具林峦，上有菖蒲八节滩。","洛浦毵毵馀玉佩，蓝田拂拂长琅玕。","著身便恐移天姥，濯发还疑借洧盘。","割爱赠予铭座右，斓斑鬓影照应难。"]},{"t":"贺太庙产芝草","f":"七言律诗","c":["太室晶瑩粲玉芝，慈闱恰遇未央时。","两宫喜色腾尧采，万岁欢声动汉卮。","发祉有来增裔叶，产祥方至在孙枝。","从今庆事频频有，准拟赓歌剩赋诗。"]},{"t":"得禁中花喜而有作","f":"七言律诗","c":["阶前红少绿多时，尚有名花巨压枝。","珠璧直疑天上得，琼瑶难报世间奇。","悬知丹禁莺花绕，始觉仙家日月迟。","珍重十洲蓬岛客，津津喜色见双眉。"]},{"t":"再次韵宣甫探梅","f":"七言律诗","c":["姑射山头冰雪姿，自应不负岁寒期。","一枝已共巡檐笑，半树宁忘欲雪诗。","未许佳人和月摘，且容老子受风吹。","城中诗社新牢落，绝喜陶山慰所思。"]},{"t":"次韵王宣甫催梅","f":"七言律诗","c":["摇落驱驰自岁年，今年惭愧得身安。","小园亦有先春意，短思惟知著句难。","看水看山从昔好，爱风爱雪待今寒。","故人远寄催梅作，唤起新愁有万端。"]},{"t":"再次王宣甫韵","f":"七言律诗","c":["江南春讯漫年年，月下推敲句未安。","好语得来元不易，爱花开后却无难。","霜晴屋角偏先暖，雪色枝头已破寒。","为向催梅居士语，杖藜肯复过苏端。"]},{"t":"次韵王宣甫催梅","f":"七言律诗","c":["犯寒时访岁寒姿，经闰何缘却后期。","珍重故人勤问讯，剪裁新意作催诗。","一阳潜与飞灰动，九奏深凭画角吹。","莫遣诗筒成断绝，日来频为起愁思。"]},{"t":"初得梅花呈似参议刘二十九丈","f":"七言律诗","c":["江南驿使是知津，剪送琼枝裹绿筠。","触发家山春意思，唤回天地雪精神。","护持惟有壶瓶水，映带全无几案尘。","一夜梅坡清入梦，不妨持恼谢岩人。"]},{"t":"张舍人惠古梅酬以拙言","f":"七言律诗","c":["孤标耻付寿阳妆，薜荔为衣藓作裳。","映竹蒙茸初破白，倚松鳞甲亦生香。","分无疏影追同辈，肯逐群英殿后芳。","珍重折枝烦寄与，恍思千树故山旁。"]},{"t":"再用韵奉酬","f":"七言律诗","c":["未信时新有俭妆，缟衣趺坐赤帷裳。","已甘槁项终肥遁，无奈酸风发暗香。","心苦故应如貌古，林深正不为人芳。","须知已是丈人行，领略群英顾在旁。"]},{"t":"同寮约过包山因问讯玉津牡丹再次韵呈子仪侍郎","f":"七言律诗","c":["传闻有约过包山，节遇天祺得暂閒。","便有啼莺迎柳外，不妨飞蝶导花间。","东吴壮观随潮长，西洛风光指日还。","独恨微臣无补报，勋名分寸盍跻攀。"]},{"t":"谢惠牡丹","f":"七言律诗","c":["未叹春光去有涯，诗翁时为送名葩。","娼条冶叶从过眼，魏紫姚黄始是花。","洗涤壶瓶晨井水，护持风雨夜窗纱。","十眉已觉成羞涩，且向樽前领物华。"]},{"t":"赵漕从善送吴门牡丹","f":"七言律诗","c":["看花檐上眼长寒，惭愧邻翁送牡丹。","和露擎来香可染，拢云争插玉成团。","传闻西洛名千变，排释东风恨万端。","茂苑去天真尺五，羡君花信报平安。"]},{"t":"芍药","f":"七言律诗","c":["扬州千叶旧生涯，诗到坡仙正复葩。","喜见故家翻瑞药，送将新句续名花。","日高髲剃醺含露，时样梳妆肉映纱。","窈窕留春春不住，诗翁留得鬓边华。"]},{"t":"再用韵","f":"七言律诗","c":["莫问无涯及有涯，眼前万绿替千葩。","故人访我跫然喜，小阁留春圣得花。","美酒急倾门候钥，清歌未彻烛笼纱。","匆匆似此频能过，犹胜逢人说梦华。"]},{"t":"三用韵","f":"七言律诗","c":["绿遍山颠与水涯，苦吟且不到春葩。","新篁已接三竿日，红药犹开四月花。","好句更烦衔两袖，嫩寒犹觉怯重纱。","留连小饮无须醉，明月翩翩扈翠华。"]},{"t":"花药相接可观复用韵","f":"七言律诗","c":["净尽天香溢夏寒，满奁谁掷狡仙丹。","洛花不逐林花老，禁药犹堪木药团。","试问丁香和恨结，何如萱草破忧端。","翠屏红粉腰如束，我是村中老谢安。"]},{"t":"传芍药复用韵","f":"七言律诗","c":["阶药留春逗晚寒，鬓丝敢傍脸霞丹。","肯分骑鹤红千叶，喜见盘龙绿一团。","妖格流传如有恨，狂香横出亦无端。","慇勤为换瓶中水，排比窗前两行安。"]},{"t":"和人惠白莲花","f":"七言律诗","c":["碧莲花发梦湾矶，鹤骨难教厚禄肥。","夜月擎来双掌露，晓风拂动六铢衣。","渔歌过后香犹湿，鹭影移时雪欲霏。","风月既为专一壑，茅茨何自有光辉。"]},{"t":"池莲","f":"七言律诗","c":["一湾清碧绕中阿，万柄香红映曲波。","不道龟鱼长受庇，只欣鸥鹭数相过。","机心久与尘俱息，警句元无趣自多。","病起情悰聊徙倚，何人解唱野塘歌。"]},{"t":"凿池添种荷花","f":"七言律诗","c":["累石防花拾弃材，凿池种藕白馀苔。","游鯈剩喜波光阔，飞鹭似知人意来。","已见圆荷浮小叶，正须细雨熟黄梅。","莫言旧隐无多景，一派清泉手自开。"]},{"t":"玉簪花","f":"七言律诗","c":["琉璃布地绿愔愔，苗长蓝田夜照林。","雪色能香开有璞，玉光未拆盍成簪。","不登云髻尤孤洁，长浸铜壶更久禁。","梅与水仙流品外，幽兰相友是同心。"]},{"t":"秋萱","f":"七言律诗","c":["说著宜男已可羞，移栽老圃且忘忧。","传为麝种生来别，唤作鹿葱元是愁。","幸脱炎威才过夏，何缘冷落尚宜秋。","国香天且难拘管，过眼空花一笑休。"]},{"t":"雁来红","f":"七言律诗","c":["非花非叶艳茸茸，雁未来时已自红。","多似锦衣明昼绣，好同旌节种秋风。","鸡冠粗俗难争长，金凤低徊漫作丛。","谁道后庭遗恨曲，龙蟠王气正豪雄。"]},{"t":"李若兄菊诗同社久已嗟赏赓和属蒙写寄仍用韵以致予奉祠之喜予两年从金陵觅菊栽而一种至今著蕊未开岂所谓晚节香者耶次韵奉酬 其一","f":"七言律诗","c":["满地金钱买断秋，晚年安得有穷愁。","小园不负长寒眼，佳客自疏新白头。","一种最开陶径晚，两年曾向蒋山求。","肯能过访同心赏，犹胜传声互答酬。"]},{"t":"李若兄菊诗同社久已嗟赏赓和属蒙写寄仍用韵以致予奉祠之喜予两年从金陵觅菊栽而一种至今著蕊未开岂所谓晚节香者耶次韵奉酬 其二","f":"楚辞体","c":["四体支吾两鬓秋，一生知足百无愁。","洞霄香火手加额，太玉山园茅盖头。","归去来兮交未息，不知我者谓何求。","若人共说无生话，一句抛来一句酬。"]},{"t":"次韵章君济黄元章二广文种竹建康学宫","f":"七言律诗","c":["城云一坞碧云深，亦许分青到泮林。","移去检书涓醉日，种来挟策较分阴。","细看直节难教改，设有繁霜不受侵。","二妙育才如此竹，惜无健笔与长吟。"]},{"t":"即事并写和质弟诗呈似","f":"七言律诗","c":["新绿愔愔长茂材，嫩流漠漠养深苔。","一梭金影缗蛮过，半缬花光剥啄来。","槛竹鸣边垂粉箨，池萍缺处落肥梅。","閒中偏得园林趣，更觉清和意象开。"]},{"t":"检校园课济叔又送花栽欣然有作","f":"七言律诗","c":["雨馀扶杖入苍苔，检校园工有品裁。","缓引瓜苗教傍架，旋齐菊杪要平台。","出墙新竹矜施粉，立水高荷劝把杯。","莫讶小园饶胜事，故人续续送花栽。"]},{"t":"蒋肖李潘才叔和检校园课之什再用韵为谢","f":"七言律诗","c":["随意篇章落海苔，琼瑶欲报不知裁。","青蒲细草来斋几，白雪阳春走皂台。","梦里勋名槐是国，閒中活计芥为杯。","吟哦蒋径潘江句，浅白深红手自栽。"]},{"t":"肖李才叔和篇末章有青蒲自是公家物之语再用韵为谢","f":"七言律诗","c":["踏破先生客位苔，诗仙凤沼得重裁。","连城更枉捐双璧，二妙真堪共一台。","蝇到成时元误笔，蛇因添后失持杯。","劝君休话青蒲事，妄想根苗莫更栽。"]},{"t":"次韵毛漳州遣价为寿二首 其一","f":"七言律诗","c":["漳州远为故人东，问讯深怜臭味同。","喜可寒冬耕灞浐，吟堪小麦熟崆峒。","贱生已觉年骎暮，远祝应难日再中。","愿老洞霄香火吏，馀龄犹得效呼嵩。"]},{"t":"次韵毛漳州遣价为寿二首 其二","f":"七言律诗","c":["充位无功得放归，渊明若在耻吾师。","旧交动色知毛檄，故里分甘到董帷。","顾我已沦诃谴域，如君合建太平基。","竞传报政趋严召，远业真堪济此时。"]},{"t":"为转庵寿二首 其一","f":"七言律诗","c":["却喜漳南解秩归，天教慰藉老朋知。","巷南巷北游从旧，浙右浙东赓唱诗。","上阁有题皆得和，西湖无路可陪时。","年颜相去追随得，难老如公寿更颐。"]},{"t":"为转庵寿二首 其二","f":"七言律诗","c":["岁岁新阳喜仲旬，两家儿辈作生辰。","下生弥勒迟三日，共约梅花作故人。","未许同龛供佛事，只须共载接车茵。","相先寿语须齐和，满酌吾家太玉春。"]},{"t":"高少卿挽词","f":"七言律诗","c":["剖竹乘轺课最多，班高惟月正逶迤。","千龄圣主难逢际，九帙慈亲奈老何。","尚拟鸣珂还里巷，俄伤埋玉向山阿。","宣仁忠节平生愿，有子巍登进士科。"]},{"t":"蔡知阁挽词","f":"七言律诗","c":["抱负平生是朴忠，发挥不尽古人风。","名藩多历为民福，上阁频输在帝衷。","勋业有期方感会，哀荣不恨剧初终。","灵峰树杪龟趺出，无愧铭辞属蔡公。"]},{"t":"亲家张舍人挽词 其一","f":"七言律诗","c":["忍看丹旐引灵輀，尚想祥华进止时。","无复短檠亲教子，空馀满箧旧题诗。","阴功会即佳城兆，显刻犹须幼妇碑。","小殡西湖湖上寺，冷云秋露不胜悲。"]},{"t":"亲家张舍人挽词 其二","f":"七言律诗","c":["忆曾伯仲共论文，迭和埙篪自不群。","尚以竹林怜小阮，肯令新妇配参军。","登楼无计追王粲，载酒空烦过子云。","幸有诸郎传素业，勉旃犹足振前闻。"]},{"t":"挽承事黄公词","f":"七言律诗","c":["胶庠衣钵是青毡，付与儿曹自勉旃。","鼎级科名彰父教，著庭勋绩见家传。","千钟合使荣三釜，一品终当贵九泉。","留却无穷风木恨，悲笳呜咽晚春天。"]},{"t":"钱致政挽词","f":"七言律诗","c":["教子全功次第成，吾乡钱氏窦家声。","善根植得桥梁固，心地均教役使平。","铜墨远从欣养志，银绯勇返了遗荣。","哀荣寿考无堪恨，行道称嗟泪自倾。"]},{"t":"刘和州挽词","f":"七言律诗","c":["风姿酝藉发阳和，议论峥嵘砥柱波。","先见不为时宰信，孤忠惟是圣心多。","两州惠爱逢人说，万里功名奈病何。","期待自惭无补报，忍观埋玉北山阿。"]},{"t":"郑通判同年挽词 其一","f":"七言律诗","c":["人物吾乡行秘书，功名末路坐题舆。","只教副墨传蛮徼，不得雌黄到石渠。","临事孰如仁者勇，著书犹是道之馀。","推尊文行铭辞好，无愧当年叹起予。"]},{"t":"郑通判同年挽词 其二","f":"七言律诗","c":["惊心同榜渺参辰，回首龙飞四十春。","不慭此翁天实惜，欲论心事我谁亲。","百年风月归吟笔，一代仪型落后尘。","正尔棘心吹泪苦，石塘东望更沾巾。"]},{"t":"郑光宗节使挽词","f":"七言律诗","c":["孝庙祥刑首选抡，行藏何愧百年身。","共知草木威名旧，亲见旌麾号令新。","登陆政成俄告老，建旄好在奄归真。","传家有子无遗恨，千古佳城泽后人。"]},{"t":"陈紫微挽词","f":"七言律诗","c":["三生竹素一臞仙，六艺波澜万口传。","能使声名垂宇内，不教官职副生前。","松阶显揭新阡表，宣室深知旧学贤。","忆赋桐君赠予别，忍吟薤露挽公篇。"]},{"t":"侯机宜挽词三首 其一","f":"七言律诗","c":["世取名科耀故乡，君家显祖屹相望。","将雏近喜重偕计，有子先登服义方。","著从事衫元漫仕，入元戎幕已交章。","头风正待陈琳檄，熟路轻车痛折箱。"]},{"t":"侯机宜挽词三首 其二","f":"七言律诗","c":["岂以姻亲笃故情，最怜意气感平生。","身居城市如专壑，家蓄图书得主名。","满拟归田谙笑语，何期中路隔幽明。","有儿万事无堪恨，待勒铭诗作世程。"]},{"t":"侯机宜挽词三首 其三","f":"七言律诗","c":["掀髯握手话心期，录录俦中独见知。","官职有惭公过许，行藏无据我何为。","直书实行人能读，厚德深功世莫窥。","有子传家吾不恨，西风吹袂涕垂颐。"]},{"t":"周和叔挽词","f":"七言律诗","c":["不烦月旦课乡评，少日声名老更成。","百里恩波东浙水，两州遗爱蜀江城。","操持坚彻神明惧，精爽全归父母生。","子有笔端公不死，故交零落我伤情。"]},{"t":"转庵挽词","f":"七言律诗","c":["无复从容唱和诗，忍为恻怆挽歌词。","生前秋月春花了，身后高山流水知。","小阮竹林思步武，仲芳蒿里得追随。","腰金埋玉终尘土，万卷千篇倚二儿。"]},{"t":"善士严明仲挽词","f":"七言律诗","c":["清风元在钓台边，分派东嘉世有传。","教子以经无尽藏，活人为德不唐捐。","年登九九方开帙，心契三三即了禅。","寿得考终称善士，合将哀些表新阡。"]},{"t":"万侍郎母夫人钱氏挽词","f":"七言律诗","c":["亲归儿住可胜悲，儿第亲存各不知。","一世苦心天乞与，百年荣养圣垂慈。","共传义激投簪语，合见恩除从橐时。","不及联书朱氏母，可怜惟赋挽歌词。"]},{"t":"夫人滕氏挽词","f":"七言律诗","c":["升堂忆昨拜慈容，京兆平反一笑中。","可但三从多懿范，了知百念积阴功。","松阶猛乞荣归养，吉国真如擅考终。","千古难消吹棘恨，可堪丹旐卷春风。"]},{"t":"代上皇太子寿二十韵","f":"五言古诗","c":["阖辟乾坤迥，胚腪历数长。","较论今鲜俪，诣绝古非常。","八帙尊尧典，千龄格舜裳。","孙枝绵奕叶，国本系元良。","南极昭穹覆，东储应寿昌。","九秋开令节，五日届重阳。","照曜辰仪肃，氤氲甲观祥。","玉卮传锡嘏，瑶乐奏称觞。","茅土仙潢润，芝兰宝砌芳。","元勋来阀阅，嘉耦奉尊章。","庆事川方至，欢呼殿未央。","恭惟天继体，仰止日重光。","拟把涓埃报，难将算数量。","皇图恢远驭，寿域振遐荒。","寝事龙楼问，班陪虎胄行。","神明推大尹，惠养式群方。","朝夕渊冲地，窥瞻简乐堂。","不能鞭朽钝，何物介陵冈。","再拜占霄象，千门祝夜香。","两宫千万岁，三圣共无疆。"]},{"t":"又代贺十韵","f":"五言古诗","c":["南极昭穹象，东储庆寿昌。","千秋符季月，五日近重阳。","银榜辰仪肃，铜吹甲观祥。","两宫开燕喜，万国庆元良。","竞指椿为算，争持菊泛觞。","恭惟天广大，仰止日辉光。","继体观行健，重轮耀有常。","自然高宇宙，何物介陵冈。","监古惭能读，分僚忝接行。","三王真有道，更欲祝绵长。"]},{"t":"上左丞相寿二十韵","f":"五言古诗","c":["阖辟乾坤迥，甄陶物象新。","舜弦熏入治，商鼎味还淳。","天贶方垂节，崧高已降神。","清明开造化，精祲下星辰。","谦损祇缝掖，尊严绝缙绅。","怯惟闻己过，勇岂逊师仁。","补衮工夫细，垂裳宠渥频。","热官无倖位，寒士有通津。","水旱犹亲奏，封章要广陈。","栋梁须偃植，海岳待涓尘。","自昔观前辈，于今迈等伦。","调和全玉烛，鼓舞在洪钧。","薄海归洪轴，中原望帝宸。","两宫三圣日，四海一家春。","少倚遐冲折，重看寿域均。","无官酬竹帛，有节拟松筠。","晓日驰中使，流霞出九旻。","敬为丞相寿，恭上太夫人。","盛德宁无种，长年宛似亲。","小人因有母，惭愧器轮囷。"]},{"t":"上梁丞相寿二十韵","f":"五言古诗","c":["千载风云会，三生柱石缘。","罕闻流渚旦，同在降崧年。","天意开皇极，神谋属钜贤。","中和垂节后，嗜欲兆开先。","象应魁三近，声蜚第一传。","十年登鼎铉，四海入陶甄。","轻重朝廷寄，安危将相权。","朔方频借问，南国小回旋。","再入仪刑肃，周询眷倚专。","折冲声色外，燮理冕旒前。","照曜冰山泮，调和玉烛圆。","帝方张挞伐，天欲靖烽烟。","机会宁容发，功成即济川。","长城端有托，寿域定无边。","不用霞觞祝，唯应宝札编。","升平天下宰，阴德地行仙。","霁色归桃李，韶光并管弦。","深为修禊日，全似浴沂天。","但乐垂裳化，难酬补衮妍。","清风时入抱，聊写穆如篇。"]},{"t":"上安抚程给事十六韵","f":"五言古诗","c":["台省仪型旧，垣扉宠渥新。","词章关造化，论议蕴经伦。","去国悲风木，流年感隙尘。","未教居鼎鼐，亦合上星辰。","何自占双使，从谁问大钧。","熊湘辰告入，牛斗夜光陈。","礼乐须贤帅，湖山要主人。","一言九重寤，八县十州春。","拾穗歌时熟，投醪味德醇。","燕閒馀画戟，谈笑且纶巾。","早晚登黄阁，声猷动紫宸。","有儒嗟濩落，无路话邅迍。","忆拜编书赐，祇怜负弩身。","或疑千里马，曾遇九方歅。","北斗言瞻切，西山入梦频。","登临冀轩豁，未敢叹轮囷。"]},{"t":"上辛安抚二十韵","f":"五言古诗","c":["开辟重华旦，胚胎间世贤。","云龙时际会，星凤睹争先。","天授归三杰，神谋效一编。","宏谟驱固陋，馀论细雕镌。","诏旨倾胪句，山呼动奏篇。","干霄须造化，惟月进班联。","有客占星次，逢人问日边。","江湖烦镇抚，壤地屈盘旋。","谈笑潢池净，生成壁垒坚。","丈夫真细事，馀子敢差肩。","黄屋深知切，青云宠渥骈。","即归调鼎铉，少驻斸龙泉。","更治今冯翊，重归旧颍川。","载涂明积雪，嗣岁卜丰年。","封殖棠阴盛，欢迎竹马鲜。","恩波行处足，威誉向来传。","此独疮痍甚，方疑雨露偏。","禁通邻邑粟，费减月桩钱。","斋戒逾三日，遭逢有二天。","执鞭吾所慕，负弩敢驱前。"]},{"t":"上周尚书内翰承旨二十韵","f":"五言古诗","c":["弱水蓬莱远，群山岱岳高。","尘埃千障隔，景行寸心劳。","摸索知何自，抠趋苦未遭。","铜章披宿雾，藻鉴炳秋毫。","穹壤悬鹏鴳，篇章抵雁羔。","斯文标正脉，舆论凛时髦。","勇退关吾道，留行切帝褒。","风云开壮观，舟楫际洪涛。","剑履昭魁象，词澜卷巨鳌。","合宫陈缛典，华盖粲星旄。","霁日明黄道，祥风动赭袍。","恩波荣赦草，颜咫醉仙桃。","麻册追盘诰，诗歌逼颂骚。","人方期补衮，功岂在挥毫。","地禁承中旨，天官冠列曹。","仪型喜颇牧，步武接夔皋。","蚤晚登三事，乾坤倚一陶。","途长须骥足，用拙匪牛刀。","造请神先索，推敲痒莫搔。","未嗟闻道晚，终待郢斤操。"]},{"t":"上运使苏大卿十六韵","f":"五言古诗","c":["当代推先正，斯文倚废兴。","表章逢圣主，衣钵见孙曾。","操履浑圭璧，行藏动准绳。","太羹元薄味，积水自增冰。","洛诵传瑰墨，鸡林织宝缯。","六卿聊率属，三事即延登。","一自双星出，重烦四牡乘。","周知民疾苦，密访吏贤能。","已见江西化，都为道院称。","夷涂终妥帖，揆路始飞腾。","后进思亲炙，今吾有服膺。","百年能几见，一语愿师承。","令弩方危脱，公堂许骤升。","暗中惭摸索，胸次漫崚嶒。","末俗惟同调，初心只自憎。","可能怜鸴鴳，随意亦鲲鹏。"]},{"t":"见提刑巩大监三十韵","f":"五言古诗","c":["夙借屏星映，曾怜坐客寒。","扁舟违逆水，方丈渺三韩。","分隔悬穹壤，心驰乏羽翰。","荧煌长在望，岁月凛奔湍。","凡骨思佺诀，师资待郢墁。","把文留箧笥，洗眼诵琅玕。","辙敢穷途恸，冠期结绶弹。","苦无苍玉佩，绝忆紫金丹。","往绝修门入，争先要路看。","飞腾宁有策，遇合自相欢。","献纳君王问，施行宇宙宽。","前星开尹幕，列宿炳朝端。","贺老聊为监，严公合从官。","调官因有便，典谒亦曾干。","不得瞻丰采，无由出肺肝。","姓名烦摸索，踪迹自蹒跚。","未有三千牍，那能九万抟。","抱关从苑候，失步向邯郸。","继忆专城去，俱兴敛惠叹。","第闻盘错旧，不见剸裁难。","帝眷从更治，民风要饱观。","甫传光礼乐，已著画衣冠。","浙水东西接，恩波昼夜澜。","去天邻杜曲，近日即长安。","儒腐真堪厌，才优特未殚。","少迟调鼎铉，即合侍金銮。","馀子甘流落，遗编守故残。","若为百里宰，已判一生酸。","蜀道游虽倦，山阴兴未阑。","犹能风雪里，作意驻征鞍。"]},{"t":"别毛质夫省宣抚丘同知访都督张知院十韵代简","f":"五言古诗","c":["交契三生在，违离百念休。","杜门烦枉驾，力疾喜登楼。","击节听高论，持杯散暮愁。","诸公争屈致，故里可淹留。","科第休云晚，行藏却自由。","安边须远略，造膝待前筹。","雨泊中川屿，风帆古括州。","知津君已熟，惜别我何忧。","京口留青眼，澄江正白头。","或纾知己问，已负杀身酬。"]},{"t":"太上皇后閤春帖子 其一","f":"五言绝句","c":["寿拟南山祝，春从北斗回。","物华欣向泰，厚德发生来。"]},{"t":"太上皇后閤春帖子 其二","f":"五言绝句","c":["母道齐皇极，韶光傍寿觞。","徽音家庆集，随辇奉尊章。"]},{"t":"太上皇后閤春帖子 其三","f":"五言绝句","c":["风帘回翡翠，冰研伴蟾蜍。","亲写迎春帖，真符太上书。"]},{"t":"太上閤端午帖子 其一","f":"五言绝句","c":["自得广成道，长居不老天。","底须桃辟恶，何用木延年。"]},{"t":"太上閤端午帖子 其二","f":"五言绝句","c":["人艾休教采，仙丹久养成。","六宫争结缕，再拜学长生。"]},{"t":"太上閤端午帖子 其三","f":"五言绝句","c":["柈献千年实，杯行九节蒲。","至尊亲上寿，家庆列成图。"]},{"t":"圣寿閤端午帖子 其一","f":"五言绝句","c":["有德天同寿，无为日更长。","每逢端午节，双上万年觞。"]},{"t":"圣寿閤端午帖子 其二","f":"五言绝句","c":["画扇迎双凤，轻衣拂六铢。","太清元有箓，抱朴不须符。"]},{"t":"圣寿閤端午帖子 其三","f":"五言绝句","c":["绕臂长生缕，当门五色丝。","榴花看结子，叶叶在孙枝。"]},{"t":"题惠崇小景 其一","f":"五言绝句","c":["寒林几吹折，冻柳不胜垂。","老去机心熟，惊鸥莫浪疑。"]},{"t":"题惠崇小景 其二","f":"五言绝句","c":["崔嵬吾肺腑，面目似庐山。","江上风涛稳，扁舟得往还。"]},{"t":"题惠崇小景 其三","f":"五言绝句","c":["舒徐春昼永，取次小桃红。","独爵把枝稳，矜呼立晚风。"]},{"t":"题惠崇小景 其四","f":"五言绝句","c":["两蛙随步武，先后得位置。","不作渴雨鸣，岂不贤鼓吹。"]},{"t":"题文与可山水","f":"五言绝句","c":["疏筱寒林手，文家富袜材。","片缣云气足，彷佛认蓬莱。"]},{"t":"题洪子恂所画盘洲图","f":"五言绝句","c":["林塘天遗得，花木地宜栽。","细纪平泉咏，挥毫落海苔。"]},{"t":"题车盘图","f":"五言绝句","c":["牛磨人俱转，车旋水即流。","争如霖雨足，所至息人牛。"]},{"t":"归牧图","f":"五言绝句","c":["爵禄不入心，牛肥了耕稼。","绿阴生晚烟，归来两閒暇。"]},{"t":"题水石翎毛","f":"五言绝句","c":["此君已可人，更著水石映。","水禽穿林来，相呼复相应。"]},{"t":"题边鲁生花木翎毛四首 其一","f":"五言绝句","c":["绿垂朱雀柳，双燕不胜春。","泥落空梁语，之人竟杀身。"]},{"t":"题边鲁生花木翎毛四首 其二","f":"五言绝句","c":["南国枇杷熟，卑枝结子多。","一双拖白练，飞堕绿林阿。"]},{"t":"题边鲁生花木翎毛四首 其三","f":"五言绝句","c":["小树生荆棘，棠梨结子幽。","白头双野鸟，相对菊花愁。"]},{"t":"题边鲁生花木翎毛四首 其四","f":"五言绝句","c":["梦断江南信，空怜铁石肠。","绿么何处去，二鸟独悲伤。"]},{"t":"赵昌芍药","f":"五言绝句","c":["风雨药栏西，残红落锦溪。","明窗时展卷，春色任提携。"]},{"t":"醒酒石","f":"五言绝句","c":["泽畔三生魄，花间独醒窠。","摩挲苔上醉，驱遣睡中魔。"]},{"t":"小垂手","f":"五言绝句","c":["醉里忘形客，山中化石仙。","翻同醒酒伴，作对媚平泉。"]},{"t":"云叶","f":"五言绝句","c":["何年老讲师，趺坐贝树根。","落云化为石，亦得无上尊。"]},{"t":"蜂窠石","f":"五言绝句","c":["水石两相激，成形不自藏。","终惭为兔窟，仅喜作蜂房。"]},{"t":"彩鹢","f":"五言绝句","c":["意适舟轻飏，夷犹杂雁凫。","不须凌弱水，乐地即蓬壶。"]},{"t":"采莲舟","f":"五言绝句","c":["拟倩谁家女，相呼去采莲。","丁宁欸乃曲，随意媚晴川。"]},{"t":"双溪堂","f":"五言绝句","c":["境与人俱胜，心无水共流。","奇奇仍怪怪，莫莫更休休。"]},{"t":"绿野堂","f":"五言绝句","c":["山坪萦雾草，湖泺漾烟芦。","野色谁延入，阴晴足画图。"]},{"t":"洗心阁","f":"五言绝句","c":["与物风迎浪，澄心月印湖。","床头不须易，本自一尘无。"]},{"t":"容膝斋","f":"五言绝句","c":["心胸包天地，人亦天地物。","莫笑容膝斋，空洞足伸屈。"]},{"t":"舣斋","f":"五言绝句","c":["心起五湖兴，身轻一叶舟。","个中风雨夜，不用转船头。"]},{"t":"楚望楼","f":"五言绝句","c":["楚东雄地望，胜槩属名流。","共俟谢安石，难追马少游。"]},{"t":"题有竹轩","f":"五言绝句","c":["家世岂孤竹，夷齐真二难。","清风与直节，一一耸高寒。"]},{"t":"题隐雾轩","f":"五言绝句","c":["豹变知非虎，磻溪若是班。","当年谢安石，只合住东山。"]},{"t":"题巢云轩","f":"五言绝句","c":["楚望巢云处，长怀曩寓居。","飘飘欲仙去，渺渺复愁予。"]},{"t":"芥纳寮","f":"五言绝句","c":["踞龟说漫游，视蚁谈绮梦。","芥内取须弥，撑桥寻月洞。"]},{"t":"灌园亭","f":"五言绝句","c":["植蔬常匝圃，酿酒仍满瓮。","便觉三公轻，更将德本种。"]},{"t":"次韵拔葵亭","f":"五言绝句","c":["拔葵固佳节，灌园宁素餐。","公归客无归，长铗且莫弹。"]},{"t":"题饭牛亭","f":"五言绝句","c":["好手聊饭牛，不将笏搢插。","所以百里奚，牛肥不枯乏。"]},{"t":"花信亭","f":"五言绝句","c":["播物潜施令，司花暗弄妆。","封姨偏漏泄，预报信前香。"]},{"t":"茧瓮亭","f":"五言绝句","c":["有家堪作茧，学圃甘抱瓮。","此生足三眠，以外均一梦。"]},{"t":"林珍亭","f":"五言绝句","c":["团坐听情语，移杯就果根。","分甘新更美，敲打任诸孙。"]},{"t":"题索笑亭 其一","f":"五言绝句","c":["江南气候宜，冷蕊破寒枝。","能共巡檐笑，何妨受雪吹。"]},{"t":"题索笑亭 其二","f":"五言绝句","c":["六出雪中宜，春藏向北枝。","巡檐时一笑，玉笛且休吹。"]},{"t":"橘友亭","f":"五言绝句","c":["梅溽香蒸玉，霜晴珠照林。","封君休僣儗，得此足投簪。"]},{"t":"题云起亭","f":"五言绝句","c":["云起有真意，水穷无尽心。","盘洲宁涸泽，天下要甘霖。"]},{"t":"欣对亭","f":"五言绝句","c":["万象尽森著，所观皆所欣。","谁能忘爱恶，达观足超群。"]},{"t":"既醉亭和韵","f":"五言绝句","c":["泛觞有何心，罚爵不为耻。","流行固自佳，坎止何妨醉。"]},{"t":"题可止亭","f":"五言绝句","c":["涧叠裴公石，杯形鸱子船。","乘流欣遇坎，结网胜临渊。"]},{"t":"美可茹亭","f":"五言绝句","c":["盘洲比盘谷，钓水鲜可烹。","采山独为乐，颇胜惩沸羹。"]},{"t":"琼报亭","f":"五言绝句","c":["园丁采时果，足以供嗜好。","眷言无尽藏，孰尽琼玖报。"]},{"t":"题睡足亭","f":"五言绝句","c":["唐皇溺太真，爱心苦未足。","因人忆海棠，何如悟秉烛。"]},{"t":"题咏亭","f":"五言绝句","c":["无尘元不禊，有酒即为春。","一咏得真趣，四时俱可人。"]},{"t":"棕亭","f":"五言绝句","c":["剥棕堪覆宇，代瓦胜诛茅。","有酒论奇字，无心赋解嘲。"]},{"t":"西户","f":"五言绝句","c":["勋业镜成斑，光阴箭能疾。","明时贳此翁，不须绳系日。"]},{"t":"月娥留照","f":"五言绝句","c":["长圆宜有缺，久晕讶无风。","留此一轮满，须知万古同。"]},{"t":"松阴溅瀑","f":"五言绝句","c":["松风翳漫漫，涧水声潺潺。","中有无尘公，飞鸣相往还。"]},{"t":"池塘小景","f":"五言绝句","c":["昨夜春水生，垂杨蘸波碧。","湖中相忘友，两两有鸂鶒。"]},{"t":"绿沉谷","f":"五言绝句","c":["黄尘满金谷，山阴尚脩竹。","所以盘洲景，未足趣已足。"]},{"t":"啸风岩","f":"五言绝句","c":["人言风从虎，风岂虎所出。","吹万生一虚，石兄故无物。"]},{"t":"泛杯岩","f":"五言绝句","c":["境佳因得水，洲窈故名盘。","引作流觞饮，岩边听激湍。"]},{"t":"题豹岩","f":"五言绝句","c":["奇峰疑地胜，勒驾恐山灵。","何止管中见，全窥文豹形。"]},{"t":"柞林","f":"五言绝句","c":["蓬蓬新叶盛，柞拔俨分行。","宁作非材栎，羞为傍路杨。"]},{"t":"芝径","f":"五言绝句","c":["辟谷几经尘，如芝今有神。","更开三益径，似恐太无邻。"]},{"t":"棠杕径","f":"五言绝句","c":["弟兄为师友，晚岁共三径。","室迩伫远思，东风吹鬓影。"]},{"t":"沃桑陌","f":"五言绝句","c":["种桑思采桑，蚕饥那可忍。","日暮寒女心，无衣犹反本。"]},{"t":"蓼岸","f":"五言绝句","c":["落水浮寒石，看痕记旧汀。","更寻红蓼岸，都有几鵁鶄。"]},{"t":"土湖","f":"五言绝句","c":["湖山远钟鼎，往往属田舍。","公自得盘洲，湖山买无价。"]},{"t":"九曲","f":"五言绝句","c":["九转多洄洑，觞行得演迤。","休将比金谷，除此只东篱。"]},{"t":"芝泉","f":"五言绝句","c":["人但千筒汲，谁知一线通。","泉今人惜重，走卒与儿童。"]},{"t":"瀑布","f":"五言绝句","c":["循崖瀑布悬，遇坎茶铛沸。","水哉斯何取，本者固如是。"]},{"t":"薝卜涧","f":"五言绝句","c":["结实黄金包，开花寒水玉。","香色俱可怜，采涧勿盈掬。"]},{"t":"濠上","f":"五言绝句","c":["观鱼要水清，爱鱼嫌芰剌。","能了濠上乐，处世何必避。"]},{"t":"鱼台","f":"五言绝句","c":["忍口嫌去乙，蓄池怜所丁。","故应濠上乐，不羡此湖醒。"]},{"t":"盘矶","f":"五言绝句","c":["新月当沈钩，香芹抵垂饵。","矶上坐移时，水清鱼自戏。"]},{"t":"鸂鶒濑","f":"五言绝句","c":["打鸭惊鸳起，忘鸥得鶒驯。","世间能去我，物外总输人。"]},{"t":"芡曲","f":"五言绝句","c":["湖边谁摘芡，轻度藕花风。","贪得鸿头去，惊他雁序空。"]},{"t":"菱湾","f":"五言绝句","c":["根随波共蔓，花更水相亲。","鱼跃翻成出，微光解照人。"]},{"t":"柳桥","f":"五言绝句","c":["眉展愁难画，腰纤怯系书。","过时低拂袖，谁遣飒轻裾。"]},{"t":"兑桥步洪韵","f":"五言绝句","c":["桥上所经过，秋成正乐郊。","儿童惊衮绣，丞相只衡茅。"]},{"t":"墨沼","f":"五言绝句","c":["积功墨成池，增价蒲为扇。","不作新样脚，一洗憔悴面。"]},{"t":"龟巢","f":"五言绝句","c":["藏六自为巢，巢莲岁久交。","支床犹耐辱，曳尾敢辞嘲。"]},{"t":"梦窟","f":"五言绝句","c":["枕上蘧蘧梦，胸中拍拍春。","从它身化蝶，谁复蝶为身。"]},{"t":"题柴桑园孤松","f":"五言绝句","c":["耻封秦爵五，逃辱若逃暑。","孤立柴桑园，出群谁敢伍。"]},{"t":"咏槐","f":"五言绝句","c":["槐绿复槐绿，时来人自忙。","处阴聊避影，岁月去堂堂。"]},{"t":"竹屋","f":"五言绝句","c":["爱苔无爱竹，戒勿长儿孙。","竹屋偏宜雪，何妨种满园。"]},{"t":"人面竹","f":"五言绝句","c":["共识此君面，谁知面目真。","清风犹立懦，奇节仰先民。"]},{"t":"猫头竹","f":"五言绝句","c":["迸穴穿篱出，狸奴知几头。","真能参玉版，足可当珍羞。"]},{"t":"慈竹","f":"五言绝句","c":["母子惟慈孝，心胸无棘荆。","斑衣供稚子，深觉负平生。"]},{"t":"木竹","f":"五言绝句","c":["品殊名亦殊，此君随藻鉴。","盘洲有木竹，收拾无一欠。"]},{"t":"方竹","f":"五言绝句","c":["峭节虚容物，清标直中绳。","杖有削圆厄，提携先模棱。"]},{"t":"石竹","f":"五言绝句","c":["干无筇九节，叶类柳三眠。","介若此君操，不因霜雪蔫。"]},{"t":"题笋","f":"五言绝句","c":["阿戎胜此君，解颐须折角。","玉版得细参，渭川成浪谑。"]},{"t":"割棕","f":"五言绝句","c":["赤身犹干固，秃节尚毛垂。","木也乃如此，人焉胡可窥。"]},{"t":"绿苔","f":"五言绝句","c":["土衣圆绿孕，屐齿孔方留。","莫扫钱留地，应嫌薏苡秋。"]},{"t":"芦花","f":"五言绝句","c":["见鹢恬徐退，看鸢喜讵飞。","飞芦欲何适，绕绿打红围。"]},{"t":"食蕨","f":"五言绝句","c":["掇芽无掘根，掘根芽必空。","乌糯亦彊名，安得隳农功。"]},{"t":"仙茅","f":"五言绝句","c":["旌阳仙去后，服饵有仙茅。","绝笑拖肠鼠，餐馀不系庖。"]},{"t":"黄精","f":"五言绝句","c":["白发终烦扫，黄精莫认花。","叶疑新竹箭，根类老姜芽。"]},{"t":"芷","f":"五言绝句","c":["银箸有生香，叶排元紫房。","更名歌九畹，课效万金方。"]},{"t":"药畹","f":"五言绝句","c":["种药怜苗润，分畦戒蔓滋。","休藏肘后法，医国是良图。"]},{"t":"对花果子","f":"五言绝句","c":["野华复结实，同在一枝上。","了知色即空，聊作因果相。"]},{"t":"朝天李","f":"五言绝句","c":["耻为钻核种，肯向道旁生。","中立不阿倚，惟存恋阙名。"]},{"t":"破核李","f":"五言绝句","c":["采实傍春山，成蹊邻露井。","和峤难责钱，计核破莫整。"]},{"t":"嘉庆子","f":"五言绝句","c":["名好实亦好，毡车自北来。","流传今转盛，见者莫惊猜。"]},{"t":"樱桃","f":"五言绝句","c":["苦笋恰相逢，匀圆得许红。","荐新存古意，驱鸟念园公。"]},{"t":"葡萄","f":"五言绝句","c":["架竹引龙须，时攀颔下珠。","欲求西域种，北使昔同符。"]},{"t":"绣橘","f":"五言绝句","c":["颂橘固多品，其贤知若干。","后皇偏著意，尔许绣团团。"]},{"t":"金橘","f":"五言绝句","c":["金橘大为贵，舂陵价倍增。","盘洲移得种，风味圣全能。"]},{"t":"罗柑","f":"五言绝句","c":["织文充革见，雾霭入怀香。","亦唤罗敷种，曾闻湘水乡。"]},{"t":"雪梨","f":"五言绝句","c":["似雪味能珍，肌肤雪后身。","花香还胜雪，未信雪如人。"]},{"t":"鹅梨","f":"五言绝句","c":["大谷固绝品，鹅梨亦遗味。","名园见似人，神皋花溅泪。"]},{"t":"绿萼梅","f":"五言绝句","c":["魂清萼绿华，望绝江南使。","天寒倚竹时，风标略相似。"]},{"t":"红梅","f":"五言绝句","c":["梅格依然在，诗家莫认桃。","纵烦金井水，终近楚人骚。"]},{"t":"黄香梅","f":"五言绝句","c":["多叶似太繁，浅装还越样。","格韵细题评，远出红梅上。"]},{"t":"长春花","f":"五言绝句","c":["平分为四序，长得作春看。","三友诚高品，兹花一岁寒。"]},{"t":"豆蔻花","f":"五言绝句","c":["二月拆芳苞，凡心比并交。","丁香多意绪，和月堕林梢。"]}]};